INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有钱", "is_correct": true, "explanation": "有钱：拥有许多钱财，即富裕。"}, {"text": "有闲", "is_correct": false, "explanation": "xián（第二声）与 qián（第二声）声母不同（x/q），意思是有空闲，不是有钱财。"}, {"text": "有权", "is_correct": false, "explanation": "quán 与 qián 介音不同（u/i），意思是有权力，不是有钱财。"}, {"text": "有情", "is_correct": false, "explanation": "qíng 与 qián 韵母不同（ing/ian），意思是有感情、有情义。"}], "explanations": {"有钱": "有钱：拥有许多钱财，即富裕。", "有闲": "xián（第二声）与 qián（第二声）声母不同（x/q），意思是有空闲，不是有钱财。", "有权": "quán 与 qián 介音不同（u/i），意思是有权力，不是有钱财。", "有情": "qíng 与 qián 韵母不同（ing/ian），意思是有感情、有情义。"}, "sentence_index": null, "correct_answer": "有钱"}, "level_3": {"options": [{"text": "有钱", "is_correct": true, "explanation": "“他家很有钱”中，“有钱”作谓语，描述一户人家经济富裕，语义和搭配都正确。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说智力，与“有钱”的经济含义不符。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”是人的心理表现，一户人家不会害羞。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说商品价格低，不能用来评价一户人家。"}], "explanations": {"有钱": "“他家很有钱”中，“有钱”作谓语，描述一户人家经济富裕，语义和搭配都正确。", "聪明": "语义：“聪明”说智力，与“有钱”的经济含义不符。", "害羞": "语义：“害羞”是人的心理表现，一户人家不会害羞。", "便宜": "搭配：“便宜”说商品价格低，不能用来评价一户人家。"}, "sentence_index": 0, "correct_answer": "有钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的生活很有钱。", "explanation": "这里应该用〈富裕〉。“有钱”说人或家庭手里的钱多，描写地区和生活水平要用“富裕”。"}, {"text": "农民的日子越来越有钱了。", "explanation": "这里应该用〈富足〉。“有钱”指个人或家庭的钱多，不用来描述日子、生活状况的充裕程度。"}, {"text": "他的精神世界很有钱。", "explanation": "这里应该用〈富有〉。“富有”可以用于精神世界、内容等抽象方面，“有钱”只指手里的钱多，不能用来形容精神世界。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有钱", "is_correct": true, "explanation": "有钱：手里的钱很多。"}, {"text": "有权", "is_correct": false, "explanation": "quán 与 qián 介音不同（u/i），意思是有权力。"}, {"text": "油钱", "is_correct": false, "explanation": "yóu（第二声）与 yǒu（第三声）声调不同，“油钱”指买油、加油的钱。"}, {"text": "右前", "is_correct": false, "explanation": "yòu（第四声）与 yǒu（第三声）声调不同，意思是右边的前方。"}], "explanations": {"有钱": "有钱：手里的钱很多。", "有权": "quán 与 qián 介音不同（u/i），意思是有权力。", "油钱": "yóu（第二声）与 yǒu（第三声）声调不同，“油钱”指买油、加油的钱。", "右前": "yòu（第四声）与 yǒu（第三声）声调不同，意思是右边的前方。"}, "sentence_index": null, "correct_answer": "有钱"}, "level_3": {"options": [{"text": "有钱", "is_correct": true, "explanation": "“住大房子的人，一定很有钱吗？”中，“有钱”与“住大房子”相呼应，表示经济状况，语义和搭配都正确。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不用来形容人。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场所或场面，不用来形容人。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”形容商品价格，不能用来形容人。"}], "explanations": {"有钱": "“住大房子的人，一定很有钱吗？”中，“有钱”与“住大房子”相呼应，表示经济状况，语义和搭配都正确。", "宽敞": "搭配：“宽敞”形容空间，不用来形容人。", "热闹": "搭配：“热闹”形容场所或场面，不用来形容人。", "便宜": "搭配：“便宜”形容商品价格，不能用来形容人。"}, "sentence_index": 6, "correct_answer": "有钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家酒店的大厅很有钱。", "explanation": "这里应该用〈豪华〉。“有钱”只说人或家庭手里钱多，不用来形容大厅的装修和档次。"}, {"text": "这位老教授的知识很有钱。", "explanation": "这里应该用〈渊博〉。“渊博”形容知识丰富，“有钱”只说手里的钱多，不能用来形容知识。"}, {"text": "这位老先生说话很有钱。", "explanation": "这里应该用〈幽默〉。“幽默”形容说话风趣，“有钱”只说人或家庭手里的钱多，不能用来形容说话的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅没很有钱，但是很快乐。", "corrected_sentence": "我舅舅不太有钱，但是很快乐。", "error_description": "错误在否定词：“有钱”作形容词谓语时，否定要用“不”，“没”不用于形容词谓语。“没很有钱”应改为“不太有钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的有钱，朋友很多。", "corrected_sentence": "他很有钱，朋友很多。", "error_description": "结构错误：“的”用在“有钱”前会把它变成定语，作谓语时应在前面加程度副词“很”。“他的有钱”应改为“他很有钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ec9804-5013-493b-b350-1068aecf33b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94951, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94951, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94951, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "未时是古时候一天中的下午一点到三点。", "primary_collocate": null, "pronunciation": "wèi shí", "ipa": "weɪ˥˩ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "古时候，未时是下午一点到三点。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书信里写着，他们约好未时在城东见面。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，未时的太阳最热。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写着，他未时才到家。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人说的未时，就是现在的下午。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在未时开了城门。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未时到了，大家都去休息。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前的日子里，未时突然下起了大雨。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老医生每天未时给人看病。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的店铺未时还开着。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "古代计时的一个时辰，下午一点到三点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94951, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未时", "is_correct": true, "explanation": "未时：古代一个时辰，指下午一点到三点，可以作“是”的主语。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：“午夜”指夜里，与“下午一点到三点”相矛盾。"}, {"text": "中饭", "is_correct": false, "explanation": "搭配：“中饭”指一餐，不能指一个时段。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”指早上，与“下午一点到三点”相矛盾。"}], "explanations": {"未时": "未时：古代一个时辰，指下午一点到三点，可以作“是”的主语。", "午夜": "语义：“午夜”指夜里，与“下午一点到三点”相矛盾。", "中饭": "搭配：“中饭”指一餐，不能指一个时段。", "清晨": "语义：“清晨”指早上，与“下午一点到三点”相矛盾。"}, "sentence_index": 0, "correct_answer": "未时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约在未时四点见面。", "explanation": "这里应该用〈下午四点〉。未时是一个时段（下午一点到三点），不能再说具体几点。"}, {"text": "我昨天未时吃了晚饭。", "explanation": "这里应该用〈傍晚〉。未时是下午一点到三点，“吃晚饭”一般在傍晚。"}, {"text": "未时的露水很多。", "explanation": "这里应该用〈清晨〉。未时是下午，露水多出现在清晨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未时", "is_correct": true, "explanation": "未时：指下午一点到三点的时段，可以作“到了”的主语。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：“黎明”是天刚亮的时候，人们正要起床干活，与“去休息”矛盾。"}, {"text": "日出", "is_correct": false, "explanation": "语义：“日出”指太阳升起的时刻，与“去休息”矛盾。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人的身体特征，不能作“到了”的时间主语。"}], "explanations": {"未时": "未时：指下午一点到三点的时段，可以作“到了”的主语。", "黎明": "语义：“黎明”是天刚亮的时候，人们正要起床干活，与“去休息”矛盾。", "日出": "语义：“日出”指太阳升起的时刻，与“去休息”矛盾。", "身高": "搭配：“身高”指人的身体特征，不能作“到了”的时间主语。"}, "sentence_index": 6, "correct_answer": "未时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "未时的星星很亮，照亮了夜路。", "explanation": "这里应该用〈夜晚〉。星星要在夜晚才亮，未时是白天的下午。"}, {"text": "未时的夕阳把天空染成了金色。", "explanation": "这里应该用〈黄昏〉。夕阳出现在傍晚，未时是下午一点到三点。"}, {"text": "古代的更夫未时敲响梆子，报告夜里的时辰。", "explanation": "这里应该用〈三更〉。更夫是夜里报时的，未时是下午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店未时三点才开门。", "corrected_sentence": "这家店未时才开门。", "error_description": "错误：“未时三点”。“未时”本身是一个时段，不能再加具体钟点，应为“未时才开门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他未时的回到城里。", "corrected_sentence": "他未时才回到城里。", "error_description": "错误：“未时的回到”。“回到”是动词，前面的时间词后直接接状语“才”，不用“的”，应为“未时才回到城里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
