INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94952, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧时计时的一个时辰，相当于下午一点到三点。", "primary_collocate": null, "pronunciation": "wèi shí", "ipa": "weɪ˥˩ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "旧时一个时辰两小时，未时在午后。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在未时出发，天黑前到了。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的人未时去了茶馆。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未时过了，她还没有回来。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，未时最适合睡午觉。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书里写，未时要关城门。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天未时练字。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从午时到未时，他一直在等。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未时的钟声响了三下。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "掌柜未时才吃午饭。", "target_word": "未时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "旧时十二时辰之一，相当于下午一点到三点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未时", "is_correct": true, "explanation": "未时：旧时十二时辰之一，相当于下午一点到三点，与“午后”相合。"}, {"text": "子时", "is_correct": false, "explanation": "语义：“子时”是午夜前后，与“午后”矛盾。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能指时辰。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”是早上，与“午后”矛盾。"}], "explanations": {"未时": "未时：旧时十二时辰之一，相当于下午一点到三点，与“午后”相合。", "子时": "语义：“子时”是午夜前后，与“午后”矛盾。", "身高": "搭配：“身高”不能指时辰。", "清晨": "语义：“清晨”是早上，与“午后”矛盾。"}, "sentence_index": 0, "correct_answer": "未时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "未时的晚霞把天空染红了。", "explanation": "这里应该用〈傍晚〉。晚霞出现在傍晚，未时是下午一点到三点。"}, {"text": "未时的日出十分壮观。", "explanation": "这里应该用〈清晨〉。日出在清晨，未时是下午。"}, {"text": "古代城门未时就实行宵禁。", "explanation": "这里应该用〈夜里〉。宵禁是夜间禁止通行，未时是下午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未时", "is_correct": true, "explanation": "未时：旧时计时的一个时辰，指下午一点到三点，可以作“每天”之后的时间词。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”指吃饭的多少，不能与“练字”搭配。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能作练字的时间。"}, {"text": "节假日", "is_correct": false, "explanation": "语义：“节假日”只在特定日子，与“每天”矛盾。"}], "explanations": {"未时": "未时：旧时计时的一个时辰，指下午一点到三点，可以作“每天”之后的时间词。", "饭量": "搭配：“饭量”指吃饭的多少，不能与“练字”搭配。", "身高": "搭配：“身高”不能作练字的时间。", "节假日": "语义：“节假日”只在特定日子，与“每天”矛盾。"}, "sentence_index": 6, "correct_answer": "未时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "未时的晨光洒满了窗台。", "explanation": "这里应该用〈清晨〉。晨光是清早的光，未时是下午一点到三点。"}, {"text": "未时的更鼓敲了三下。", "explanation": "这里应该用〈半夜〉。更鼓是夜里报时的，未时是下午。"}, {"text": "未时的萤火虫在草丛里闪亮。", "explanation": "这里应该用〈夜间〉。萤火虫夜里才明显，未时是下午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们未时晚上才出发。", "corrected_sentence": "他们未时才出发。", "error_description": "错误：“未时晚上”。“未时”是下午一点到三点，与“晚上”冲突，应只用“未时”，即“未时才出发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天未时三点在书房练字。", "corrected_sentence": "他每天未时在书房练字。", "error_description": "错误：“未时三点”。“未时”已是一个时段，不能再加具体钟点，应为“未时在书房练字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
