INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "标签是贴在东西上写字的小纸片。", "primary_collocate": null, "pronunciation": "biāo qiān", "ipa": "pjɑʊ˥ tɕʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "瓶子上贴着一张标签。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在每个盒子上都贴了标签。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在标签上写你的名字。", "target_word": "标签", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "标签掉了，我不知道这是谁的杯子。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用小标签分开不同的书。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张标签太小，写不下地址。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个书包贴上了标签。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水把标签上的字弄花了。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到笔，没法写标签。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李箱上有一张名字标签。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "小标签", "label": "复合"}, {"form": "标签纸", "label": "复合"}], "register": "中性", "sense_fingerprint": "贴在物品上用来写字的小纸片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标签", "is_correct": true, "explanation": "标签：贴在瓶子上、用来写字的小纸片，正是这里要的词，与“贴着”搭配。"}, {"text": "床单", "is_correct": false, "explanation": "语义：床单是铺在床上的大块布，不会贴在瓶子上。"}, {"text": "信", "is_correct": false, "explanation": "搭配：“信”的量词是“封”，不说“一张信”。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“雨伞”的量词是“把”，不说“一张雨伞”，雨伞也不会贴在瓶子上。"}], "explanations": {"标签": "标签：贴在瓶子上、用来写字的小纸片，正是这里要的词，与“贴着”搭配。", "床单": "语义：床单是铺在床上的大块布，不会贴在瓶子上。", "信": "搭配：“信”的量词是“封”，不说“一张信”。", "雨伞": "搭配：“雨伞”的量词是“把”，不说“一张雨伞”，雨伞也不会贴在瓶子上。"}, "sentence_index": 0, "correct_answer": "标签"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在地图上用红笔做了标签。", "explanation": "这里应该用〈标记〉。标签是贴在物品上写字的小纸片，在地图上做记号要用标记。"}, {"text": "店门口挂着一块巨大的标签，上面写着店名。", "explanation": "这里应该用〈招牌〉。标签是贴在物品上的小纸片，挂在店门口、写着店名的大牌子要用招牌。"}, {"text": "游行队伍举着写有“保护环境”的标签。", "explanation": "这里应该用〈标语〉。标签是贴在物品上写字的小纸片，游行时举的写着口号的横幅要用标语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标签", "is_correct": true, "explanation": "标签：贴在书包上、用来写字的纸片，老师给书包贴的正是它。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是挂在窗上的布，不会贴在书包上。"}, {"text": "膏药", "is_correct": false, "explanation": "语义：膏药是贴在身体上的药，不用来贴书包。"}, {"text": "墙纸", "is_correct": false, "explanation": "搭配：“贴墙纸”只说贴在墙面上，不说贴在书包上。"}], "explanations": {"标签": "标签：贴在书包上、用来写字的纸片，老师给书包贴的正是它。", "窗帘": "语义：窗帘是挂在窗上的布，不会贴在书包上。", "膏药": "语义：膏药是贴在身体上的药，不用来贴书包。", "墙纸": "搭配：“贴墙纸”只说贴在墙面上，不说贴在书包上。"}, "sentence_index": 6, "correct_answer": "标签"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我寄来一张标签，邀请我参加婚礼。", "explanation": "这里应该用〈请柬〉。标签是贴在物品上写字的小纸片，邀请宾客的卡片要用请柬。"}, {"text": "这家公司的标签是一只飞鸟。", "explanation": "这里应该用〈标志〉。标签是贴在物品上的纸片，公司的图案标识要用标志。"}, {"text": "他给我发来一张标签，通知我明天开会。", "explanation": "这里应该用〈通知〉。标签是贴在物品上写字的小纸片，告知开会时间的文书要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在行李上贴了一只标签。", "corrected_sentence": "他在行李上贴了一张标签。", "error_description": "“标签”是纸片，量词应为“张”，“只”不能用于纸片，应说“一张标签”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把名字写在标签，贴到了书包上。", "corrected_sentence": "老师把名字写在标签上，贴到了书包上。", "error_description": "“标签”是普通名词，表示处所时后面要加方位词“上”，应说“写在标签上”，不能说“写在标签”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
