INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "贴在物品上，注明名称、价格等的小纸条。", "primary_collocate": null, "pronunciation": "biāo qiān", "ipa": "pjɑʊ˥ tɕʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "这件衣服的标签上写着价格。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看一下标签上的名称和价格。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标签上说这瓶牛奶只能放三天。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的东西都有价格标签。", "target_word": "标签", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把标签撕下来，才穿新衣服。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买水果的时候，我先看标签。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标签上写着：三十八元。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标签贴歪了，价格看不清楚。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道这双鞋多少钱，可是标签掉了。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市工人正在给面包换新标签。", "target_word": "标签", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "价格标签", "label": "复合"}, {"form": "商品标签", "label": "复合"}], "register": "中性", "sense_fingerprint": "商品上注明名称、价格等信息的小纸条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标签", "is_correct": true, "explanation": "标签：这里指衣服上标注价格的小纸条，正确。"}, {"text": "扣子", "is_correct": false, "explanation": "语义：扣子是用来扣合衣服的，不用来写价格。"}, {"text": "口袋", "is_correct": false, "explanation": "搭配：“写着价格”要用在可以印字的纸片上，口袋上不说“写着价格”。"}, {"text": "拉链", "is_correct": false, "explanation": "语义：拉链是开合衣物的零件，上面不会标注价格。"}], "explanations": {"标签": "标签：这里指衣服上标注价格的小纸条，正确。", "扣子": "语义：扣子是用来扣合衣服的，不用来写价格。", "口袋": "搭配：“写着价格”要用在可以印字的纸片上，口袋上不说“写着价格”。", "拉链": "语义：拉链是开合衣物的零件，上面不会标注价格。"}, "sentence_index": 0, "correct_answer": "标签"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务台旁边的墙上贴着一张价格标签，列出了店里所有商品的价钱。", "explanation": "这里应该用〈价目表〉。价格标签贴在单件商品上，列出全店所有商品价钱的整张表要用价目表。"}, {"text": "这家饭馆的价格标签有三页。", "explanation": "这里应该用〈菜单〉。价格标签是贴在商品上标价的小纸条，饭馆里列出所有菜的多页清单要用菜单。"}, {"text": "饭后服务员递来一张价格标签。", "explanation": "这里应该用〈账单〉。价格标签贴在商品上标价，餐后结算的费用清单要用账单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标签", "is_correct": true, "explanation": "标签：贴在商品上、标注价钱的小纸条，正确。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是挂在窗上的布，不会标注价钱。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是戴在手上的物品，不会在上面写价钱。"}, {"text": "叶子", "is_correct": false, "explanation": "搭配：“写着三十八元”指商品标价，叶子不是商品，不搭配这样的说法。"}], "explanations": {"标签": "标签：贴在商品上、标注价钱的小纸条，正确。", "窗帘": "语义：窗帘是挂在窗上的布，不会标注价钱。", "手套": "语义：手套是戴在手上的物品，不会在上面写价钱。", "叶子": "搭配：“写着三十八元”指商品标价，叶子不是商品，不搭配这样的说法。"}, "sentence_index": 6, "correct_answer": "标签"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员胸前别着一张价格标签。", "explanation": "这里应该用〈工作牌〉。价格标签是贴在商品上标价的纸条，工作人员胸前标明身份的牌子要用工作牌。"}, {"text": "进门时，保安让我出示一张价格标签，证明我是学生。", "explanation": "这里应该用〈学生证〉。价格标签是贴在商品上标价的纸条，证明身份的证件要用学生证。"}, {"text": "朋友递给我一张价格标签，请我周末参加聚会。", "explanation": "这里应该用〈请柬〉。价格标签是贴在商品上标价的纸条，邀请客人的卡片要用请柬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件毛衣上有一只价格标签。", "corrected_sentence": "这件毛衣上有一张价格标签。", "error_description": "“价格标签”是纸片，量词应为“张”，“只”不用于纸片，应说“一张价格标签”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在价格标签看到了三十八元。", "corrected_sentence": "我在价格标签上看到了三十八元。", "error_description": "“价格标签”是普通名词，作处所时要加方位词“上”，应说“在价格标签上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
