INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94963, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没收是把别人不能有的东西拿走。", "primary_collocate": null, "pronunciation": "méi shōu", "ipa": "meɪ˧˥ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "老师没收了我的手机。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把我的游戏机没收了。", "target_word": "没收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课玩手机，老师会没收。", "target_word": "没收", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在考试时带小抄，老师没收了。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说要没收弟弟的玩具。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她上课看漫画书，老师把书没收了。", "target_word": "没收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生带零食进教室，老师就没收。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明玩游戏太久，妈妈没收了他的平板。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在课上传纸条，老师没收了纸条。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再玩手机，我就没收。", "target_word": "没收", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "没收了", "label": "体标"}, {"form": "没收过", "label": "体标"}], "register": "中性", "sense_fingerprint": "老师或家长把不该有的东西拿走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9844ebf-71c6-485b-8194-50a304b0844d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没收", "is_correct": true, "explanation": "没收：把别人不该有的东西拿走，符合句意。"}, {"text": "骂", "is_correct": false, "explanation": "配价：“骂”的对象应是人，不能说“骂手机”。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“手机”作宾语。"}, {"text": "祝贺", "is_correct": false, "explanation": "配价：“祝贺”的对象应是成功或喜事，不能用于手机。"}], "explanations": {"没收": "没收：把别人不该有的东西拿走，符合句意。", "骂": "配价：“骂”的对象应是人，不能说“骂手机”。", "游泳": "配价：“游泳”是不及物动词，不能带“手机”作宾语。", "祝贺": "配价：“祝贺”的对象应是成功或喜事，不能用于手机。"}, "sentence_index": 0, "correct_answer": "没收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生没收了老师的手机。", "explanation": "这里应该用〈借〉。没收是有管束权的人依规定拿走违规物品，学生拿走老师的手机不能说没收。"}, {"text": "他没收了一份奖学金。", "explanation": "这里应该用〈获得〉。没收表示把财物拿走、使人失去，他得到奖学金应说获得。"}, {"text": "老师没收了那个调皮的学生。", "explanation": "这里应该用〈带走〉。没收的对象只能是物品，人不能被没收，老师把学生带出教室应说带走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没收", "is_correct": true, "explanation": "没收：学生带零食进教室，老师依规定把零食拿走，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：老师唱歌与学生违规带零食的后果无关，句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：零食不能直接用“喝”来处理，老师就喝与语境不符。"}, {"text": "表扬", "is_correct": false, "explanation": "配价：“表扬”需要带受事，单独说“老师就表扬”不完整，且与违规的语境相反。"}], "explanations": {"没收": "没收：学生带零食进教室，老师依规定把零食拿走，符合句意。", "唱": "语义：老师唱歌与学生违规带零食的后果无关，句意不通。", "喝": "语义：零食不能直接用“喝”来处理，老师就喝与语境不符。", "表扬": "配价：“表扬”需要带受事，单独说“老师就表扬”不完整，且与违规的语境相反。"}, "sentence_index": 6, "correct_answer": "没收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈没收了我的游戏时间。", "explanation": "这里应该用〈取消〉。没收的对象须是具体物品，游戏时间是抽象的，不能说没收。"}, {"text": "暴雨没收了我们的雨伞。", "explanation": "这里应该用〈毁坏〉。没收是依规定把东西拿走，暴雨只能毁坏雨伞，不能用没收。"}, {"text": "学生没收了这个秘密。", "explanation": "这里应该用〈守住〉。没收的对象是财物，秘密不能被没收，应说守住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师被没收了小华的手机。", "corrected_sentence": "老师没收了小华的手机。", "error_description": "被动标记错误：“没收”的施事是“老师”，不能在它前面加“被”。正确说法是“老师没收了小华的手机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把小明的漫画书没收。", "corrected_sentence": "老师把小明的漫画书没收了。", "error_description": "把字句错误：动词“没收”后缺少“了”，“把”字句的谓语需带成分，应为“老师把小明的漫画书没收了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
