INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94964, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依法把违禁物品或非法所得收归公有。", "primary_collocate": null, "pronunciation": "méi shōu", "ipa": "meɪ˧˥ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "海关没收了他带的违禁品。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院没收了他的非法所得。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府依法没收了这批假药。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他卖假货赚的钱，法院全部没收。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院决定没收他的全部非法财产。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海关把走私的香烟全部没收了。", "target_word": "没收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违法所得要全部没收，上交国家。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察查到毒品，当场就没收了。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "安检人员发现违禁物品，会依法没收。", "target_word": "没收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院判他坐牢，还要没收他的非法所得。", "target_word": "没收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没收了", "label": "体标"}, {"form": "没收过", "label": "体标"}], "register": "书面", "sense_fingerprint": "国家机关依法把违禁品或非法所得收归公有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9844ebf-71c6-485b-8194-50a304b0844d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没收", "is_correct": true, "explanation": "没收：海关依法把违禁品收归公有，符合句意。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：海关把违禁品赠送给他，与“依法查处”的语境矛盾。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：海关把违禁品收藏起来不合常理，与执法语境冲突。"}, {"text": "祝贺", "is_correct": false, "explanation": "配价：“祝贺”的对象应是成功或喜事，不能用于违禁品。"}], "explanations": {"没收": "没收：海关依法把违禁品收归公有，符合句意。", "赠送": "语义：海关把违禁品赠送给他，与“依法查处”的语境矛盾。", "收藏": "语义：海关把违禁品收藏起来不合常理，与执法语境冲突。", "祝贺": "配价：“祝贺”的对象应是成功或喜事，不能用于违禁品。"}, "sentence_index": 0, "correct_answer": "没收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司没收了这批不合格的产品。", "explanation": "这里应该用〈收回〉。没收必须由有权机关依法执行，公司收回自己的不合格产品应说收回。"}, {"text": "他没收了一笔奖金。", "explanation": "这里应该用〈获得〉。没收表示财物被依法收归公有、使人失去，他得到奖金应说获得。"}, {"text": "法院没收了那个被告。", "explanation": "这里应该用〈审判〉。没收的对象只能是违禁物品或非法所得，人不能被没收，法院对被告应说审判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没收", "is_correct": true, "explanation": "没收：违法所得依法收归国家，符合句意。"}, {"text": "发还", "is_correct": false, "explanation": "语义：“发还”是退还原主，与“上交国家”的语境矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "配价：“表扬”需要带受事，且“违法所得要全部表扬”不成立。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：违法所得赠送给别人，与“上交国家”的句意矛盾。"}], "explanations": {"没收": "没收：违法所得依法收归国家，符合句意。", "发还": "语义：“发还”是退还原主，与“上交国家”的语境矛盾。", "表扬": "配价：“表扬”需要带受事，且“违法所得要全部表扬”不成立。", "赠送": "语义：违法所得赠送给别人，与“上交国家”的句意矛盾。"}, "sentence_index": 6, "correct_answer": "没收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海关没收了他的健康。", "explanation": "这里应该用〈损害〉。没收的对象须是财物或非法所得，健康不能被没收。"}, {"text": "地震没收了我们的房子。", "explanation": "这里应该用〈毁坏〉。没收是依法收归公有，地震只能毁坏房子，不能用没收。"}, {"text": "法院没收了他的名誉。", "explanation": "这里应该用〈损害〉。没收的对象只能是财物或非法所得，名誉是无形的，不能被没收。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海关被没收了走私香烟。", "corrected_sentence": "海关没收了走私香烟。", "error_description": "被动标记错误：“没收”的施事是“海关”，不能在它前面加“被”。正确说法是“海关没收了走私香烟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院依法把他的违法所得没收。", "corrected_sentence": "法院依法把他的违法所得没收了。", "error_description": "把字句错误：动词“没收”后缺少“了”，“把”字句的谓语需带成分，应为“法院依法把他的违法所得没收了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746e8ceb-58e7-40b0-a07d-a29ffe73e13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
