INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94965, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没种是胆子小，不敢做。", "primary_collocate": null, "pronunciation": "méi zhǒng", "ipa": "mei˧˥ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "你怎么这么没种，不敢去说？", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太没种了，连话都不敢说。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说他没种。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不是没种，只是现在不想去。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别那么没种，试一试吧。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见大狗就跑，真没种。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不敢去，就是没种。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说我没种，可我只是太累了。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁说我没种？我现在就去。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很没种，什么事都不敢做。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没種", "label": "繁体"}], "register": "口语", "sense_fingerprint": "胆子小，不敢去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没种", "is_correct": true, "explanation": "没种：胆子小、不敢做，与“不敢去说”的语境一致。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说的是智力，与“不敢去说”的胆怯相矛盾。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”形容整洁，不能用来形容一个人的胆量。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不能用来说明一个人的胆量。"}], "explanations": {"没种": "没种：胆子小、不敢做，与“不敢去说”的语境一致。", "聪明": "语义：“聪明”说的是智力，与“不敢去说”的胆怯相矛盾。", "干净": "搭配：“干净”形容整洁，不能用来形容一个人的胆量。", "漂亮": "搭配：“漂亮”形容外貌，不能用来说明一个人的胆量。"}, "sentence_index": 0, "correct_answer": "没种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很没种，从不说谎。", "explanation": "这里应该用〈诚实〉。没种形容胆子小、不敢做事，不用来说一个人是否诚实。"}, {"text": "我奶奶很没种，从不乱花钱。", "explanation": "这里应该用〈节俭〉。没种说的是胆量，不能用来形容节约。"}, {"text": "店主很没种，主动帮我们找座位。", "explanation": "这里应该用〈热情〉。没种指没有胆量，与主动、热情待客的行为矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没种", "is_correct": true, "explanation": "没种：没有胆量，与“不敢去”以及“就是”后面的判断一致。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：幽默指说话风趣，与“不敢去”的胆怯无关，不能这样评价。"}, {"text": "精明", "is_correct": false, "explanation": "语义：精明指聪明会算计，与“不敢去”的胆怯相矛盾。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容事物排列得有条理，不能用来形容一个人的胆量。"}], "explanations": {"没种": "没种：没有胆量，与“不敢去”以及“就是”后面的判断一致。", "幽默": "语义：幽默指说话风趣，与“不敢去”的胆怯无关，不能这样评价。", "精明": "语义：精明指聪明会算计，与“不敢去”的胆怯相矛盾。", "整齐": "搭配：“整齐”形容事物排列得有条理，不能用来形容一个人的胆量。"}, "sentence_index": 6, "correct_answer": "没种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很没种，常常请朋友吃饭。", "explanation": "这里应该用〈慷慨〉。没种说的是没有胆量，不能用来形容大方请客。"}, {"text": "这个孩子很没种，学习很快。", "explanation": "这里应该用〈聪明〉。没种指胆子小，不能用来说一个人学得快。"}, {"text": "他很没种，讲的笑话大家都爱听。", "explanation": "这里应该用〈幽默〉。没种指没有胆量，不能用来形容讲笑话风趣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他太的没种了，连狗都不敢碰。", "corrected_sentence": "他太没种了，连狗都不敢碰。", "error_description": "错误：程度副词“太”后多加了“的”。“太”直接修饰形容词，中间不能加“的”。正确应为“太没种了”，去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很的没种，连话都不敢说。", "corrected_sentence": "他很没种，连话都不敢说。", "error_description": "错误：程度副词“很”后多加了“的”。“很”直接修饰形容词，中间不能加“的”。正确应为“他很没种，连话都不敢说。”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
