INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94966, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有胆量，懦弱。", "primary_collocate": null, "pronunciation": "méi zhǒng", "ipa": "mei˧˥ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是个没种的男人。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得前男友太没种了。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难就逃跑，真没种。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很没种，不敢承认错误。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人打了人又跑了，真没种。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最看不起没种的人。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前他不敢上台，朋友说他没种。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你就这么没种吗？", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩子不能没种。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被人骂了也不敢说话，大家都觉得他没种。", "target_word": "没种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没種", "label": "繁体"}], "register": "口语", "sense_fingerprint": "没有胆量，性格懦弱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9338e44a-02f0-4ff6-8511-9734bc7b6a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没种", "is_correct": true, "explanation": "没种：没有胆量、懦弱，与“男人”搭配，句子通顺。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，不能用来形容一个男人的性格。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容一个人的性格。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“湿”形容物体或天气，不用于描述男人的性格。"}], "explanations": {"没种": "没种：没有胆量、懦弱，与“男人”搭配，句子通顺。", "圆": "语义：“圆”形容形状，不能用来形容一个男人的性格。", "咸": "语义：“咸”形容味道，不能用来形容一个人的性格。", "湿": "搭配：“湿”形容物体或天气，不用于描述男人的性格。"}, "sentence_index": 0, "correct_answer": "没种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很没种，常常帮助邻居。", "explanation": "这里应该用〈善良〉。没种指胆量不足，不能用来形容人的品德。"}, {"text": "老师很没种，学生都怕他。", "explanation": "这里应该用〈严肃〉。没种说的是没有胆量，不能用来形容一个人的神情或作风。"}, {"text": "他性格没种，喜欢请大家喝酒。", "explanation": "这里应该用〈豪爽〉。没种指没有胆量，与豪爽的性格相反，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没种", "is_correct": true, "explanation": "没种：没有胆量，与“不敢上台”的情况一致，朋友的评价合理。"}, {"text": "健康", "is_correct": false, "explanation": "语义：健康指身体状况好，不能用来评价一个人的胆量，与“不敢上台”不符。"}, {"text": "友好", "is_correct": false, "explanation": "语义：友好指待人和气，与“不敢上台”的胆怯无关，不能这样评价。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容事物排列有条理，不能用来评价一个人的胆量。"}], "explanations": {"没种": "没种：没有胆量，与“不敢上台”的情况一致，朋友的评价合理。", "健康": "语义：健康指身体状况好，不能用来评价一个人的胆量，与“不敢上台”不符。", "友好": "语义：友好指待人和气，与“不敢上台”的胆怯无关，不能这样评价。", "整齐": "搭配：“整齐”形容事物排列有条理，不能用来评价一个人的胆量。"}, "sentence_index": 6, "correct_answer": "没种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很没种，每天学习到很晚。", "explanation": "这里应该用〈努力〉。没种指没有胆量，不能用来形容一个人学习刻苦。"}, {"text": "她很没种，衣服总是干干净净的。", "explanation": "这里应该用〈整洁〉。没种说的是胆子小，不能用来形容衣着干净。"}, {"text": "老师很没种，一遍一遍地讲题。", "explanation": "这里应该用〈耐心〉。没种指没有胆量，不能用来形容讲解时的耐心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他太的没种了，连夜里一个人走路都怕。", "corrected_sentence": "他太没种了，连夜里一个人走路都怕。", "error_description": "错误：程度副词“太”后多加了“的”。“太”直接修饰形容词，中间不能加“的”。正确应为“太没种了”，去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很的没种，被人骂了也不敢说话。", "corrected_sentence": "他很没种，被人骂了也不敢说话。", "error_description": "错误：程度副词“很”后多加了“的”。“很”直接修饰形容词，中间不能加“的”。正确应为“他很没种，被人骂了也不敢说话。”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babba5e0-0b28-42d0-8f55-614438535d6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
