INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94967, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "存在于事物内部、现在还看不出来的。", "primary_collocate": null, "pronunciation": "qián zài", "ipa": "t͡ɕʰjɛn˧˥ t͡saɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这里有潜在的危险。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很大的潜在能力。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小问题可能带来潜在的麻烦。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他表面不动声色，心里潜在的怒气没人看得出来。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子身上有很多潜在的才能。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现了他潜在的优点。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个市场有潜在的力量。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先看看潜在的风险。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没发现潜在的问题。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是个有潜在价值的想法。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜在的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "藏在里面、现在还看不出来的（多作定语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94967, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "潜在", "is_correct": true, "explanation": "潜在（qián zài）：藏着，现在还看不出来。"}, {"text": "前菜", "is_correct": false, "explanation": "前菜（qiáncài）与“潜在”第二音节声母不同（c 与 z），意思是正餐前的小吃。"}, {"text": "连载", "is_correct": false, "explanation": "连载（liánzài）与“潜在”第一音节声母不同（l 与 q），意思是分期陆续刊登。"}, {"text": "闲在", "is_correct": false, "explanation": "闲在（xiánzài）与“潜在”第一音节声母不同（x 与 q），意思是悠闲自在。"}], "explanations": {"潜在": "潜在（qián zài）：藏着，现在还看不出来。", "前菜": "前菜（qiáncài）与“潜在”第二音节声母不同（c 与 z），意思是正餐前的小吃。", "连载": "连载（liánzài）与“潜在”第一音节声母不同（l 与 q），意思是分期陆续刊登。", "闲在": "闲在（xiánzài）与“潜在”第一音节声母不同（x 与 q），意思是悠闲自在。"}, "sentence_index": null, "correct_answer": "潜在"}, "level_3": {"options": [{"text": "潜在", "is_correct": true, "explanation": "潜在：指藏着、现在还看不出来，可以修饰“危险”。"}, {"text": "安全", "is_correct": false, "explanation": "语义：“安全”与“危险”意思相反，“安全的危险”自相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型，不能修饰“危险”。"}, {"text": "坚固", "is_correct": false, "explanation": "搭配：“坚固”说物体结实，不能修饰“危险”。"}], "explanations": {"潜在": "潜在：指藏着、现在还看不出来，可以修饰“危险”。", "安全": "语义：“安全”与“危险”意思相反，“安全的危险”自相矛盾。", "高大": "搭配：“高大”形容体型，不能修饰“危险”。", "坚固": "搭配：“坚固”说物体结实，不能修饰“危险”。"}, "sentence_index": 0, "correct_answer": "潜在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手上潜在的伤口正在流血，大家都看得见。", "explanation": "这里应该用〈明显〉。潜在指藏着、现在还看不出来，而“正在流血，大家都看得见”说明伤口是明显的。"}, {"text": "昨天潜在的事故造成了很大损失。", "explanation": "这里应该用〈已经发生的〉。潜在指尚未显现，而昨天的事故已经发生并显现出来。"}, {"text": "窗外潜在的月光很亮。", "explanation": "这里应该用〈明亮的〉。潜在指藏着、看不出来，而“很亮”说明月光已经看得见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94967, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "潜在", "is_correct": true, "explanation": "潜在（qián zài）：藏着，现在还看不出来。"}, {"text": "前代", "is_correct": false, "explanation": "前代（qiándài）与“潜在”第二音节声母不同（d 与 z），意思是前朝。"}, {"text": "前债", "is_correct": false, "explanation": "前债（qiánzhài）与“潜在”第二音节声母不同（zh 与 z），意思是以前欠下的债。"}, {"text": "千载", "is_correct": false, "explanation": "千载（qiānzǎi）与“潜在”声母韵母相同、声调不同（qiān/qián，zǎi/zài），意思是千年。"}], "explanations": {"潜在": "潜在（qián zài）：藏着，现在还看不出来。", "前代": "前代（qiándài）与“潜在”第二音节声母不同（d 与 z），意思是前朝。", "前债": "前债（qiánzhài）与“潜在”第二音节声母不同（zh 与 z），意思是以前欠下的债。", "千载": "千载（qiānzǎi）与“潜在”声母韵母相同、声调不同（qiān/qián，zǎi/zài），意思是千年。"}, "sentence_index": null, "correct_answer": "潜在"}, "level_3": {"options": [{"text": "潜在", "is_correct": true, "explanation": "潜在：指藏着、还没有显现，正好修饰“力量”。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”与“有……的力量”意思相矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材体型，不能修饰“力量”。"}, {"text": "空荡", "is_correct": false, "explanation": "搭配：“空荡”说空间里没有东西，不能修饰“力量”。"}], "explanations": {"潜在": "潜在：指藏着、还没有显现，正好修饰“力量”。", "冷清": "语义：“冷清”与“有……的力量”意思相矛盾。", "矮小": "体貌：“矮小”形容身材体型，不能修饰“力量”。", "空荡": "搭配：“空荡”说空间里没有东西，不能修饰“力量”。"}, "sentence_index": 6, "correct_answer": "潜在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在会上潜在的道歉让大家很感动。", "explanation": "这里应该用〈公开〉。潜在指藏着、看不出来，而在会上当众道歉是公开进行的。"}, {"text": "人群里他潜在的红衣服格外显眼。", "explanation": "这里应该用〈醒目〉。潜在指藏着、看不出来，而“格外显眼”说明衣服是露在外面、看得见的。"}, {"text": "他潜在的喊叫让大家都听见了。", "explanation": "这里应该用〈大声〉。潜在指藏着、看不出来，而“让大家都听见”说明声音是显露的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_va