INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们发现了一个潜在地问题。", "corrected_sentence": "我们发现了一个潜在的问题。", "error_description": "错误：“潜在地问题”。“潜在”是形容词，修饰名词时应用结构助词“的”，不能用“地”，应为“潜在的问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
