INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94968, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "存在于内部、尚未显现出来的。", "primary_collocate": null, "pronunciation": "qián zài", "ipa": "t͡ɕʰjɛn˧˥ t͡saɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她身上潜在的天赋还没有表现出来。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法有潜在的缺点。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的潜在实力很强。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司看到了潜在的机会。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区有潜在的好处。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想到潜在的困难。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子前，要看清潜在的问题。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队里有不少潜在的好球员。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病有潜在的原因。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有潜在的领导能力。", "target_word": "潜在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜在的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "存在于内部、还没有表现出来的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab8815-7ec2-46b3-9bde-62defb4a82b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94968, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "潜在", "is_correct": true, "explanation": "潜在（qián zài）：存在于内部，尚未显现出来。"}, {"text": "连载", "is_correct": false, "explanation": "连载（liánzài）与“潜在”第一音节声母不同（l 与 q），意思是分期陆续刊登。"}, {"text": "闲在", "is_correct": false, "explanation": "闲在（xiánzài）与“潜在”第一音节声母不同（x 与 q），意思是悠闲自在。"}, {"text": "前代", "is_correct": false, "explanation": "前代（qiándài）与“潜在”第二音节声母不同（d 与 z），意思是前朝。"}], "explanations": {"潜在": "潜在（qián zài）：存在于内部，尚未显现出来。", "连载": "连载（liánzài）与“潜在”第一音节声母不同（l 与 q），意思是分期陆续刊登。", "闲在": "闲在（xiánzài）与“潜在”第一音节声母不同（x 与 q），意思是悠闲自在。", "前代": "前代（qiándài）与“潜在”第二音节声母不同（d 与 z），意思是前朝。"}, "sentence_index": null, "correct_answer": "潜在"}, "level_3": {"options": [{"text": "潜在", "is_correct": true, "explanation": "潜在：存在于内部、还没有表现出来，可以修饰“天赋”。"}, {"text": "明显", "is_correct": false, "explanation": "语义：“明显”指看得出来，与“还没有表现出来”矛盾。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容身体，不能修饰“天赋”。"}, {"text": "外露", "is_correct": false, "explanation": "语义：“外露”指显露在外，与“还没有表现出来”矛盾。"}], "explanations": {"潜在": "潜在：存在于内部、还没有表现出来，可以修饰“天赋”。", "明显": "语义：“明显”指看得出来，与“还没有表现出来”矛盾。", "瘦小": "体貌：“瘦小”形容身体，不能修饰“天赋”。", "外露": "语义：“外露”指显露在外，与“还没有表现出来”矛盾。"}, "sentence_index": 0, "correct_answer": "潜在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙角潜在的裂缝一眼就能看见。", "explanation": "这里应该用〈明显〉。潜在指藏着、现在还看不出来，而“一眼就能看见”正好相反。"}, {"text": "这份合同潜在的条款已经写在纸上。", "explanation": "这里应该用〈写明的〉。潜在指藏着、看不出来，而条款已经写在纸上，是看得见的。"}, {"text": "大路边潜在的广告牌很显眼。", "explanation": "这里应该用〈醒目的〉。潜在指藏着、看不出来，而“很显眼”说明广告牌已经露在外面了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94968, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "潜在", "is_correct": true, "explanation": "潜在（qián zài）：存在于内部，尚未显现出来。"}, {"text": "前菜", "is_correct": false, "explanation": "前菜（qiáncài）与“潜在”第二音节声母不同（c 与 z），意思是正餐前的小吃。"}, {"text": "前债", "is_correct": false, "explanation": "前债（qiánzhài）与“潜在”第二音节声母不同（zh 与 z），意思是以前欠下的债。"}, {"text": "千载", "is_correct": false, "explanation": "千载（qiānzǎi）与“潜在”声母韵母相同、声调不同，意思是千年。"}], "explanations": {"潜在": "潜在（qián zài）：存在于内部，尚未显现出来。", "前菜": "前菜（qiáncài）与“潜在”第二音节声母不同（c 与 z），意思是正餐前的小吃。", "前债": "前债（qiánzhài）与“潜在”第二音节声母不同（zh 与 z），意思是以前欠下的债。", "千载": "千载（qiānzǎi）与“潜在”声母韵母相同、声调不同，意思是千年。"}, "sentence_index": null, "correct_answer": "潜在"}, "level_3": {"options": [{"text": "潜在", "is_correct": true, "explanation": "潜在：指藏着、还没有显现，可以修饰“问题”。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容身材，不能修饰“问题”。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容空间，不能修饰“问题”。"}, {"text": "圆形", "is_correct": false, "explanation": "体貌：“圆形”描述物体的形状，不能修饰“问题”。"}], "explanations": {"潜在": "潜在：指藏着、还没有显现，可以修饰“问题”。", "苗条": "体貌：“苗条”形容身材，不能修饰“问题”。", "辽阔": "搭配：“辽阔”形容空间，不能修饰“问题”。", "圆形": "体貌：“圆形”描述物体的形状，不能修饰“问题”。"}, "sentence_index": 6, "correct_answer": "潜在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子潜在的哭声把全家都吵醒了。", "explanation": "这里应该用〈大声〉。潜在指藏着、看不出来，而“吵醒了全家”说明声音很明显。"}, {"text": "房间里潜在的灯火很亮，大家都看得见。", "explanation": "这里应该用〈明亮的〉。潜在指藏着、看不出来，而“大家都看得见”说明灯火是显露的。"}, {"text": "他脸上潜在的笑容，所有人都看在眼里。", "explanation": "这里应该用〈明显的〉。潜在指藏着、看不出来，而“所有人都看在眼里”说明笑容是显露的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合同里有潜在地纠纷。", "corrected_sentence": "这份合同里有潜在的纠纷。", "error_description": "错误：“潜在地纠纷”。“潜在”修饰名词时用“的”，不用“地”，应为“潜在的纠纷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器有潜在的。", "corrected_sentence": "这台机器有潜在的故障。", "error_description": "错误：“潜在的。”“潜在”是形容词，后面必须接被修饰的名词，应补上“故障”，即“潜在的故障”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b85754-4e02-48ba-91d9-02715c9bae66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
