INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94969, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "灾害是下大雨、地震这样让人受伤的事。", "primary_collocate": null, "pronunciation": "zāi hài", "ipa": "tsaɪ̯˥ xaɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "地震是一种很可怕的灾害。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方常常发生灾害，人们很小心。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨带来了灾害，很多人没有家了。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是灾害。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到灾害时，我们要先保护自己。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说那个城市遭受了灾害。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到灾害的消息，他马上给家里打电话。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾害过去以后，大家一起修房子。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校每年都做灾害演习。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡去年有大灾害，很多路都坏了。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "災害", "label": "繁体"}], "register": "中性", "sense_fingerprint": "下大雨、地震等让人受伤的坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01a5a511-643b-455f-a743-1f7bb54c8652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94969, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "节日", "is_correct": false, "explanation": "语义：地震是灾难，节日不是可怕的事，句意不通。"}, {"text": "灾害", "is_correct": true, "explanation": "正确。灾害指地震这类让人受伤的事，与“很可怕”相配。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：地震是自然现象，不是食品，不能说是一种饼干。"}, {"text": "乐趣", "is_correct": false, "explanation": "搭配：“可怕”修饰灾难、疾病等，不修饰“乐趣”。"}], "explanations": {"节日": "语义：地震是灾难，节日不是可怕的事，句意不通。", "灾害": "正确。灾害指地震这类让人受伤的事，与“很可怕”相配。", "饼干": "语义：地震是自然现象，不是食品，不能说是一种饼干。", "乐趣": "搭配：“可怕”修饰灾难、疾病等，不修饰“乐趣”。"}, "sentence_index": 0, "correct_answer": "灾害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天高速公路上出了一起大灾害，两辆车都撞坏了。", "explanation": "这里应该用〈事故〉。灾害指地震、大水这类大范围的损害，车祸这种交通意外要用“事故”。"}, {"text": "他的婚礼很顺利，这场灾害让他很开心。", "explanation": "这里应该用〈喜事〉。灾害指造成大范围损害的事，婚礼这样的好事要用“喜事”。"}, {"text": "他在路上遇到了一次灾害，所幸没有受伤。", "explanation": "这里应该用〈意外〉。灾害指造成大范围损害的事，个人路上遇到的小意外要用“意外”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐器", "is_correct": false, "explanation": "语义：“消息”的内容应是事件，乐器不是需要马上告诉家里的事，句意不通。"}, {"text": "灯笼", "is_correct": false, "explanation": "语义：灯笼是物品，不是他会马上打电话告诉家里的事。"}, {"text": "灾害", "is_correct": true, "explanation": "正确。“灾害”是消息的内容，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“消息”前面常接事件或情况，“颜色”不搭配“消息”。"}], "explanations": {"乐器": "语义：“消息”的内容应是事件，乐器不是需要马上告诉家里的事，句意不通。", "灯笼": "语义：灯笼是物品，不是他会马上打电话告诉家里的事。", "灾害": "正确。“灾害”是消息的内容，符合句意。", "颜色": "搭配：“消息”前面常接事件或情况，“颜色”不搭配“消息”。"}, "sentence_index": 6, "correct_answer": "灾害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年得了一种灾害，住了三个月医院。", "explanation": "这里应该用〈疾病〉。灾害指大范围的损害，个人患病要用“疾病”。"}, {"text": "两家公司因为合同发生了灾害，最后打了官司。", "explanation": "这里应该用〈纠纷〉。灾害指地震、大水等造成的损害，合同争议要用“纠纷”。"}, {"text": "两个人因为小事发生了灾害，后来和好了。", "explanation": "这里应该用〈争吵〉。灾害指造成大面积损害的事，口角要用“争吵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只灾害让很多人失去了家。", "corrected_sentence": "这场灾害让很多人失去了家。", "error_description": "“灾害”指一次事件，量词应用“场”。“这只灾害”用了动物量词“只”，应改为“这场灾害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场严重地灾害毁了很多房子。", "corrected_sentence": "那场严重的灾害毁了很多房子。", "error_description": "“灾害”是名词，前面的修饰语要用“的”；“严重地灾害”误用了“地”，应改为“严重的灾害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
