INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然现象或人为原因造成的损害，如水灾、旱灾等。", "primary_collocate": null, "pronunciation": "zāi hài", "ipa": "tsaɪ̯˥ xaɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "水灾和旱灾都是严重的灾害。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林大火是人为造成的灾害。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场灾害让农民损失了很多粮食。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱引起的灾害影响了全省的粮食。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在想办法减少灾害带来的损失。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震这样的灾害，很难提前知道。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家提醒大家注意预防灾害。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水上涨，造成了严重的灾害。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家去年遭受了一次大灾害。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾害发生后，救援队很快赶到了。", "target_word": "灾害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "災害", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自然或人为原因造成的损害，如水灾、旱灾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01a5a511-643b-455f-a743-1f7bb54c8652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疾病", "is_correct": false, "explanation": "语义：水灾和旱灾是造成损害的灾害，不是疾病。"}, {"text": "灾害", "is_correct": true, "explanation": "正确。水灾、旱灾都属于灾害，可以说是严重的灾害。"}, {"text": "乐趣", "is_correct": false, "explanation": "搭配：“严重”不修饰“乐趣”，“严重的乐趣”说不通。"}, {"text": "节日", "is_correct": false, "explanation": "语义：水灾、旱灾是损害，节日不能是严重的损害。"}], "explanations": {"疾病": "语义：水灾和旱灾是造成损害的灾害，不是疾病。", "灾害": "正确。水灾、旱灾都属于灾害，可以说是严重的灾害。", "乐趣": "搭配：“严重”不修饰“乐趣”，“严重的乐趣”说不通。", "节日": "语义：水灾、旱灾是损害，节日不能是严重的损害。"}, "sentence_index": 0, "correct_answer": "灾害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他考试没通过，这场灾害让他很难过。", "explanation": "这里应该用〈失败〉。灾害指造成大范围损害的事，考试没通过是个人的失败，要用“失败”。"}, {"text": "他骑车时出了一次灾害，腿摔伤了。", "explanation": "这里应该用〈事故〉。灾害指大范围的损害，个人骑车摔伤要用“事故”。"}, {"text": "那次摔跤是一次灾害，他没有受伤。", "explanation": "这里应该用〈意外〉。灾害指造成损害的大事，没有造成损害的小摔跤要用“意外”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不是需要预防的事情。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“预防”针对灾害、疾病等，不搭配“颜色”。"}, {"text": "灯笼", "is_correct": false, "explanation": "语义：灯笼不是需要预防的危害，句意不通。"}, {"text": "灾害", "is_correct": true, "explanation": "正确。预防的对象是灾害。"}], "explanations": {"饼干": "语义：饼干是食品，不是需要预防的事情。", "颜色": "搭配：“预防”针对灾害、疾病等，不搭配“颜色”。", "灯笼": "语义：灯笼不是需要预防的危害，句意不通。", "灾害": "正确。预防的对象是灾害。"}, "sentence_index": 6, "correct_answer": "灾害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司因为合同发生了灾害，最后打了官司。", "explanation": "这里应该用〈纠纷〉。灾害指水灾、旱灾这类造成损害的事，合同争议要用“纠纷”。"}, {"text": "两个人因为小事发生了灾害，后来和好了。", "explanation": "这里应该用〈争吵〉。灾害指造成损害的事，口角要用“争吵”。"}, {"text": "他在比赛中表现不好，这场灾害让他没能进入决赛。", "explanation": "这里应该用〈失利〉。灾害指水灾、旱灾这类造成大范围损害的事，比赛没取得好成绩要用“失利”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只灾害毁掉了村里的庄稼。", "corrected_sentence": "这场灾害毁掉了村里的庄稼。", "error_description": "“灾害”指一次事件，量词应用“场”。“这只灾害”用了动物量词“只”，应改为“这场灾害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次严重地灾害让整个村子断了水。", "corrected_sentence": "这次严重的灾害让整个村子断了水。", "error_description": "“灾害”前的修饰语要用“的”，“严重地灾害”误用了“地”，应改为“严重的灾害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94971, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有效", "is_correct": true, "explanation": "正确：“有效”与“无效”是反义词，指做了有结果、起作用。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指声音小或心里平静，与“无效”没有反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容外表好看，与“无效”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指清晰、明白，与“无效”没有反义关系。"}], "correct_answer": "有效", "explanations": {"有效": "正确：“有效”与“无效”是反义词，指做了有结果、起作用。", "安静": "“安静”指声音小或心里平静，与“无效”没有反义关系。", "美丽": "“美丽”形容外表好看，与“无效”没有反义关系。", "清楚": "“清楚”指清晰、明白，与“无效”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94971, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有效", "is_correct": true, "explanation": "正确：“有效”与“无效”是反义词，指做了有结果、起作用。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”指心情愉快，与“无效”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人反应快、有智慧，与“无效”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有污物，与“无效”没有反义关系。"}], "correct_answer": "有效", "explanations": {"有效": "正确：“有效”与“无效”是反义词，指做了有结果、起作用。", "高兴": "“高兴”指心情愉快，与“无效”没有反义关系。", "聪明": "“聪明”形容人反应快、有智慧，与“无效”没有反义关系。", "干净": "“干净”指没有污物，与“无效”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94971, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无效是做了也没用。", "primary_collocate": null, "pronunciation": "wú xiào", "ipa": "u˧˥ ɕiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他不肯改，我说什么都无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在才道歉，已经无效了。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不练习，光看书是无效的。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我试了三次，方法都无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他劝了很久，结果还是无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用了很多办法让他安静，都无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再怎么哭，也是无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有认真做，再多努力也无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不肯努力，给他再多机会也无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么久的努力，最后都无效了。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無效", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做了某事但没有用处，达不到想要的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94971, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无效", "is_correct": true, "explanation": "正确：“无效”指做了也没有效果，与“他不肯改，我说什么都……”的语境相符。"}, {"text": "有用", "is_correct": false, "explanation": "语义：“有用”说明话有作用，与“他不肯改”的前半句矛盾。"}, {"text": "有益", "is_correct": false, "explanation": "语域：“有益”偏书面，口语里“我说什么都有益”不自然，而且说话有好处也与“他不肯改”的语境不合。"}, {"text": "灵验", "is_correct": false, "explanation": "搭配：“灵验”多用于祈祷、符咒或预言，不能用来说话的结果。"}], "explanations": {"无效": "正确：“无效”指做了也没有效果，与“他不肯改，我说什么都……”的语境相符。", "有用": "语义：“有用”说明话有作用，与“他不肯改”的前半句矛盾。", "有益": "语域：“有益”偏书面，口语里“我说什么都有益”不自然，而且说话有好处也与“他不肯改”的语境不合。", "灵验": "搭配：“灵验”多用于祈祷、符咒或预言，不能用来说话的结果。"}, "sentence_index": 0, "correct_answer": "无效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台旧收音机已经无效了。", "explanation": "这里应该用〈无用〉。无效指做法、措施没有效果，不用来说东西本身没有用处。"}, {"text": "这道菜很无效，吃起来一点味道都没有。", "explanation": "这里应该用〈寡淡〉。无效指做法或结果没有效果，不用来形容食物的味道。"}, {"text": "他太无效了，什么都做不好。", "explanation": "这里应该用〈无能〉。无效只说做法或结果不起作用，不能用来形容人的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无效", "is_correct": true, "explanation": "正确：“无效”指做了也没有效果，与“你再怎么哭，也是……”的语境相符。"}, {"text": "管用", "is_correct": false, "explanation": "语义：“管用”说明有效果，与“你再怎么哭”的无奈语气相反。"}, {"text": "有意义", "is_correct": false, "explanation": "语义：“有意义”说哭有价值，与“你再怎么哭”的无奈语气不合。"}, {"text": "合理", "is_correct": false, "explanation": "搭配：“合理”多用于做法、安排，不能用来评价哭的结果。"}], "explanations": {"无效": "正确：“无效”指做了也没有效果，与“你再怎么哭，也是……”的语境相符。", "管用": "语义：“管用”说明有效果，与“你再怎么哭”的无奈语气相反。", "有意义": "语义：“有意义”说哭有价值，与“你再怎么哭”的无奈语气不合。", "合理": "搭配：“合理”多用于做法、安排，不能用来评价哭的结果。"}, "sentence_index": 6, "correct_answer": "无效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的运转很无效，一小时只能做十个。", "explanation": "这里应该用〈低效〉。无效指做了也没用，形容运转慢、产量少要用“低效”。"}, {"text": "他的字写得很无效，别人根本看不懂。", "explanation": "这里应该用〈潦草〉。无效指做法或结果没有效果，不用来形容字迹。"}, {"text": "这张桌子的腿很无效，一碰就晃。", "explanation": "这里应该用〈不结实〉。无效指做法或结果没有效果，不用来形容物件的牢固程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们提出的几个办法都无效地。", "corrected_sentence": "他们提出的几个办法都无效了。", "error_description": "“地”用在动词前作状语标记，“无效”在句末作谓语，后面不能加“地”，应说“都无效了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们想尽办法，结果还是无效地。", "corrected_sentence": "我们想尽办法，结果还是无效了。", "error_description": "“地”用在动词前作状语标记，“无效”在句末作谓语，后面不能加“地”，应说“结果还是无效了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
