INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94972, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "票证、合同、证件等因不符合规定而不被承认，不起作用。", "primary_collocate": null, "pronunciation": "wú xiào", "ipa": "u˧˥ ɕiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这张票过期了，已经无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同没有签字，是无效的。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超过时间的优惠券无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我输错了密码，所以这次登录无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡过了期，在这里无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有盖章的证明无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时间到了，再写的答案无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张优惠券只能用一次，第二次无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的投票因为没有填名字而无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的签名和证件不一样，所以无效。", "target_word": "无效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無效", "label": "繁体"}], "register": "中性", "sense_fingerprint": "票证、合同、号码等不起作用，不被承认", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94972, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无效", "is_correct": true, "explanation": "正确：“无效”指票证过期后不被承认，与“这张票过期了”相符。"}, {"text": "有用", "is_correct": false, "explanation": "语义：“有用”说明票还能用，与“过期了”矛盾。"}, {"text": "新鲜", "is_correct": false, "explanation": "搭配：“新鲜”形容食物或空气，不用来形容票。"}, {"text": "合法", "is_correct": false, "explanation": "语义：“合法”指符合法律，票过期后不能说“已经合法”。"}], "explanations": {"无效": "正确：“无效”指票证过期后不被承认，与“这张票过期了”相符。", "有用": "语义：“有用”说明票还能用，与“过期了”矛盾。", "新鲜": "搭配：“新鲜”形容食物或空气，不用来形容票。", "合法": "语义：“合法”指符合法律，票过期后不能说“已经合法”。"}, "sentence_index": 0, "correct_answer": "无效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影很无效，看得人直打哈欠。", "explanation": "这里应该用〈乏味〉。无效指没有效果、不起作用，形容影片枯燥要用“乏味”。"}, {"text": "这盒牛奶已经无效了，喝了会不舒服。", "explanation": "这里应该用〈过期〉。无效指凭证、做法不被承认或不起作用，食品放久变质要用“过期”。"}, {"text": "这首歌很无效，听得人很烦。", "explanation": "这里应该用〈难听〉。无效指没有效果、不起作用，形容歌曲声音不好听要用“难听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无效", "is_correct": true, "explanation": "正确：“无效”指时间到了之后写的答案不算数，与语境相符。"}, {"text": "有利", "is_correct": false, "explanation": "语义：“有利”说对某方有好处，与“考试时间到了”的语境相反。"}, {"text": "突出", "is_correct": false, "explanation": "搭配：“突出”形容人或成绩的特点，不用来形容答案的效力。"}, {"text": "有益", "is_correct": false, "explanation": "语域：“有益”偏书面，而且说答案有益与“考试时间到了”的语境不合。"}], "explanations": {"无效": "正确：“无效”指时间到了之后写的答案不算数，与语境相符。", "有利": "语义：“有利”说对某方有好处，与“考试时间到了”的语境相反。", "突出": "搭配：“突出”形容人或成绩的特点，不用来形容答案的效力。", "有益": "语域：“有益”偏书面，而且说答案有益与“考试时间到了”的语境不合。"}, "sentence_index": 6, "correct_answer": "无效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很无效，动不动就发火。", "explanation": "这里应该用〈暴躁〉。无效指凭证、做法不被承认或不起作用，不用来形容脾气。"}, {"text": "他这个人很无效。", "explanation": "这里应该用〈没用〉。无效不用来形容人，说人没有价值要用“没用”。"}, {"text": "这件衣服的颜色很无效，看着很难看。", "explanation": "这里应该用〈难看〉。无效指没有效果、不起作用，形容颜色、外观不好看要用“难看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张优惠券已经过期，无效地。", "corrected_sentence": "这张优惠券已经过期，无效了。", "error_description": "“地”用在动词前作状语标记，“无效”在句末作谓语，后面不能加“地”，应说“无效了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份申请因为没有签名，所以无效地。", "corrected_sentence": "这份申请因为没有签名，所以无效了。", "error_description": "“地”用在动词前作状语标记，“无效”在句末作谓语，后面不能加“地”，应说“所以无效了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
