INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一家族世代统治的朝代。", "primary_collocate": null, "pronunciation": "wáng cháo", "ipa": "wɑŋ˧˥ ʈʂʰɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "唐朝是中国历史上很有名的王朝。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "清朝是中国最后一个王朝。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个王朝一共有十几位皇帝。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个王朝不可能永远存在，最后都会结束。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个王朝由一个家族统治了三百年。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在博物馆里看到了那个王朝的瓷器。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汉朝以后，又出现了好几个新王朝。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，每个王朝都有自己的故事。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里写着很多王朝的名字。", "target_word": "王朝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个王朝灭亡以后，国家乱了很多年。", "target_word": "王朝", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "同一家族世代统治的朝代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '063f9b1f-5b36-425e-8fb6-27ef06b3df50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝是人，唐朝是朝代，不能说“唐朝是……很有名的皇帝”。"}, {"text": "王朝", "is_correct": true, "explanation": "王朝指同一家族世代统治的朝代，正好说明唐朝属于哪一类历史时期。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语且带贬义，不适合用于历史叙述。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市是地方，唐朝是朝代，二者不能等同。"}], "explanations": {"皇帝": "语义：皇帝是人，唐朝是朝代，不能说“唐朝是……很有名的皇帝”。", "王朝": "王朝指同一家族世代统治的朝代，正好说明唐朝属于哪一类历史时期。", "玩意儿": "语域：“玩意儿”是口语且带贬义，不适合用于历史叙述。", "城市": "语义：城市是地方，唐朝是朝代，二者不能等同。"}, "sentence_index": 0, "correct_answer": "王朝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国是一个历史很长的王朝。", "explanation": "这里应该用〈国家〉。王朝指同一家族世代统治的朝代，是一段历史时期，不能用来指称整个国家。"}, {"text": "王朝住在皇宫里。", "explanation": "这里应该用〈皇帝〉。王朝是朝代，不是人，不能住在皇宫里。"}, {"text": "北京是中国的王朝。", "explanation": "这里应该用〈首都〉。北京是城市，王朝指朝代，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流是自然地理事物，不是统治时期，不会在“汉朝以后”一个接一个地更替出现。"}, {"text": "王朝", "is_correct": true, "explanation": "王朝指一个家族世代统治的朝代，符合“汉朝以后又出现了好几个新……”的历史语境。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语，用于“汉朝以后”这类历史叙述很不协调。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳只有一个，不能说“又出现了好几个新太阳”。"}], "explanations": {"河流": "语义：河流是自然地理事物，不是统治时期，不会在“汉朝以后”一个接一个地更替出现。", "王朝": "王朝指一个家族世代统治的朝代，符合“汉朝以后又出现了好几个新……”的历史语境。", "家伙": "语域：“家伙”是口语，用于“汉朝以后”这类历史叙述很不协调。", "太阳": "语义：太阳只有一个，不能说“又出现了好几个新太阳”。"}, "sentence_index": 6, "correct_answer": "王朝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戴上了王朝。", "explanation": "这里应该用〈皇冠〉。王朝是一段历史时期，不是能戴在头上的东西。"}, {"text": "他把牛奶倒进了王朝。", "explanation": "这里应该用〈杯子〉。王朝是时期，不能当作容器装东西。"}, {"text": "他每天开王朝上班。", "explanation": "这里应该用〈车〉。王朝不是交通工具，不能用“开”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个王朝存在了着三百年。", "corrected_sentence": "这个王朝存在了三百年。", "error_description": "“了”与“着”不能同时用在同一个动词后面，是体标误用。去掉“着”，说“存在了三百年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座王朝的历史很长。", "corrected_sentence": "那个王朝的历史很长。", "error_description": "量词错误：王朝应使用〈个〉。“座”用于山、楼等大型建筑，应改为“那个王朝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
