INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94975, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "疑问是心里不明白，想问的事。", "primary_collocate": null, "pronunciation": "yí wèn", "ipa": "i˧˥ wən˥˩", "syllable_count": 2, "sentences": [{"text": "老师，我心里有一个疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完这件事，我还有很多疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有疑问就马上问老师。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对这个办法有什么疑问吗？", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把心里的疑问写在了本子上。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的脑子里总是有很多疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有疑问的同学可以先回家。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着我，眼里全是疑问。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家想一想，还有没有疑问？", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的疑问是，他为什么没来。", "target_word": "疑问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "疑问句", "label": "复合"}, {"form": "疑问词", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里不明白、想问的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8a6e1b4-4957-4aa2-bef8-2e14d4c5083b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送人的东西，不能放在心里，与“心里想问的事”不符。"}, {"text": "疑问", "is_correct": true, "explanation": "“心里有一个疑问”指心里不明白、想问的事，与句意相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是心里不明白的事。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“一个”不能修饰“空气”这样的不可数名词。"}], "explanations": {"礼物": "语义：礼物是送人的东西，不能放在心里，与“心里想问的事”不符。", "疑问": "“心里有一个疑问”指心里不明白、想问的事，与句意相符。", "书包": "语义：书包是装东西的袋子，不是心里不明白的事。", "空气": "搭配：“一个”不能修饰“空气”这样的不可数名词。"}, "sentence_index": 0, "correct_answer": "疑问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给了我一个满意的疑问。", "explanation": "这里应该用〈答案〉。疑问是心里想问的事，不能说“满意”；能说“满意”的是答案。"}, {"text": "这份疑问我昨晚就做完了。", "explanation": "这里应该用〈作业〉。“做完”的对象是作业、题目，疑问不能被“做完”。"}, {"text": "我心里有一只疑问，想问老师。", "explanation": "这里应该用〈个〉。疑问是抽象名词，量词用“个”；“只”多用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛奶", "is_correct": false, "explanation": "语义：“没有牛奶的同学可以先回家”没有道理，句子说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“没有窗户的同学可以先回家”与“回家”的条件无关，说不通。"}, {"text": "翅膀", "is_correct": false, "explanation": "搭配：“同学”是人，不能说“没有翅膀的同学”，“翅膀”与“同学”搭配不上。"}, {"text": "疑问", "is_correct": true, "explanation": "“没有疑问”即没有不明白的地方，可以先回家，与句意相符。"}], "explanations": {"牛奶": "语义：“没有牛奶的同学可以先回家”没有道理，句子说不通。", "窗户": "语义：“没有窗户的同学可以先回家”与“回家”的条件无关，说不通。", "翅膀": "搭配：“同学”是人，不能说“没有翅膀的同学”，“翅膀”与“同学”搭配不上。", "疑问": "“没有疑问”即没有不明白的地方，可以先回家，与句意相符。"}, "sentence_index": 6, "correct_answer": "疑问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的疑问是，这本书很有意思。", "explanation": "这里应该用〈感想〉。疑问是心里想问的事，不能用来表达读后的看法。"}, {"text": "他的疑问是当一名医生。", "explanation": "这里应该用〈心愿〉。疑问是想弄清楚的事，不能是想要实现的愿望。"}, {"text": "我每天早上都喝疑问，很有营养。", "explanation": "这里应该用〈牛奶〉。“喝”的对象是饮料，疑问是想弄清楚的问题，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我对这件事很疑问。", "corrected_sentence": "我对这件事很有疑问。", "error_description": "“疑问”是名词，不能直接受“很”修饰成形容词；应说“很有疑问”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没有一条疑问的同学可以先回家。", "corrected_sentence": "没有一个疑问的同学可以先回家。", "error_description": "量词错误：“疑问”的量词用“个”，不用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
