INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94979, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "穿越是从一边走过去到另一边。", "primary_collocate": null, "pronunciation": "chuān yuè", "ipa": "ʈʂʰwan˥ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "我们小心地穿越了那片沼泽。", "target_word": "穿越", "complexity_tier": "T3", "furigana": "wǒmen xiǎoxīn de chuānyuè le nà piàn zhǎozé", "sentence_source": "generated"}, {"text": "他们穿越森林，走到了河边。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们穿越操场，跑进教室。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骆驼穿越沙漠，走了三天。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢穿越了铁路。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从公园的这边穿越到那边。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请走地下通道穿越到马路对面。", "target_word": "穿越", "complexity_tier": "T3", "furigana": "qǐng zǒu dìxià tōngdào chuānyuè dào mǎlù duìmiàn", "sentence_source": "generated"}, {"text": "我们穿越了一片草地，看见了湖。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗穿越街道，跑回了家。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "探险队穿越了雪山。", "target_word": "穿越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿越了", "label": "体标（完成）"}, {"form": "穿越过", "label": "体标（经历）"}], "register": "中性", "sense_fingerprint": "人或动物从一边走到另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1665dc3-7706-4348-9cee-b52c002cdca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿越", "is_correct": true, "explanation": "正确：“穿越”表示人从一边走到另一边，符合“小心地走过沼泽”的语境。"}, {"text": "建造", "is_correct": false, "explanation": "语义：沼泽是自然形成的地貌，不能被“建造”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象应是液体，沼泽不能被喝。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能直接带“沼泽”作宾语。"}], "explanations": {"穿越": "正确：“穿越”表示人从一边走到另一边，符合“小心地走过沼泽”的语境。", "建造": "语义：沼泽是自然形成的地貌，不能被“建造”。", "喝": "语义：“喝”的对象应是液体，沼泽不能被喝。", "哭": "配价：“哭”是不及物动词，后面不能直接带“沼泽”作宾语。"}, "sentence_index": 0, "correct_answer": "穿越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿越了一杯咖啡。", "explanation": "这里应该用〈喝〉。穿越是从一边走到另一边，不表示饮用，喝咖啡要用〈喝〉。"}, {"text": "他穿越了这次考试。", "explanation": "这里应该用〈通过〉。穿越是从一边走到另一边，不表示考试合格，通过考试要用〈通过〉。"}, {"text": "他穿越了这个问题。", "explanation": "这里应该用〈解决〉。穿越是从一边走到另一边，不用于“处理问题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿越", "is_correct": true, "explanation": "正确：“穿越到”表示从地下通道走到马路对面，与“请走地下通道”相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“请走地下通道”说明是步行，“飞”与此矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能表示从地下通道走到马路对面。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”表示用水清洁东西，不能表示到达马路对面。"}], "explanations": {"穿越": "正确：“穿越到”表示从地下通道走到马路对面，与“请走地下通道”相符。", "飞": "语义：“请走地下通道”说明是步行，“飞”与此矛盾。", "唱": "语义：“唱”的对象是歌曲，不能表示从地下通道走到马路对面。", "洗": "语义：“洗”表示用水清洁东西，不能表示到达马路对面。"}, "sentence_index": 6, "correct_answer": "穿越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师穿越了这个故事。", "explanation": "这里应该用〈讲述〉。穿越是从一边走到另一边，不表示叙述；讲这个故事要用〈讲述〉。"}, {"text": "他穿越了一封信。", "explanation": "这里应该用〈读〉。穿越是从一边走到另一边，不表示阅读，读信要用〈读〉。"}, {"text": "他穿越了原来的计划。", "explanation": "这里应该用〈推翻〉。穿越不表示否定或取消，推翻计划要用〈推翻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们穿越了着一条泥泞的小路。", "corrected_sentence": "他们穿越了一条泥泞的小路。", "error_description": "错误：“了着”重复体标；正确：“穿越了”。“了”表示动作已完成，“着”表示动作持续，二者不能同时用在同一动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们穿越在了河对岸。", "corrected_sentence": "他们穿越到了河对岸。", "error_description": "错误：“穿越在了”；正确：“穿越到了”。结果补语应用“到”表示到达的地点，“在”不能表示这一动作的终点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
