INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94981, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "老去是人慢慢变老了。", "primary_collocate": null, "pronunciation": "lǎo qù", "ipa": "lau̯˨˩˦ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸妈妈在老家慢慢老去，我很想回去看看。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岁月不停，我们每个人都在老去。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师老去了，可是学生们还记得他。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最怕的是自己老去后没人照顾。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着朋友们一个个老去，他很感慨。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青春会过去，我们终将老去。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆老去的样子，我永远记得。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人在老去以前，应该多去看看世界。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一点也不担心老去，每天都开开心心。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起慢慢老去，一起看日出日落。", "target_word": "老去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老去了", "label": "体标"}], "register": "书面", "sense_fingerprint": "老去：人慢慢变老", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b6ab932-ffa3-44f3-be69-23e97a6cbed0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94981, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老去", "is_correct": true, "explanation": "正确。老去（lǎo qù）指人慢慢变老，与听到的读音一致。"}, {"text": "老区", "is_correct": false, "explanation": "qū（第一声）与 qù（第四声）声调不同，老区指旧时的革命根据地。"}, {"text": "老气", "is_correct": false, "explanation": "qì 与 qù 韵母不同（i 与 ü），老气指陈旧、缺乏朝气，不指变老的过程。"}, {"text": "老曲", "is_correct": false, "explanation": "qǔ（第三声）与 qù（第四声）声调不同，老曲指旧的歌曲或曲调。"}], "explanations": {"老去": "正确。老去（lǎo qù）指人慢慢变老，与听到的读音一致。", "老区": "qū（第一声）与 qù（第四声）声调不同，老区指旧时的革命根据地。", "老气": "qì 与 qù 韵母不同（i 与 ü），老气指陈旧、缺乏朝气，不指变老的过程。", "老曲": "qǔ（第三声）与 qù（第四声）声调不同，老曲指旧的歌曲或曲调。"}, "sentence_index": null, "correct_answer": "老去"}, "level_3": {"options": [{"text": "老去", "is_correct": true, "explanation": "正确：老去指人慢慢变老，与「爸爸妈妈在老家慢慢老去」相合。"}, {"text": "长大", "is_correct": false, "explanation": "语义：父母已是成年人，不会再「长大」。"}, {"text": "繁荣", "is_correct": false, "explanation": "搭配：「繁荣」用于城市、事业，不用于形容父母。"}, {"text": "倒退", "is_correct": false, "explanation": "语义：「倒退」指向后退步，与父母的自然变化不符。"}], "explanations": {"老去": "正确：老去指人慢慢变老，与「爸爸妈妈在老家慢慢老去」相合。", "长大": "语义：父母已是成年人，不会再「长大」。", "繁荣": "搭配：「繁荣」用于城市、事业，不用于形容父母。", "倒退": "语义：「倒退」指向后退步，与父母的自然变化不符。"}, "sentence_index": 0, "correct_answer": "老去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同签了十年，条款已经老去。", "explanation": "这里应该用〈过时〉。「老去」指人或生物随时间衰老，条款不再适用要用〈过时〉。"}, {"text": "他的怒气一天天老去。", "explanation": "这里应该用〈消退〉。「老去」指人随时间变老，怒气的平息要用〈消退〉。"}, {"text": "这首歌的热度慢慢老去了。", "explanation": "这里应该用〈减退〉。「老去」指人或生物随时间变老，热度的下降要用〈减退〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94981, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老去", "is_correct": true, "explanation": "正确。老去（lǎo qù）指人慢慢变老，与听到的读音一致。"}, {"text": "老路", "is_correct": false, "explanation": "lù 与 qù 声母不同（l 与 q），老路指旧的道路，与变老无关。"}, {"text": "老户", "is_correct": false, "explanation": "hù 与 qù 声母不同（h 与 q），老户指老住户。"}, {"text": "老剧", "is_correct": false, "explanation": "jù 与 qù 声母不同（j 与 q），老剧指旧时的戏剧。"}, {"text": "老鹿", "is_correct": false, "explanation": "lù 与 qù 声母不同（l 与 q），老鹿指年老的鹿。"}], "explanations": {"老去": "正确。老去（lǎo qù）指人慢慢变老，与听到的读音一致。", "老路": "lù 与 qù 声母不同（l 与 q），老路指旧的道路，与变老无关。", "老户": "hù 与 qù 声母不同（h 与 q），老户指老住户。", "老剧": "jù 与 qù 声母不同（j 与 q），老剧指旧时的戏剧。", "老鹿": "lù 与 qù 声母不同（l 与 q），老鹿指年老的鹿。"}, "sentence_index": null, "correct_answer": "老去"}, "level_3": {"options": [{"text": "老去", "is_correct": true, "explanation": "正确：老去指人随时间变老，与「外婆老去的样子」相合。"}, {"text": "长大", "is_correct": false, "explanation": "语义：外婆已是成年人，不会再「长大」。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：「生长」多用于植物或幼小的生命，不用来形容外婆。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：「发芽」只用于植物或种子，不能用于人。"}], "explanations": {"老去": "正确：老去指人随时间变老，与「外婆老去的样子」相合。", "长大": "语义：外婆已是成年人，不会再「长大」。", "生长": "搭配：「生长」多用于植物或幼小的生命，不用来形容外婆。", "发芽": "搭配：「发芽」只用于植物或种子，不能用于人。"}, "sentence_index": 6, "correct_answer": "老去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部手机用了五年，零件都老去了。", "explanation": "这里应该用〈老化〉。「老去」指人或生物随时间衰老，机器零件性能变差要用〈老化〉。"}, {"text": "这块肉放久了就老去了。", "explanation": "这里应该用〈腐烂〉。「老去」只用于人或生物随时间衰老，食物变质要用〈腐烂〉。"}, {"text": "这把铁锁放在雨里，很快就老去了。", "explanation": "这里应该用〈生锈〉。「老去」用于人或生物的衰老，金属的锈蚀要用〈生锈〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的头发开始白了，她也在慢慢很老去。", "corrected_sentence": "妈妈的头发开始白了，她也在慢慢老去。", "error_description": "「很老去」错在用程度副词「很」修饰动词「老去」。「老去」是动词，不能直接受「很」修饰，应去掉「很」，说「在慢慢老去」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姥姥一天天被老去，我舍不得她。", "corrected_sentence": "姥姥一天天老去，我舍不得她。", "error_description": "「被老去」错在用了「被」。「老去」是不及物动词，没有被动用法，应去掉「被」，说「老去」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b652e03-3212-49f5-8464-607d6622b468') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
