INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94983, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "号叫是大声地喊叫。", "primary_collocate": null, "pronunciation": "háo jiào", "ipa": "xɑʊ˧˥ tɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "球迷们在看台上号叫，声音传遍了整个体育场。", "target_word": "号叫", "complexity_tier": "T3", "furigana": "háo jiào", "sentence_source": "generated"}, {"text": "孩子在门外号叫，吵得大家睡不着。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地对着电话号叫了几声。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜有人在楼下号叫，我很害怕。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别在图书馆号叫，大家都在看书。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山谷里传来孩子们的号叫，大家都吓了一跳。", "target_word": "号叫", "complexity_tier": "T3", "furigana": "háo jiào", "sentence_source": "generated"}, {"text": "他号叫着跑过来，要大家快走。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不要在教室里号叫。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山上对着远处号叫了一声。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被骗后在街上号叫，引来许多人围观。", "target_word": "号叫", "complexity_tier": "T3", "furigana": "háo jiào", "sentence_source": "generated"}], "morphological_forms": [{"form": "号叫着", "label": "体标"}, {"form": "号叫了", "label": "体标"}, {"form": "号叫过", "label": "体标"}], "register": "书面", "sense_fingerprint": "大声地喊叫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8a6e1b4-4957-4aa2-bef8-2e14d4c5083b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94983, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "号叫", "is_correct": true, "explanation": "「号叫」是大声地喊叫，与“声音传遍了整个体育场”相符。"}, {"text": "低语", "is_correct": false, "explanation": "语义：「低语」的声音很小，与“声音传遍了整个体育场”矛盾。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：「沉默」不发出声音，无法让声音传遍体育场。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：「微笑」是表情，不能与“声音传遍”搭配。"}], "explanations": {"号叫": "「号叫」是大声地喊叫，与“声音传遍了整个体育场”相符。", "低语": "语义：「低语」的声音很小，与“声音传遍了整个体育场”矛盾。", "沉默": "语义：「沉默」不发出声音，无法让声音传遍体育场。", "微笑": "搭配：「微笑」是表情，不能与“声音传遍”搭配。"}, "sentence_index": 0, "correct_answer": "号叫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在远处低声号叫着，想让我快点过去。", "explanation": "这里应该用〈呼唤〉。「号叫」是大声喊叫，与“低声”矛盾，轻声叫人过来要用〈呼唤〉。"}, {"text": "他在角落里号叫了一阵，像在商量事情。", "explanation": "这里应该用〈嘀咕〉。「号叫」是大声喊叫，像在小声商量要用〈嘀咕〉。"}, {"text": "妈妈在床边号叫着，想让孩子快点睡觉。", "explanation": "这里应该用〈哄〉。「号叫」是大声长叫，哄孩子睡觉要用〈哄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号叫", "is_correct": true, "explanation": "「号叫」是大声地喊叫，符合“跑过来、要大家快走”的紧急语境。"}, {"text": "散步", "is_correct": false, "explanation": "语义：「散步」是慢慢地走，与“跑过来”矛盾。"}, {"text": "静坐", "is_correct": false, "explanation": "搭配：「静坐」指坐着不动，不能与“跑过来”搭配。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：「发呆」是呆住不动，与“跑过来、快走”矛盾。"}], "explanations": {"号叫": "「号叫」是大声地喊叫，符合“跑过来、要大家快走”的紧急语境。", "散步": "语义：「散步」是慢慢地走，与“跑过来”矛盾。", "静坐": "搭配：「静坐」指坐着不动，不能与“跑过来”搭配。", "发呆": "语义：「发呆」是呆住不动，与“跑过来、快走”矛盾。"}, "sentence_index": 6, "correct_answer": "号叫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他悄悄地号叫了一声，怕吵醒别人。", "explanation": "「号叫」指大声地喊叫，与“悄悄地”矛盾，此处应该用〈哼〉：“他悄悄地哼了一声”。"}, {"text": "他的笑声很轻，像在号叫。", "explanation": "这里应该用〈轻笑〉。「号叫」指大声叫喊，形容很轻的笑声要用〈轻笑〉，不能用〈号叫〉。"}, {"text": "他在台下号叫得很小声。", "explanation": "这里应该用〈哼〉。「号叫」是大声叫，形容很小的声音要用〈哼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他号叫很大声，全楼都听见了。", "corrected_sentence": "他号叫得很大声，全楼都听见了。", "error_description": "程度补语应为“号叫得很大声”，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在山上号叫很响，声音传得很远。", "corrected_sentence": "他在山上号叫得很响，声音传得很远。", "error_description": "程度补语漏掉“得”：“号叫”后接程度补语“很响”时要说“号叫得很响”，不能说“号叫很响”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
