INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94984, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大声地叫，多形容野兽或人痛苦时的叫声。", "primary_collocate": null, "pronunciation": "háo jiào", "ipa": "xɑʊ˧˥ tɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "狼在山上号叫，声音很可怕。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的小狗一直在号叫。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿很疼，疼得在床上号叫。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，远处的野兽在号叫。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎在笼子里不停地号叫。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人疼得整夜号叫，医生赶快来了。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫受了伤，在草地上号叫着。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子肚子疼，在妈妈怀里号叫。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的狼整夜号叫，我们都没睡好。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他痛苦地号叫了几声，就不动了。", "target_word": "号叫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "号叫着", "label": "体标"}, {"form": "号叫了", "label": "体标"}, {"form": "号叫过", "label": "体标"}], "register": "书面", "sense_fingerprint": "野兽或人痛苦时大声叫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8a6e1b4-4957-4aa2-bef8-2e14d4c5083b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "号叫", "is_correct": true, "explanation": "「号叫」是野兽痛苦时的大声叫，与“声音很可怕”相符。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：「微笑」不发出声音，不能与“声音很可怕”搭配。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：「沉默」没有声音，与“声音很可怕”矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉」不发出声音，与“声音很可怕”的语境矛盾。"}], "explanations": {"号叫": "「号叫」是野兽痛苦时的大声叫，与“声音很可怕”相符。", "微笑": "搭配：「微笑」不发出声音，不能与“声音很可怕”搭配。", "沉默": "语义：「沉默」没有声音，与“声音很可怕”矛盾。", "睡觉": "语义：「睡觉」不发出声音，与“声音很可怕”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "号叫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在门口号叫着，向妈妈轻声道别。", "explanation": "这里应该用〈低语〉。「号叫」是大声的长叫，与“轻声”矛盾，轻声道别要用〈低语〉。"}, {"text": "他在院子里小声地号叫了一会儿。", "explanation": "这里应该用〈嘀咕〉。「号叫」是大声的长叫，小声说话要用〈嘀咕〉，不能用〈号叫〉。"}, {"text": "奶奶在床边号叫着，想让宝宝入睡。", "explanation": "这里应该用〈哄〉。「号叫」是大声长叫，哄宝宝入睡要用〈哄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号叫", "is_correct": true, "explanation": "「号叫」是受伤后大声叫，与“受了伤，在草地上”的语境相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：受伤的猫不会跳舞，与“受了伤”矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：受伤痛苦时不会唱歌，与语境矛盾。"}, {"text": "写", "is_correct": false, "explanation": "语义：猫不会写字，“在草地上写”与语境矛盾。"}], "explanations": {"号叫": "「号叫」是受伤后大声叫，与“受了伤，在草地上”的语境相符。", "跳舞": "语义：受伤的猫不会跳舞，与“受了伤”矛盾。", "唱歌": "语义：受伤痛苦时不会唱歌，与语境矛盾。", "写": "语义：猫不会写字，“在草地上写”与语境矛盾。"}, "sentence_index": 6, "correct_answer": "号叫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他痛苦地号叫了一声，声音轻得像耳语。", "explanation": "这里应该用〈呻吟〉。「号叫」是大声的长叫，声音轻得像耳语要用〈呻吟〉。"}, {"text": "宝宝睡得很香，像在号叫。", "explanation": "这里应该用〈打鼾〉。「号叫」是大声的长叫，睡得很香时的声音要用〈打鼾〉。"}, {"text": "他疼得在床上轻轻地号叫，没有人听见。", "explanation": "这里应该用〈呻吟〉。「号叫」是大声的长叫，与“轻轻地”“没有人听见”矛盾，轻声地痛叫要用〈呻吟〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只猫受伤后号叫很厉害。", "corrected_sentence": "那只猫受伤后号叫得很厉害。", "error_description": "程度补语应为“号叫得很厉害”，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他痛苦地在床上号叫很厉害，不肯停下来。", "corrected_sentence": "他痛苦地在床上号叫得很厉害，不肯停下来。", "error_description": "程度补语漏掉“得”：“号叫”后接程度补语“很厉害”时要说“号叫得很厉害”，不能说“号叫很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
