INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94985, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "语音是人说话时发出的声音。", "primary_collocate": null, "pronunciation": "yǔ yīn", "ipa": "y˨˩ in˥", "syllable_count": 2, "sentences": [{"text": "这个软件可以把语音变成文字。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的语音听起来很温柔，让我很安心。", "target_word": "语音", "complexity_tier": "T3", "furigana": "mā mā de yǔ yīn tīng qǐ lái hěn wēn róu, ràng wǒ hěn ān xīn.", "sentence_source": "generated"}, {"text": "电话里的语音很清楚。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会记录你的语音。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个导航的语音很自然，开车时听着很舒服。", "target_word": "语音", "complexity_tier": "T3", "furigana": "zhè ge dǎo háng de yǔ yīn hěn zì rán, kāi chē shí tīng zhe hěn shū fu.", "sentence_source": "generated"}, {"text": "这段语音有点长，我听了两遍。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先听一下这段语音。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能分辨不同人的语音。", "target_word": "语音", "complexity_tier": "T3", "furigana": "zhè tái jī qì néng fēn biàn bù tóng rén de yǔ yīn.", "sentence_source": "generated"}, {"text": "这段语音里有很多杂音。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人能听懂人的语音。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語音", "label": "繁体"}, {"form": "语音消息", "label": "复合"}, {"form": "语音识别", "label": "复合"}], "register": "中性", "sense_fingerprint": "人说话发出的声音，也指录下来发送的说话声音（如语音消息）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94985, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "语音", "is_correct": true, "explanation": "正确。语音指人说话发出的声音，也指录下来的语音消息。"}, {"text": "玉音", "is_correct": false, "explanation": "yù（第四声）与 yǔ（第三声）声调不同，玉音是书面语，指对别人言辞的敬称或美好的声音，不是说话录音。"}, {"text": "雨衣", "is_correct": false, "explanation": "yī（第一声）与 yīn（第一声）只差鼻音韵尾 -n，意思是雨衣。"}, {"text": "余音", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，意思是声音停止后残留的声音。"}], "explanations": {"语音": "正确。语音指人说话发出的声音，也指录下来的语音消息。", "玉音": "yù（第四声）与 yǔ（第三声）声调不同，玉音是书面语，指对别人言辞的敬称或美好的声音，不是说话录音。", "雨衣": "yī（第一声）与 yīn（第一声）只差鼻音韵尾 -n，意思是雨衣。", "余音": "yú（第二声）与 yǔ（第三声）声调不同，意思是声音停止后残留的声音。"}, "sentence_index": null, "correct_answer": "语音"}, "level_3": {"options": [{"text": "语音", "is_correct": true, "explanation": "正确。“语音”指说话的声音，可以通过语音识别转成文字。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“把颜色变成文字”搭配不通，颜色不是可以转写成文字的内容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以转写成文字的说话内容。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道靠味觉感受，不能转成文字。"}], "explanations": {"语音": "正确。“语音”指说话的声音，可以通过语音识别转成文字。", "颜色": "搭配：“把颜色变成文字”搭配不通，颜色不是可以转写成文字的内容。", "天气": "语义：天气是自然现象，不是可以转写成文字的说话内容。", "味道": "语义：味道靠味觉感受，不能转成文字。"}, "sentence_index": 0, "correct_answer": "语音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他会说三种语音。", "explanation": "这里应该用〈语言〉。说“会说三种语言”时要用语言，语音指声音本身，不能用来指某种语言。"}, {"text": "我收到了一首语音。", "explanation": "这里量词用错。语音消息应该用〈条〉或〈段〉，〈首〉用于歌曲、诗词。"}, {"text": "空调发出很大的语音，吵得人睡不着。", "explanation": "这里应该用〈噪音〉。空调发出的杂乱响声叫噪音，语音只指说话的声音或语音消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语音", "is_correct": true, "explanation": "正确。“听一下这段语音”指听录下来的说话声音。"}, {"text": "照片", "is_correct": false, "explanation": "语义：照片是图像，不能用“听”。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“听”不能搭配“电影”，电影要说“看”。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味靠嗅觉感受，不能用“听”。"}], "explanations": {"语音": "正确。“听一下这段语音”指听录下来的说话声音。", "照片": "语义：照片是图像，不能用“听”。", "电影": "搭配：“听”不能搭配“电影”，电影要说“看”。", "香味": "语义：香味靠嗅觉感受，不能用“听”。"}, "sentence_index": 6, "correct_answer": "语音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的语音太小了，我听不清。", "explanation": "这里应该用〈音量〉。音量指声音的大小，歌曲声音太小要说音量；语音只指人说话的声音或语音消息。"}, {"text": "他说话带着很重的语音，别人听不懂。", "explanation": "这里应该用〈口音〉。带有地方特色的发音叫口音，语音不能用来指说话时带的地方特色。"}, {"text": "我收到一朵语音。", "explanation": "这里量词用错。语音消息应该用〈条〉或〈段〉，〈朵〉用于花、云等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚给我发了一台语音。", "corrected_sentence": "他刚给我发了一段语音。", "error_description": "“语音消息”的量词应为“段”或“条”。“台”用于机器、设备，不能用于语音。应把“台”改为“段”，即“一段语音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他发来一把语音，说他已经到了。", "corrected_sentence": "他发来一条语音，说他已经到了。", "error_description": "“语音消息”的量词应为“条”或“段”。“把”用于有柄的器具，不能用于语音。应把“把”改为“条”，即“一条语音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
