INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语音是一种语言的发音和声音系统，包括声母、韵母和声调。", "primary_collocate": null, "pronunciation": "yǔ yīn", "ipa": "y˨˩ in˥", "syllable_count": 2, "sentences": [{"text": "汉语的语音有四个声调。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语要先学好语音。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种方言的语音差别很大。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们英语的语音。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的语音语调都很标准。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语音是语言的声音系统。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学生的语音还需要练习，老师常常帮他纠正。", "target_word": "语音", "complexity_tier": "T3", "furigana": "zhè ge xué shēng de yǔ yīn hái xū yào liàn xí, lǎo shī cháng cháng bāng tā jiū zhèng.", "sentence_source": "generated"}, {"text": "这本书专门讲日语语音。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的语音发展得很快。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粤语的语音和普通话不同。", "target_word": "语音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "語音", "label": "繁体"}, {"form": "语音学", "label": "复合"}, {"form": "语音语调", "label": "复合"}], "register": "中性", "sense_fingerprint": "一种语言的发音和声音系统（声母、韵母、声调等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94986, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "语音", "is_correct": true, "explanation": "正确。语音指语言的发音和声音系统。"}, {"text": "玉音", "is_correct": false, "explanation": "yù（第四声）与 yǔ（第三声）声调不同，玉音是书面语，指美好的声音或对他人言辞的敬称。"}, {"text": "雨衣", "is_correct": false, "explanation": "yī（第一声）与 yīn（第一声）只差鼻音韵尾 -n，意思是雨衣。"}, {"text": "余音", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，意思是声音停止后残留的声音。"}], "explanations": {"语音": "正确。语音指语言的发音和声音系统。", "玉音": "yù（第四声）与 yǔ（第三声）声调不同，玉音是书面语，指美好的声音或对他人言辞的敬称。", "雨衣": "yī（第一声）与 yīn（第一声）只差鼻音韵尾 -n，意思是雨衣。", "余音": "yú（第二声）与 yǔ（第三声）声调不同，意思是声音停止后残留的声音。"}, "sentence_index": null, "correct_answer": "语音"}, "level_3": {"options": [{"text": "语音", "is_correct": true, "explanation": "正确。“语音”指语言的声音系统，声调是其中的一部分。"}, {"text": "词汇", "is_correct": false, "explanation": "语义：“词汇”指词的总和，不是声音系统，不说“有四个声调”。"}, {"text": "字形", "is_correct": false, "explanation": "语义：“字形”指汉字的书写形状，不是声音，没有声调。"}, {"text": "语法", "is_correct": false, "explanation": "搭配：“语法”与“有四个声调”搭配不通，语法不指声音的调类。"}], "explanations": {"语音": "正确。“语音”指语言的声音系统，声调是其中的一部分。", "词汇": "语义：“词汇”指词的总和，不是声音系统，不说“有四个声调”。", "字形": "语义：“字形”指汉字的书写形状，不是声音，没有声调。", "语法": "搭配：“语法”与“有四个声调”搭配不通，语法不指声音的调类。"}, "sentence_index": 0, "correct_answer": "语音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的语音很快，我听不清楚。", "explanation": "这里应该用〈语速〉。语速指说话的快慢，说话太快要说语速；语音指语言的发音系统，不指快慢。"}, {"text": "这位歌手的语音很大，把音响都震坏了。", "explanation": "这里应该用〈音量〉。语音指语言的发音系统，声音大小要说音量。"}, {"text": "工地传来刺耳的语音。", "explanation": "这里应该用〈噪音〉。刺耳杂乱的声音叫噪音，语音指语言的发音系统。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语音", "is_correct": true, "explanation": "正确。发音可以练习和纠正，“语音”指语言的发音。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体的特征，不是能练习的对象。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的特征，不是能练习的对象。"}, {"text": "照片", "is_correct": false, "explanation": "语义：照片是图像，不是可以练习的技能。"}], "explanations": {"语音": "正确。发音可以练习和纠正，“语音”指语言的发音。", "身高": "体貌：身高是身体的特征，不是能练习的对象。", "体重": "体貌：体重是身体的特征，不是能练习的对象。", "照片": "语义：照片是图像，不是可以练习的技能。"}, "sentence_index": 6, "correct_answer": "语音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台洗衣机的语音很大，吵得人睡不着。", "explanation": "这里应该用〈噪音〉。机器发出的杂乱响声叫噪音，语音指语言的发音系统，不指机器的声响。"}, {"text": "这首曲子的语音很悠扬，让人放松。", "explanation": "这里应该用〈乐声〉。语音只指语言或说话的声音，音乐的声音不用语音。"}, {"text": "汉语有一朵独特的语音。", "explanation": "这里量词用错。〈朵〉用于花、云等，语音作为语言的声音系统应该用〈种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书讲汉语地语音特点。", "corrected_sentence": "这本书讲汉语的语音特点。", "error_description": "“语音特点”是定中结构，“语音”修饰“特点”，中间要用“的”。错误形式“汉语地语音特点”把修饰语的助词“的”误用成状语助词“地”，正确形式应为“汉语的语音特点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汉语有一首独特的语音。", "corrected_sentence": "汉语有一种独特的语音。", "error_description": "“语音”指语言的声音系统时，量词应用“种”。“首”用于歌曲、诗词，不能说“一首语音”。应把“首”改为“种”，即“一种独特的语音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
