INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "赛季是一年里比赛的那一段时间。", "primary_collocate": null, "pronunciation": "sài jì", "ipa": "sai˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "新赛季下个月开始。", "target_word": "赛季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个赛季他一场比赛都没错过。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球赛季从秋天开始，到春天结束。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛季里球员每周都要比赛。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天是滑雪的赛季，运动员很忙。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛季快结束了，球队还在争第一。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛季开始前，球员们要练很长时间。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受了伤，整个赛季都不能上场。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛季结束后，球员可以休息两个月。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上个赛季我们队排在第三名。", "target_word": "赛季", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "新赛季", "label": "复合"}, {"form": "本赛季", "label": "复合"}], "register": "中性", "sense_fingerprint": "一年中运动比赛集中进行的那段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8674e63a-393f-4d84-bf8a-ca1ff6fc6749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是东西，不能说“新电脑下个月开始”。"}, {"text": "赛季", "is_correct": true, "explanation": "“新赛季”指新的一段比赛时期，与“下个月开始”相符。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：“朋友”指人，不会在下个月“开始”。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“衣服”是东西，不会在下个月“开始”。"}], "explanations": {"电脑": "语义：“电脑”是东西，不能说“新电脑下个月开始”。", "赛季": "“新赛季”指新的一段比赛时期，与“下个月开始”相符。", "朋友": "语义：“朋友”指人，不会在下个月“开始”。", "衣服": "语义：“衣服”是东西，不会在下个月“开始”。"}, "sentence_index": 0, "correct_answer": "赛季"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秋天是收获的赛季。", "explanation": "这里应该用〈季节〉。“赛季”指体育比赛的一段时期，表示自然界的季节要用“季节”。"}, {"text": "我们队昨天的赛季输了。", "explanation": "这里应该用〈球赛〉。“赛季”指整段时期，不能指某一场比赛的输赢。"}, {"text": "这次赛季的最后一分钟很精彩。", "explanation": "这里应该用〈比赛〉。“赛季”是一段时期，不会有“最后一分钟”这样的瞬间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不会“开始”。"}, {"text": "赛季", "is_correct": true, "explanation": "“赛季开始前”指比赛时期开始之前，球员要练习，句意相符。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不会“开始”。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔”是文具，不会“开始”。"}], "explanations": {"桌子": "语义：“桌子”是家具，不会“开始”。", "赛季": "“赛季开始前”指比赛时期开始之前，球员要练习，句意相符。", "苹果": "语义：“苹果”是水果，不会“开始”。", "铅笔": "语义：“铅笔”是文具，不会“开始”。"}, "sentence_index": 6, "correct_answer": "赛季"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部手机的赛季很长。", "explanation": "这里的“赛季”只能指体育比赛的一段时期，不能用来说手机的使用时间。"}, {"text": "第二赛季的销售额比去年高。", "explanation": "这里应该用〈季度〉。“赛季”指体育比赛的一段时期，不能用来指计算销售额的季度。"}, {"text": "这首歌的赛季从春天唱到秋天。", "explanation": "这里的“赛季”指体育比赛的一段时期，不能用来说歌曲的演唱时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只赛季我们队进了很多球。", "corrected_sentence": "这个赛季我们队进了很多球。", "error_description": "量词错误：“赛季”的量词应为“个”，不能用“只”。错误形式：这只赛季；正确形式：这个赛季。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位教练带队三年，每个赛季了都拿了冠军。", "corrected_sentence": "这位教练带队三年，每个赛季都拿了冠军。", "error_description": "“赛季”是名词，不能带动态助词“了”，应去掉“了”。错误形式：每个赛季了都拿了冠军；正确形式：每个赛季都拿了冠军。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02bbc78d-1e95-4345-8942-46b25251613e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
