INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94989, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟踪是一直跟在别人后面。", "primary_collocate": null, "pronunciation": "gēn zōng", "ipa": "kən˥ tsʊŋ˥", "syllable_count": 2, "sentences": [{"text": "有一个人一直跟踪她。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察开车跟踪那辆白色的车。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得有人在跟踪我。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟踪着小偷走进小路。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现有人跟踪过她。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别跟踪我，我想一个人走。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男人跟踪了她一路。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现学生在跟踪他。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把那辆出租车跟踪到了火车站。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟踪别人是不对的。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟蹤", "label": "繁体"}, {"form": "跟踪了", "label": "体标"}, {"form": "跟踪着", "label": "体标"}, {"form": "跟踪过", "label": "体标"}], "register": "中性", "sense_fingerprint": "悄悄一直跟在某人或某物后面走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94989, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟踪", "is_correct": true, "explanation": "正确。“跟踪”指悄悄一直跟在某人后面。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，不能用于“一直……她”。"}, {"text": "洗涤", "is_correct": false, "explanation": "语义：“洗涤”是用水清洗物品，不能用于人。"}, {"text": "注册", "is_correct": false, "explanation": "搭配：“注册”后接的是账号、公司等，不能接人。"}], "explanations": {"跟踪": "正确。“跟踪”指悄悄一直跟在某人后面。", "发明": "语义：“发明”指创造新事物，不能用于“一直……她”。", "洗涤": "语义：“洗涤”是用水清洗物品，不能用于人。", "注册": "搭配：“注册”后接的是账号、公司等，不能接人。"}, "sentence_index": 0, "correct_answer": "跟踪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我跟踪朋友说了再见。", "explanation": "这里应该用〈跟〉。跟踪是悄悄跟在别人后面，和别人说话要用介词“跟”。"}, {"text": "她跟踪老人下楼梯，却一直走在老人前面。", "explanation": "这里应该用〈带领〉。跟踪是在后面悄悄跟着，一直走在前面就不是跟踪，应说带领。"}, {"text": "妈妈跟踪孩子穿好了外套。", "explanation": "这里应该用〈帮〉。跟踪是悄悄跟在后面，替孩子穿衣服要说帮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94989, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟踪", "is_correct": true, "explanation": "正确。“跟踪了她一路”指一直悄悄跟在她后面。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去污物，不能表示一路跟随。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，不能表示跟随。"}, {"text": "注射", "is_correct": false, "explanation": "搭配：“注射”后接的是药剂，不能接“她一路”。"}], "explanations": {"跟踪": "正确。“跟踪了她一路”指一直悄悄跟在她后面。", "擦": "语义：“擦”指抹去污物，不能表示一路跟随。", "烧": "语义：“烧”指燃烧或加热，不能表示跟随。", "注射": "搭配：“注射”后接的是药剂，不能接“她一路”。"}, "sentence_index": 6, "correct_answer": "跟踪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "志愿者跟踪这位老人回家，却和老人并排走着。", "explanation": "这里应该用〈陪同〉。跟踪是在后面悄悄跟着，并排走要说陪同。"}, {"text": "导游跟踪大家参观博物馆。", "explanation": "这里应该用〈引导〉。跟踪是在后面跟着观察，带领游客参观要说引导。"}, {"text": "他跟踪了一本书给我。", "explanation": "这里应该用〈送〉。跟踪是悄悄跟在别人后面，把东西给人要说送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们悄悄跟踪了过那个人。", "corrected_sentence": "我们悄悄跟踪过那个人。", "error_description": "“跟踪过”表示曾经做过，“了”与“过”不能叠加在同一动词后，应去掉“了”，说“跟踪过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "侦探一直跟踪了过那个嫌疑人。", "corrected_sentence": "侦探一直跟踪着那个嫌疑人。", "error_description": "“了”与“过”不能叠加在同一动词后，“跟踪了过”不成立。表示持续的“一直”应配“着”，即“一直跟踪着那个嫌疑人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
