INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94990, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持续追踪观察某人、某事或某物的变化和情况。", "primary_collocate": null, "pronunciation": "gēn zōng", "ipa": "kən˥ tsʊŋ˥", "syllable_count": 2, "sentences": [{"text": "医生会跟踪病人的情况。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者跟踪这个案子两年了。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要长期跟踪这个孩子的成长。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司跟踪了每个客户的使用情况。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用卫星跟踪着这场台风。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一直在跟踪学生的学习进步。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能跟踪快递的位置。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们跟踪调查了一千个家庭。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察跟踪调查这个案子三个月了。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院跟踪过这些病人的恢复情况。", "target_word": "跟踪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟蹤", "label": "繁体"}, {"form": "跟踪了", "label": "体标"}, {"form": "跟踪着", "label": "体标"}, {"form": "跟踪过", "label": "体标"}], "register": "中性", "sense_fingerprint": "持续追踪观察某人、某事或某物的变化和情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94990, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟踪", "is_correct": true, "explanation": "正确。“跟踪”指持续观察、掌握某人或某事的变化和情况。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”是身体动作，不能用于“情况”。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋，不说“装修病人的情况”。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指修饰外表，不能用于“情况”。"}], "explanations": {"跟踪": "正确。“跟踪”指持续观察、掌握某人或某事的变化和情况。", "拥抱": "语义：“拥抱”是身体动作，不能用于“情况”。", "装修": "搭配：“装修”的对象是房屋，不说“装修病人的情况”。", "打扮": "语义：“打扮”指修饰外表，不能用于“情况”。"}, "sentence_index": 0, "correct_answer": "跟踪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跟踪了一个苹果。", "explanation": "这里应该用〈吃〉。跟踪指持续观察情况的变化，吃苹果不能说跟踪。"}, {"text": "他跟踪了一杯咖啡。", "explanation": "这里应该用〈喝〉。跟踪指持续观察情况的变化，喝咖啡不能说跟踪。"}, {"text": "我们一起跟踪了一首歌。", "explanation": "这里应该用〈唱〉。跟踪指持续观察情况的变化，唱歌不能说跟踪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟踪", "is_correct": true, "explanation": "正确。“跟踪快递的位置”指持续查看位置的变化。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，不能用于位置。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指涂抹墙面，不能用于位置。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”接的是音视频，不说“播放位置”。"}], "explanations": {"跟踪": "正确。“跟踪快递的位置”指持续查看位置的变化。", "烹饪": "语义：“烹饪”指做饭，不能用于位置。", "粉刷": "语义：“粉刷”指涂抹墙面，不能用于位置。", "播放": "搭配：“播放”接的是音视频，不说“播放位置”。"}, "sentence_index": 6, "correct_answer": "跟踪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班后去医院跟踪爷爷。", "explanation": "这里应该用〈探望〉。跟踪是暗中跟在人后面，去医院看望生病的人要说探望。"}, {"text": "大家一起跟踪他的生日。", "explanation": "这里应该用〈庆祝〉。跟踪指持续观察情况，庆祝生日要说庆祝。"}, {"text": "妈妈跟踪了一桌菜。", "explanation": "这里应该用〈做〉。跟踪指持续观察情况的变化，做菜不能说跟踪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一直跟踪了过这次实验的结果。", "corrected_sentence": "我们一直跟踪着这次实验的结果。", "error_description": "“了”与“过”不能叠加在同一动词后，“跟踪了过”不成立。“一直”表示持续，应配“着”，即“一直跟踪着这次实验的结果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师跟踪了过学生的成绩变化。", "corrected_sentence": "老师跟踪过学生的成绩变化。", "error_description": "“了”与“过”不能叠加在同一动词后，应去掉“了”，说“跟踪过学生的成绩变化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
