INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队中担任排长以上职务的人员。", "primary_collocate": null, "pronunciation": "jūn guān", "ipa": "tɕyn˥ kwan˥", "syllable_count": 2, "sentences": [{"text": "他刚从军校毕业，现在是一名军官。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当了军官以后，他的工资高了很多。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军官和普通士兵住在不同的房子里。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从排长开始，慢慢成了高级军官。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位军官的肩上有两颗星。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要当军官，需要读很多年的军校。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位军官，不是普通的士兵。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我舅舅当了十年军官，后来回家工作了。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加军队以后，他想当军官。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军官出门的时候要穿军装。", "target_word": "军官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "軍官", "label": "繁体"}], "register": "中性", "sense_fingerprint": "军队中排长以上职务的人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '063f9b1f-5b36-425e-8fb6-27ef06b3df50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小学生", "is_correct": false, "explanation": "语义：从军校毕业后不会成为小学生，与语境不符。"}, {"text": "军官", "is_correct": true, "explanation": "军官指军队中担任排长以上职务的人员，符合“从军校毕业，现在是一名”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能担任职务，与“现在是一名……”不符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿无法从军校毕业，与语境矛盾。"}], "explanations": {"小学生": "语义：从军校毕业后不会成为小学生，与语境不符。", "军官": "军官指军队中担任排长以上职务的人员，符合“从军校毕业，现在是一名”的语境。", "石头": "语义：石头不是人，不能担任职务，与“现在是一名……”不符。", "婴儿": "语义：婴儿无法从军校毕业，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "军官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位军官每天早上在花瓶里开花。", "explanation": "这里应该用〈花〉。军官是人，不会在花瓶里开花。"}, {"text": "这位军官已经生锈了，该刷一层漆了。", "explanation": "这里应该用〈铁门〉。军官是人，不会生锈。"}, {"text": "这位军官每天在墙上长出几片叶子。", "explanation": "这里应该用〈树〉。军官是人，不会长出叶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是人，不能说“他是一位苹果”。"}, {"text": "军官", "is_correct": true, "explanation": "军官指军队中担任排长以上职务的人员，与“不是普通的士兵”形成对比。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能作为身份，与“他是一位……”不符。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不具备军队中的职务身份，与语境不符。"}], "explanations": {"苹果": "语义：苹果是水果，不是人，不能说“他是一位苹果”。", "军官": "军官指军队中担任排长以上职务的人员，与“不是普通的士兵”形成对比。", "石头": "语义：石头不是人，不能作为身份，与“他是一位……”不符。", "小孩": "语义：小孩不具备军队中的职务身份，与语境不符。"}, "sentence_index": 6, "correct_answer": "军官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位军官很快就飘走了。", "explanation": "这里应该用〈云〉。军官指人，不能像云一样飘走。"}, {"text": "他用军官打开了门。", "explanation": "这里应该用〈钥匙〉。军官指人，不是工具，不能用来开门。"}, {"text": "孩子们在军官里玩耍。", "explanation": "这里应该用〈花园〉。军官指人，不是地方，不能说“在军官里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的哥哥也当了过军官。", "corrected_sentence": "她的哥哥也当过军官。", "error_description": "“过”已表示曾经有过的经历，“了”与“过”不能同时出现。应说“也当过军官”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条军官是我的老朋友。", "corrected_sentence": "这位军官是我的老朋友。", "error_description": "量词错误：军官是人，应用〈位〉。“条”用于狭长的事物，应改为“这位军官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
