INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94996, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超过一定的程度或限度。", "primary_collocate": null, "pronunciation": "guò fèn", "ipa": "kwo˥˩ fən˥˩", "syllable_count": 2, "sentences": [{"text": "他过分担心孩子，晚上睡不好。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过分紧张会影响考试成绩。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用过分客气，就像在家一样。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过分相信别人，所以常常上当。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过分夸奖自己，大家都不太喜欢他。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对工作过分认真，没有时间休息。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子过分喜欢手机，对眼睛不好。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过分骄傲的人，很难学到新东西。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的灯过分明亮，我睡不着。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，过分节省有时也不好。", "target_word": "过分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度超过限度，修饰动词或形容词，如过分担心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01a5a511-643b-455f-a743-1f7bb54c8652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仔细", "is_correct": false, "explanation": "搭配：“仔细”修饰动作，不修饰“担心”这种心理活动。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意去做，担心孩子不能是故意的。"}, {"text": "过分", "is_correct": true, "explanation": "正确。“过分担心”指担心超过了限度，与“睡不好”相符。"}, {"text": "可惜", "is_correct": false, "explanation": "语义：“可惜”表示遗憾，与担心孩子的语境不符，句意不通。"}], "explanations": {"仔细": "搭配：“仔细”修饰动作，不修饰“担心”这种心理活动。", "故意": "语义：“故意”表示有意去做，担心孩子不能是故意的。", "过分": "正确。“过分担心”指担心超过了限度，与“睡不好”相符。", "可惜": "语义：“可惜”表示遗憾，与担心孩子的语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "过分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你这样说他，真的太过分了。", "explanation": "这里是“过分”的另一义项：作谓语，指言行不合适。本题要的是修饰动词或形容词、表示程度超过限度的用法。"}, {"text": "他迟到一个小时，还不道歉，很过分。", "explanation": "这里是“过分”的另一义项：作谓语，形容言行不合适。这句没有修饰动词或形容词，不是程度超过限度的用法。"}, {"text": "开玩笑可以，但不要过分。", "explanation": "这里是“过分”的另一义项：单独作谓语，指玩笑超过了合适的界限。本题要的是修饰动词或形容词的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严重", "is_correct": false, "explanation": "搭配：“严重”修饰问题、后果，不修饰“喜欢”。"}, {"text": "过分", "is_correct": true, "explanation": "正确。“过分喜欢”说明喜欢超过了限度，修饰动词。"}, {"text": "坚决", "is_correct": false, "explanation": "搭配：“坚决”多修饰拒绝、反对等意志行为，不修饰“喜欢”。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”表示不费力，“轻松喜欢手机”与“对眼睛不好”的语境不符。"}], "explanations": {"严重": "搭配：“严重”修饰问题、后果，不修饰“喜欢”。", "过分": "正确。“过分喜欢”说明喜欢超过了限度，修饰动词。", "坚决": "搭配：“坚决”多修饰拒绝、反对等意志行为，不修饰“喜欢”。", "轻松": "语义：“轻松”表示不费力，“轻松喜欢手机”与“对眼睛不好”的语境不符。"}, "sentence_index": 6, "correct_answer": "过分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这样对待朋友，真的很过分。", "explanation": "这里是“过分”的另一义项：作谓语，指言行不合适。本题要的是修饰动词或形容词、表示程度超过限度的用法。"}, {"text": "他骂人骂得太过分了，大家都很生气。", "explanation": "这里是“过分”的另一义项：作谓语，指言行不合适。本题要的是修饰动词或形容词、表示程度超过限度的用法。"}, {"text": "他总是在半夜打电话，真的太过分了。", "explanation": "这里是“过分”的另一义项：作谓语，指言行不合适。本题要的是修饰动词或形容词、表示程度超过限度的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她过分得节省，连买菜都舍不得花钱。", "corrected_sentence": "她过分节省，连买菜都舍不得花钱。", "error_description": "“过分”修饰动词“节省”时，中间不能加“得”。“过分得节省”多了“得”，应改为“过分节省”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他过分得担心考试，一夜没睡好。", "corrected_sentence": "他过分担心考试，一夜没睡好。", "error_description": "“过分”直接修饰动词“担心”，中间不能加“得”。“过分得担心”多了“得”，应改为“过分担心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
