INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在陆地上作战的军队。", "primary_collocate": null, "pronunciation": "lù jūn", "ipa": "lu˥˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "陆军是在陆地上作战的军队。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥去年参加了陆军。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陆军和海军一起参加了这次演习。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支陆军有两万多人。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陆军的士兵每天早上都要跑步。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷年轻时在陆军工作过。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山多的国家需要很强的陆军。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陆军的坦克慢慢开进了城。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军在海上作战，陆军在陆地上作战。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在播放陆军的新闻。", "target_word": "陆军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一支陆军", "label": "量词搭配"}, {"form": "陆军部队", "label": "复合词"}], "register": "中性", "sense_fingerprint": "军队中在陆地上作战的兵种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陆军", "is_correct": true, "explanation": "“陆军”指在陆地上作战的军队，与定义相符。"}, {"text": "海军", "is_correct": false, "explanation": "语义：“海军”指在海上作战的军队，与“在陆地上作战”相反。"}, {"text": "空军", "is_correct": false, "explanation": "语义：“空军”指在空中作战的军队，与“在陆地上作战”不符。"}, {"text": "警察", "is_correct": false, "explanation": "语义：“警察”负责维持治安，不是作战的军队。"}], "explanations": {"陆军": "“陆军”指在陆地上作战的军队，与定义相符。", "海军": "语义：“海军”指在海上作战的军队，与“在陆地上作战”相反。", "空军": "语义：“空军”指在空中作战的军队，与“在陆地上作战”不符。", "警察": "语义：“警察”负责维持治安，不是作战的军队。"}, "sentence_index": 0, "correct_answer": "陆军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "陆军在海上作战，保护国家。", "explanation": "这里应该用〈海军〉。陆军在陆地上作战，在海上作战要用海军。"}, {"text": "陆军每天在城市里灭火救人。", "explanation": "这里应该用〈消防队〉。陆军负责作战，灭火救人要用消防队。"}, {"text": "陆军在天上巡逻，保护国家。", "explanation": "这里应该用〈空军〉。陆军在地面作战，在天上巡逻要用空军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陆军", "is_correct": true, "explanation": "“陆军”是地面作战的军队，与“山多”的地形相合，填入后语义通顺。"}, {"text": "陆地", "is_correct": false, "explanation": "搭配：“很强的”后不能接“陆地”这种地理名词，搭配不成立。"}, {"text": "山地", "is_correct": false, "explanation": "搭配：“很强的”后接的是军队或人，“山地”是地点，不能搭配。"}, {"text": "海岸", "is_correct": false, "explanation": "搭配：“很强的”后不能接“海岸”这类地点名词，搭配不成立。"}], "explanations": {"陆军": "“陆军”是地面作战的军队，与“山多”的地形相合，填入后语义通顺。", "陆地": "搭配：“很强的”后不能接“陆地”这种地理名词，搭配不成立。", "山地": "搭配：“很强的”后接的是军队或人，“山地”是地点，不能搭配。", "海岸": "搭配：“很强的”后不能接“海岸”这类地点名词，搭配不成立。"}, "sentence_index": 6, "correct_answer": "陆军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陆军在街上卖水果。", "explanation": "这里应该用〈小贩〉。陆军负责作战，在街上卖水果要用小贩。"}, {"text": "陆军在港口卖门票。", "explanation": "这里应该用〈售票员〉。陆军负责作战，在港口卖门票要用售票员。"}, {"text": "陆军在图书馆里借书给读者。", "explanation": "这里应该用〈图书管理员〉。陆军负责作战，在图书馆借书给读者要用图书管理员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条陆军驻扎在边境。", "corrected_sentence": "这支陆军驻扎在边境。", "error_description": "量词错误：“条”用于细长的东西，军队类名词应用量词“支”，正确说法是“这支陆军”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次演习由很陆军负责。", "corrected_sentence": "这次演习由陆军负责。", "error_description": "副词错误：“很”修饰形容词或心理动词，不修饰“陆军”这类名词，“很陆军”不成立，应说“陆军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
