INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "紧接着，立刻。", "primary_collocate": null, "pronunciation": "suí jí", "ipa": "sweɪ˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "灯一亮，大家随即安静下来。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到电话响，她随即拿起了手机。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了一句话，大家随即笑了。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，太阳随即出来了。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生来了，随即给病人检查。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理走进来，大家随即站了起来。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铃声响了，学生们随即回到座位。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔倒了，旁边的人随即跑过去帮他。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发了一条信息，朋友随即回复了。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到火，他随即大声叫了起来。", "target_word": "随即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "紧接着前一件事，立刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '063f9b1f-5b36-425e-8fb6-27ef06b3df50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "随即", "is_correct": true, "explanation": "正确。随即表示紧接着前一件事，立刻发生。"}, {"text": "随时", "is_correct": false, "explanation": "jí 与 shí 声母不同（j/sh），随时指在任何时候。"}, {"text": "随记", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同。随记指随手记下的笔记。"}, {"text": "随机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同。随机指没有规律、任意。"}], "explanations": {"随即": "正确。随即表示紧接着前一件事，立刻发生。", "随时": "jí 与 shí 声母不同（j/sh），随时指在任何时候。", "随记": "jì（第四声）与 jí（第二声）声调不同。随记指随手记下的笔记。", "随机": "jī（第一声）与 jí（第二声）声调不同。随机指没有规律、任意。"}, "sentence_index": null, "correct_answer": "随即"}, "level_3": {"options": [{"text": "随即", "is_correct": true, "explanation": "正确。“灯一亮，大家随即安静下来”表示灯亮后立刻安静。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未如此，与“灯一亮”后大家立刻安静的变化矛盾。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：“始终”表示一直如此，不能与“安静下来”这种表示开始变化的补语搭配。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态延续，与“安静下来”所表示的开始变化矛盾。"}], "explanations": {"随即": "正确。“灯一亮，大家随即安静下来”表示灯亮后立刻安静。", "从来": "语义：“从来”表示从未如此，与“灯一亮”后大家立刻安静的变化矛盾。", "始终": "搭配：“始终”表示一直如此，不能与“安静下来”这种表示开始变化的补语搭配。", "仍然": "语义：“仍然”表示状态延续，与“安静下来”所表示的开始变化矛盾。"}, "sentence_index": 0, "correct_answer": "随即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们等了三个小时，公交车随即来了。", "explanation": "这里应该用〈终于〉。随即表示紧接着、立刻，与“等了三个小时”矛盾。"}, {"text": "他写了信，过了三天，随即收到了回信。", "explanation": "这里应该用〈后来〉。随即表示紧接着、立刻，“过了三天”之后才收到，与之矛盾。"}, {"text": "我放下碗，过了好一会儿随即去洗碗了。", "explanation": "这里应该用〈随后〉。随即表示立刻，“过了好一会儿”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "随即", "is_correct": true, "explanation": "正确。随即表示紧接着前一件事，立刻发生。"}, {"text": "速记", "is_correct": false, "explanation": "sù jì 与 suí jí 韵母、声调都不同。速记指用简便符号快速记录。"}, {"text": "追击", "is_correct": false, "explanation": "zhuī jí 与 suí jí 声母、声调不同（zh/s）。追击指追赶攻击。"}, {"text": "随意", "is_correct": false, "explanation": "yì 与 jí 声母、声调不同。随意指按自己的意思，不受拘束。"}], "explanations": {"随即": "正确。随即表示紧接着前一件事，立刻发生。", "速记": "sù jì 与 suí jí 韵母、声调都不同。速记指用简便符号快速记录。", "追击": "zhuī jí 与 suí jí 声母、声调不同（zh/s）。追击指追赶攻击。", "随意": "yì 与 jí 声母、声调不同。随意指按自己的意思，不受拘束。"}, "sentence_index": null, "correct_answer": "随即"}, "level_3": {"options": [{"text": "随即", "is_correct": true, "explanation": "正确。“铃声响了，学生们随即回到座位”表示铃一响就回座位。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示习惯性的否定，与“铃声响了”这一次的事件矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“回到座位”这种一次性动作搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与铃声一响就回座位的紧接关系矛盾。"}], "explanations": {"随即": "正确。“铃声响了，学生们随即回到座位”表示铃一响就回座位。", "从不": "语义：“从不”表示习惯性的否定，与“铃声响了”这一次的事件矛盾。", "一直": "搭配：“一直”表示持续，不能与“回到座位”这种一次性动作搭配。", "偶尔": "语义：“偶尔”表示不经常，与铃声一响就回座位的紧接关系矛盾。"}, "sentence_index": 6, "correct_answer": "随即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火还在烧，他随即在一旁站着。", "explanation": "这里应该用〈仍然〉。随即表示紧接着前一件事，不能描述状态延续。"}, {"text": "他还在哭，过了半天随即笑了起来。", "explanation": "这里应该用〈终于〉。随即表示紧接着、立刻，“过了半天”之后才笑，与之矛盾。"}, {"text": "他跑了一个小时，过了很久随即到达了学校。", "explanation": "这里应该用〈最终〉。随即表示紧接着、立刻，“过了很久”之后才到达，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLU