INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门一开，猫随即的跑了出去。", "corrected_sentence": "门一开，猫随即跑了出去。", "error_description": "错误：“随即的跑了出去”；正确：“随即跑了出去”。“随即”是副词，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dad82014-6291-4aef-ad40-dae724446334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
