INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95003, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "顺序是一个接着一个的排法。", "primary_collocate": null, "pronunciation": "shùn xù", "ipa": "ʂwən˥˩ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "大家按顺序上车，不要挤。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按顺序来，别插队。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们按顺序发言。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些号码是按顺序排的。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们按顺序走进教室。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生按顺序叫病人的名字。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按顺序上台唱歌。", "target_word": "顺序", "complexity_tier": "T3", "furigana": "shùn xù", "sentence_source": "generated"}, {"text": "公交车上，大家按顺序下车。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队时，大家不能乱了顺序。", "target_word": "顺序", "complexity_tier": "T3", "furigana": "shùn xù", "sentence_source": "generated"}, {"text": "站队的顺序是按身高排的。", "target_word": "顺序", "complexity_tier": "T3", "furigana": "shùn xù", "sentence_source": "generated"}], "morphological_forms": [{"form": "先后顺序", "label": "复合"}, {"form": "順序", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个接着一个的排法，如排队、按顺序做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01a5a511-643b-455f-a743-1f7bb54c8652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顺序", "is_correct": true, "explanation": "正确：“顺序”指一个接着一个的排法，与“按”搭配表示依次上车。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的钱数，与按次序上车无关。"}, {"text": "样子", "is_correct": false, "explanation": "体貌：“样子”指外形，不能用来指上车的先后。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是上车的依据，读来不通。"}], "explanations": {"顺序": "正确：“顺序”指一个接着一个的排法，与“按”搭配表示依次上车。", "价格": "语义：“价格”指商品的钱数，与按次序上车无关。", "样子": "体貌：“样子”指外形，不能用来指上车的先后。", "颜色": "语义：“颜色”不是上车的依据，读来不通。"}, "sentence_index": 0, "correct_answer": "顺序"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个顺序唱得很好听。", "explanation": "这里应该用〈旋律〉。顺序只指先后排列，不能用来“唱”。"}, {"text": "她的顺序一直很勇敢。", "explanation": "这里应该用〈品质〉。顺序只指先后排列，不能用来形容人的勇敢。"}, {"text": "他们定了一座顺序。", "explanation": "这里应该用〈个〉或〈种〉。〈座〉用于山、桥、房屋等大型固定物，不用于顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顺序", "is_correct": true, "explanation": "正确：“顺序”指一个接着一个的排法，与“按”搭配表示依次上台。"}, {"text": "方向", "is_correct": false, "explanation": "语义：“方向”指朝向，上台唱歌不按朝向排。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是人的重量，不能用来安排上台的先后。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”指面部的神色，不能用来排上台次序。"}], "explanations": {"顺序": "正确：“顺序”指一个接着一个的排法，与“按”搭配表示依次上台。", "方向": "语义：“方向”指朝向，上台唱歌不按朝向排。", "体重": "语义：“体重”是人的重量，不能用来安排上台的先后。", "脸色": "体貌：“脸色”指面部的神色，不能用来排上台次序。"}, "sentence_index": 6, "correct_answer": "顺序"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套顺序很好吃。", "explanation": "这里应该用〈菜肴〉。顺序只指排列的先后，不能指可以吃的东西。"}, {"text": "他的顺序很爱吃辣。", "explanation": "这里应该用〈口味〉。顺序只指排列次序，不能用来说饮食喜好。"}, {"text": "她的顺序一直很开朗。", "explanation": "这里应该用〈性格〉。顺序只指排列次序，不能用来形容性格开朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条顺序大家都能接受。", "corrected_sentence": "这种顺序大家都能接受。", "error_description": "量词错误：“顺序”前应用“种”或“个”，“条”用于长条形的事物，不修饰“顺序”。正确说法是“这种顺序”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乘客们按一顺序进站了。", "corrected_sentence": "乘客们按顺序进站了。", "error_description": "“顺序”前不能直接加数词“一”，“按顺序”不需要数量词。“按一顺序”多了“一”，应改为“按顺序”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
