INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物排列的先后次序。", "primary_collocate": null, "pronunciation": "shùn xù", "ipa": "ʂwən˥˩ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "请按时间的顺序写这件事。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些名字的顺序错了。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭要注意菜的下锅顺序。", "target_word": "顺序", "complexity_tier": "T3", "furigana": "shùn xù", "sentence_source": "generated"}, {"text": "孩子们按身高的顺序站好。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书的顺序弄乱了。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的顺序是先买菜，再做饭。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以换一下这两个句子的顺序。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片的顺序是按年份放的。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，写字的顺序不能错。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书把故事的顺序打乱了。", "target_word": "顺序", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "先后顺序", "label": "复合"}, {"form": "順序", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物排列的先后次序，如时间顺序、步骤顺序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01a5a511-643b-455f-a743-1f7bb54c8652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顺序", "is_correct": true, "explanation": "正确：“顺序”指事物先后排列的次序，与“按时间的”搭配，能填入此处。"}, {"text": "距离", "is_correct": false, "explanation": "语义：“距离”指空间上的间隔，不能按时间排列写作。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是可以按时间依次安排的事物，句子读来不通。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人或物的外在样子，不能用来说明写事情的先后。"}], "explanations": {"顺序": "正确：“顺序”指事物先后排列的次序，与“按时间的”搭配，能填入此处。", "距离": "语义：“距离”指空间上的间隔，不能按时间排列写作。", "颜色": "语义：“颜色”不是可以按时间依次安排的事物，句子读来不通。", "外貌": "体貌：“外貌”指人或物的外在样子，不能用来说明写事情的先后。"}, "sentence_index": 0, "correct_answer": "顺序"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中取得了好顺序。", "explanation": "这里应该用〈名次〉。顺序指事物先后排列的次序，比赛中的排位要用名次。"}, {"text": "这座城市的社会顺序非常好。", "explanation": "这里应该用〈秩序〉。顺序只指先后排列；社会有条理的状态要用秩序。"}, {"text": "我们定了一座顺序。", "explanation": "这里应该用〈个〉或〈种〉。〈座〉用于山、桥、房屋等大型固定物，不用于顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顺序", "is_correct": true, "explanation": "正确：“顺序”指句子排列的先后次序，与“换一下”搭配，能填入此处。"}, {"text": "字数", "is_correct": false, "explanation": "语义：“字数”指字的多少，换的是句子的位置，不是字数。"}, {"text": "样子", "is_correct": false, "explanation": "体貌：“样子”指外形，调换两个句子只能改变排列，不能换样子。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是句子的属性，两个句子无法互换颜色。"}], "explanations": {"顺序": "正确：“顺序”指句子排列的先后次序，与“换一下”搭配，能填入此处。", "字数": "语义：“字数”指字的多少，换的是句子的位置，不是字数。", "样子": "体貌：“样子”指外形，调换两个句子只能改变排列，不能换样子。", "颜色": "语义：“颜色”不是句子的属性，两个句子无法互换颜色。"}, "sentence_index": 6, "correct_answer": "顺序"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上课时要遵守课堂顺序。", "explanation": "这里应该用〈纪律〉或〈秩序〉。顺序只指先后排列，课堂上的规矩要用纪律或秩序。"}, {"text": "这套顺序很好吃。", "explanation": "这里应该用〈菜肴〉。顺序只指排列的先后，不能指可以吃的东西。"}, {"text": "他的顺序很开朗。", "explanation": "这里应该用〈性格〉。顺序只指排列次序，不能用来形容性格开朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条顺序很合理。", "corrected_sentence": "这种顺序很合理。", "error_description": "量词错误：“顺序”前应用“种”或“个”，“条”用于长条形的事物，不修饰“顺序”。正确说法是“这种顺序”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些书已经按一顺序摆好了。", "corrected_sentence": "这些书已经按顺序摆好了。", "error_description": "“顺序”前不能直接加数词“一”，“按顺序”不需要数量词。“按一顺序”多了“一”，应改为“按顺序”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95005, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95005, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95005, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头脑是人用来想事情的地方。", "primary_collocate": null, "pronunciation": "tóu nǎo", "ipa": "tʰoʊ˧˥ naʊ˨˩", "syllable_count": 2, "sentences": [{"text": "他的头脑里全是工作。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡一觉，头脑就清楚了。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我头脑里一片空白。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一喝酒，头脑就发昏。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太累了，我的头脑转不动了。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法在我头脑里转了很久。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上头脑最清醒。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想让头脑休息一下。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头脑里想着明天的考试。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些事从头脑里赶走吧。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭腦", "label": "繁体"}, {"form": "头脑风暴", "label": "复合"}], "register": "中性", "sense_fingerprint": "人用来想事情的脑子，指思考时所在的头脑（清醒、发昏、空白）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "头脑", "is_correct": true, "explanation": "头脑指思考的地方，「他的头脑里全是工作」说他心里一直想着工作，符合语义。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋是穿在脚上的东西，里面装不下「工作」，句子说不通。"}, {"text": "脸", "is_correct": false, "explanation": "搭配：「脸里」不能这样说，「里」前面一般接容器或想事情的地方。"}, {"text": "老板", "is_correct": false, "explanation": "配价：「老板」是人，不能充当「里」前面的处所，「他的老板里全是工作」不成立。"}], "explanations": {"头脑": "头脑指思考的地方，「他的头脑里全是工作」说他心里一直想着工作，符合语义。", "鞋": "语义：鞋是穿在脚上的东西，里面装不下「工作」，句子说不通。", "脸": "搭配：「脸里」不能这样说，「里」前面一般接容器或想事情的地方。", "老板": "配价：「老板」是人，不能充当「里」前面的处所，「他的老板里全是工作」不成立。"}, "sentence_index": 0, "correct_answer": "头脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的头脑比我高半个头。", "explanation": "这里应该用〈个子〉。头脑指想事情的地方，不说高矮；说身高要用「个子」。"}, {"text": "他一喝酒，头脑就发红。", "explanation": "这里应该用〈脸〉。头脑指想事情的地方，不能发红；说脸因为喝酒而发红要用「脸」。"}, {"text": "他唱歌时头脑很好听。", "explanation": "这里应该用〈嗓子〉。头脑是思考的地方，不能用来形容声音好听；说声音要用「嗓子」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "头脑", "is_correct": true, "explanation": "头脑指人用来想事情的地方，「清醒」形容它的状态，「早上头脑最清醒」符合语义。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人的意识，「早上天气最清醒」说不通。"}, {"text": "头发", "is_correct": false, "explanation": "体貌：头发是外貌，不会清醒，「早上头发最清醒」不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：「清醒」只用于人的意识，不能用来形容桌子。"}], "explanations": {"头脑": "头脑指人用来想事情的地方，「清醒」形容它的状态，「早上头脑最清醒」符合语义。", "天气": "语义：天气不是人的意识，「早上天气最清醒」说不通。", "头发": "体貌：头发是外貌，不会清醒，「早上头发最清醒」不成立。", "桌子": "搭配：「清醒」只用于人的意识，不能用来形容桌子。"}, "sentence_index": 6, "correct_answer": "头脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用头脑推开了门。", "explanation": "这里应该用〈手〉。头脑指想事情的地方，这句却把它当成能出力推门的身体部位（头）来用，这一用法不对。"}, {"text": "我把头脑放进了书包。", "explanation": "这里应该用〈课本〉。头脑是想事情的地方，不是能拿起来放进书包的东西；放进书包的应是「课本」等物品。"}, {"text": "他的头脑吃了一个苹果。", "explanation": "头脑是想事情的器官，把它当成能吃东西的人来用是错的；「吃苹果」要求人或动物作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那首歌一直在我头脑上转来转去。", "corrected_sentence": "那首歌一直在我头脑里转来转去。", "error_description": "错误形式「头脑上」，正确形式「头脑里」。头脑是想事情的地方，想法在头脑「里」面，不能说「头脑上」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总想把烦心事头脑里赶出去。", "corrected_sentence": "他总想把烦心事从头脑里赶出去。", "error_description": "错误形式「把烦心事头脑里赶出去」，正确形式「把烦心事从头脑里赶出去」。「从……里」表示事情离开的起点，「从」不能省略，漏掉后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
