INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95006, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的思维能力、判断力和聪明程度。", "primary_collocate": null, "pronunciation": "tóu nǎo", "ipa": "tʰoʊ˧˥ naʊ˨˩", "syllable_count": 2, "sentences": [{"text": "他很有头脑，生意做得好。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做决定时要有冷静的头脑。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子头脑很灵活。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她头脑简单，容易相信别人。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有商业头脑。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题，我们要用头脑想办法。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她头脑聪明，学什么都快。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要动动头脑，别总问别人。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事很有头脑，从不乱花钱。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事需要一个有头脑的人来做。", "target_word": "头脑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭腦", "label": "繁体"}, {"form": "头脑风暴", "label": "复合"}], "register": "中性", "sense_fingerprint": "人的思维能力、判断力和聪明程度（有头脑、头脑灵活）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "头脑", "is_correct": true, "explanation": "头脑指思维能力，「很有头脑」说他判断和办事的能力强，与「生意做得好」相符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：「很有」后面不接具体的家具，「很有桌子」说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人的属性，「很有天气」无法表示能力，句子不通。"}, {"text": "胡子", "is_correct": false, "explanation": "体貌：胡子是外貌，不能用「很有」表示能力，「很有胡子，生意做得好」不成立。"}], "explanations": {"头脑": "头脑指思维能力，「很有头脑」说他判断和办事的能力强，与「生意做得好」相符。", "桌子": "搭配：「很有」后面不接具体的家具，「很有桌子」说不通。", "天气": "语义：天气不是人的属性，「很有天气」无法表示能力，句子不通。", "胡子": "体貌：胡子是外貌，不能用「很有」表示能力，「很有胡子，生意做得好」不成立。"}, "sentence_index": 0, "correct_answer": "头脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的头脑有一米八。", "explanation": "这里应该用〈身高〉。头脑指思维能力，不能说有多高；说身高要用「身高」。"}, {"text": "这幅画的头脑很鲜艳。", "explanation": "这里应该用〈颜色〉。头脑指思维能力，不能说鲜艳；描述颜色要用「颜色」。"}, {"text": "她的头脑很白。", "explanation": "这里应该用〈皮肤〉。头脑不能说颜色白；描述皮肤白要用「皮肤」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "头脑", "is_correct": true, "explanation": "头脑指思维能力，「头脑聪明」说她理解和记忆快，与「学什么都快」相符。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是人，没有智力，「她树聪明」说不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「聪明」用来形容人或思维，不能用来形容石头。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有智力，「房子聪明」不成立。"}], "explanations": {"头脑": "头脑指思维能力，「头脑聪明」说她理解和记忆快，与「学什么都快」相符。", "树": "语义：树不是人，没有智力，「她树聪明」说不通。", "石头": "搭配：「聪明」用来形容人或思维，不能用来形容石头。", "房子": "语义：房子没有智力，「房子聪明」不成立。"}, "sentence_index": 6, "correct_answer": "头脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的头脑很鲜。", "explanation": "这里应该用〈味道〉。头脑指思维能力，不能说鲜；描述菜的口感要用「味道」。"}, {"text": "她的头脑很甜。", "explanation": "这里应该用〈声音〉。头脑不能用来形容甜；描述声音甜要用「声音」。"}, {"text": "火车的头脑很快。", "explanation": "这里应该用〈速度〉。头脑指思维能力，不能用来说快慢；描述快慢要用「速度」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个经理有很头脑，做事很稳。", "corrected_sentence": "这个经理很有头脑，做事很稳。", "error_description": "错误形式「有很头脑」，正确形式「很有头脑」。「很」是修饰「有」的副词，要放在「有」前面，不能放在「有」后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师是个有头脑人。", "corrected_sentence": "这位老师是个有头脑的人。", "error_description": "错误形式「有头脑人」，正确形式「有头脑的人」。修饰名词的短语「有头脑」后面要加「的」，不能直接接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
