INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95007, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95007, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "体会是自己亲身做过才明白。", "primary_collocate": null, "pronunciation": "tǐ huì", "ipa": "tʰi˨˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "只有自己做过，才能体会到父母的辛苦。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚来中国时，没体会过一个人生活的难处。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了老师以后，才体会到这份工作不容易。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你没爬过山，很难体会爬山的快乐。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在国外一年，我体会了生活的不容易。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自己带孩子以后，我才体会到妈妈有多累。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去农村住几天，你就会体会到农民的辛苦。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你亲自试一试，就能体会这种感觉。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作很多年，深深体会到学习的重要。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没送过快递的人，体会不到我们的辛苦。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "体会了", "label": "完成体"}, {"form": "体会过", "label": "经历体"}, {"form": "体会着", "label": "持续体"}, {"form": "体会体会", "label": "重叠"}], "register": "中性", "sense_fingerprint": "自己亲自做过之后才真正明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体会", "is_correct": true, "explanation": "“体会”指亲身经历后才真正明白，与“只有自己做过”的语境相符。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象多是舒适、愉快的事物，不能说享受父母的辛苦。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”指用钱买东西，与“父母的辛苦”这种感受无关。"}, {"text": "得到", "is_correct": false, "explanation": "语义：“得到”指获得可以拥有的东西，不能用来说得到辛苦。"}], "explanations": {"体会": "“体会”指亲身经历后才真正明白，与“只有自己做过”的语境相符。", "享受": "搭配：“享受”的对象多是舒适、愉快的事物，不能说享受父母的辛苦。", "购买": "语义：“购买”指用钱买东西，与“父母的辛苦”这种感受无关。", "得到": "语义：“得到”指获得可以拥有的东西，不能用来说得到辛苦。"}, "sentence_index": 0, "correct_answer": "体会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书包里体会到了一把钥匙。", "explanation": "这里应该用〈发现〉。体会指通过亲身经历而理解道理或感受，找到具体物品要用发现。"}, {"text": "我在操场上体会到了很大的声音。", "explanation": "这里应该用〈听到〉。体会用于理解和感受，听见声音要用听到。"}, {"text": "我在黑暗中体会到了墙上的一个开关。", "explanation": "这里应该用〈摸到〉。体会不能指通过触摸找到东西，摸到开关要用摸到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体会", "is_correct": true, "explanation": "“体会到”指亲身经历后理解农民的辛苦，与“去农村住几天”的语境相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“体会到”的意思相反，“忘记到农民的辛苦”句意不通。"}, {"text": "赚取", "is_correct": false, "explanation": "语义：“赚取”指通过劳动或交易获得钱财，与“辛苦”这种感受不搭。"}, {"text": "查看", "is_correct": false, "explanation": "语义：“查看”指检查、察看资料或情况，不能用来表示亲身感受到辛苦。"}], "explanations": {"体会": "“体会到”指亲身经历后理解农民的辛苦，与“去农村住几天”的语境相符。", "忘记": "语义：“忘记”与“体会到”的意思相反，“忘记到农民的辛苦”句意不通。", "赚取": "语义：“赚取”指通过劳动或交易获得钱财，与“辛苦”这种感受不搭。", "查看": "语义：“查看”指检查、察看资料或情况，不能用来表示亲身感受到辛苦。"}, "sentence_index": 6, "correct_answer": "体会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在超市体会到了一箱牛奶。", "explanation": "这里应该用〈买到〉。体会用于理解道理或感受，买来的东西要用买到。"}, {"text": "我这次体会到了一百分。", "explanation": "这里应该用〈考到〉。体会不能指取得分数，考试得分要用考到。"}, {"text": "我在树上体会到了一个苹果。", "explanation": "这里应该用〈摘到〉。体会不能指摘下的东西，摘到水果要用摘到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我慢慢体会了到生活的不容易。", "corrected_sentence": "我慢慢体会到了生活的不容易。", "error_description": "错误在于“到”与“了”的顺序。“体会”后应先接结果补语“到”，再接体标“了”，正确说法是“体会到了”，“体会了到”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我年轻时在工厂干过，现在才体会在那份辛苦。", "corrected_sentence": "我年轻时在工厂干过，现在才体会到那份辛苦。", "error_description": "错误在于结果补语“到”被换成了“在”。“体会”后接结果补语应用“到”，“体会在”不成立，正确说法是“体会到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
