INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95008, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过亲身经历而理解、领会。", "primary_collocate": null, "pronunciation": "tǐ huì", "ipa": "tʰi˨˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "通过这次旅行，我体会到了朋友的重要。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在医院工作后，体会到了生命的意义。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在老房子里，我慢慢体会着旧时光的节奏。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛让我深深体会到团队的力量。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外生活多年，体会过很多不同的文化。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你体会一下这首歌里的感情吧。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我慢慢体会出了老师那句话的意思。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了半年汉语，我体会到要多开口说才能进步。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次一个人生活，我体会了独立的不容易。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说工作累，现在我终于体会到了。", "target_word": "体会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "体会了", "label": "完成体"}, {"form": "体会过", "label": "经历体"}, {"form": "体会着", "label": "持续体"}, {"form": "体会体会", "label": "重叠"}], "register": "中性", "sense_fingerprint": "经过亲身经历而理解并领会道理或感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体会", "is_correct": true, "explanation": "“体会”指通过经历而领会道理，与“通过这次旅行”的语境相符。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多与愉快的事物搭配，不能说享受朋友的重要。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”指不重视，与“体会到朋友的重要”的意思相反。"}, {"text": "赚取", "is_correct": false, "explanation": "语义：“赚取”指获得钱财，与“朋友的重要”这种道理无关。"}], "explanations": {"体会": "“体会”指通过经历而领会道理，与“通过这次旅行”的语境相符。", "享受": "搭配：“享受”多与愉快的事物搭配，不能说享受朋友的重要。", "忽视": "语义：“忽视”指不重视，与“体会到朋友的重要”的意思相反。", "赚取": "语义：“赚取”指获得钱财，与“朋友的重要”这种道理无关。"}, "sentence_index": 0, "correct_answer": "体会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在树林里体会到了一只鹿。", "explanation": "这里应该用〈看见〉。体会指理解道理或感受，看见动物要用看见。"}, {"text": "我在菜市场体会到了一把青菜。", "explanation": "这里应该用〈买到〉。体会不能指买来的具体物品，买到青菜要用买到。"}, {"text": "我昨晚体会到了奶奶。", "explanation": "这里应该用〈梦见〉。体会指亲身经历后理解，梦中见到某人要用梦见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体会", "is_correct": true, "explanation": "“体会出”指通过琢磨而领会，与“老师那句话的意思”相符，填入后语义通顺。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”指用钱换取物品，不能说买出一句话的意思。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕出”指用力扯开，不能与“意思”搭配。"}, {"text": "收", "is_correct": false, "explanation": "语义：“收”指收取或收拾，与领会话语的意思无关。"}], "explanations": {"体会": "“体会出”指通过琢磨而领会，与“老师那句话的意思”相符，填入后语义通顺。", "买": "语义：“买”指用钱换取物品，不能说买出一句话的意思。", "撕": "搭配：“撕出”指用力扯开，不能与“意思”搭配。", "收": "语义：“收”指收取或收拾，与领会话语的意思无关。"}, "sentence_index": 6, "correct_answer": "体会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天体会到一封信。", "explanation": "这里应该用〈收到〉。体会用于理解道理或感受，收到具体的信件要用收到。"}, {"text": "我终于体会到了丢失的钥匙。", "explanation": "这里应该用〈找到〉。体会不能用来说找回具体物品，找到钥匙要用找到。"}, {"text": "我体会到了最后一张票。", "explanation": "这里应该用〈抢到〉。体会不能指抢得的具体东西，抢到票要用抢到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在农村待了一年，慢慢体会了到生活的意义。", "corrected_sentence": "她在农村待了一年，慢慢体会到了生活的意义。", "error_description": "错误在于“到”与“了”的顺序。应说“体会到了”，先接结果补语“到”，再接体标“了”，“体会了到”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我终于体会在了这份工作的不容易。", "corrected_sentence": "我终于体会到了这份工作的不容易。", "error_description": "错误在于结果补语“到”被换成了“在”。“体会”后接结果补语应用“到”，“体会在”不成立，正确说法是“体会到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
