INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95009, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "党委是党里管事的一群人。", "primary_collocate": null, "pronunciation": "dǎng wěi", "ipa": "taŋ˨˩˦ weɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "党委开会讨论这件事。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的党委有九个人。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司党委的成员。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党委决定明年建一座新楼。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要先问党委。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党委的人都来参加会议了。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂党委很关心工人的生活。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院党委工作。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党委每个月开一次会。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党委里有三位女同志。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "党委会", "label": "复合"}], "register": "正式", "sense_fingerprint": "单位或地方里负责管理事务的党的领导成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95009, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "党委", "is_correct": true, "explanation": "党委：党的委员会，可以开会、讨论事情。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有思维，不能开会讨论事情。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“开会”要求人或组织作主语，小狗不能开会。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不能开会讨论这件事。"}], "explanations": {"党委": "党委：党的委员会，可以开会、讨论事情。", "石头": "语义：石头没有思维，不能开会讨论事情。", "小狗": "搭配：“开会”要求人或组织作主语，小狗不能开会。", "水": "语义：水是液体，不能开会讨论这件事。"}, "sentence_index": 0, "correct_answer": "党委"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "党委昨天生病住院了。", "explanation": "这里应该用〈委员〉。党委是机构，不会生病住院，指人要用“委员”。"}, {"text": "我们学校有一条党委。", "explanation": "这里应该用〈个〉。党委是机构，量词用“个”或“届”，“条”用于细长的东西。"}, {"text": "这位党委每天很早来办公室。", "explanation": "这里应该用〈领导〉。“这位”指人，党委是机构，不能这样指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "党委", "is_correct": true, "explanation": "党委：工厂里的党的领导机构，能够关心工人的生活。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“关心”一般以人或组织作主语，机器不能关心工人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有感情，不会关心工人的生活。"}, {"text": "大门", "is_correct": false, "explanation": "语义：大门是建筑部件，没有感情，不能关心工人的生活。"}], "explanations": {"党委": "党委：工厂里的党的领导机构，能够关心工人的生活。", "机器": "搭配：“关心”一般以人或组织作主语，机器不能关心工人。", "窗户": "语义：窗户没有感情，不会关心工人的生活。", "大门": "语义：大门是建筑部件，没有感情，不能关心工人的生活。"}, "sentence_index": 6, "correct_answer": "党委"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位党委每次都准时到场。", "explanation": "这里应该用〈委员〉。“这位”指人，党委是机构，指人要用“委员”。"}, {"text": "我们公司有一位党委。", "explanation": "这里应该用〈个〉。“位”用于人，党委是机构，量词应为“个”。"}, {"text": "党委每天都备课到很晚。", "explanation": "这里应该用〈老师〉。党委是机构，不能备课，指备课的人要用“老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院有一位党委。", "corrected_sentence": "这家医院有一个党委。", "error_description": "量词错误：“党委”是机构，应使用量词“个”。“位”只用于人，应说“一个党委”，不能说“一位党委”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个工厂都有一位党委。", "corrected_sentence": "每个工厂都有一个党委。", "error_description": "量词错误：“党委”是机构，应使用量词“个”；“位”只用于人，不能说“一位党委”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
