INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "党的各级领导机构的委员会。", "primary_collocate": null, "pronunciation": "dǎng wěi", "ipa": "taŋ˨˩˦ weɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "市党委发了一份新通知。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县党委在这座楼里办公。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各级党委都要学习这个文件。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校党委开会选出了新领导。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省党委的工作很多。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党委是党的领导机构。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单位的党委在三楼。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该听党委的意见。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司党委发出了通知。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他进党委。", "target_word": "党委", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "党委会", "label": "复合"}], "register": "正式", "sense_fingerprint": "党在各级组织中的领导机构，即委员会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "党委", "is_correct": true, "explanation": "党委：党的各级领导机构，能够发布通知。"}, {"text": "市区", "is_correct": false, "explanation": "语义：市区是地区，不能发布通知。"}, {"text": "市集", "is_correct": false, "explanation": "语义：市集是集市，没有管理权，不能发布通知。"}, {"text": "市场", "is_correct": false, "explanation": "搭配：“发通知”要求有管理权的机构作主语，市场一般不发通知。"}], "explanations": {"党委": "党委：党的各级领导机构，能够发布通知。", "市区": "语义：市区是地区，不能发布通知。", "市集": "语义：市集是集市，没有管理权，不能发布通知。", "市场": "搭配：“发通知”要求有管理权的机构作主语，市场一般不发通知。"}, "sentence_index": 0, "correct_answer": "党委"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位党委讲得很好。", "explanation": "这里应该用〈领导〉。“这位”指人，党委是机构，不能这样指人。"}, {"text": "我们学校有一名党委。", "explanation": "这里应该用〈个〉。“名”用于人，党委是机构，量词应为“个”。"}, {"text": "党委昨天感冒请假了。", "explanation": "这里应该用〈委员〉。党委是机构，不会感冒请假，指人要用“委员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "党委", "is_correct": true, "explanation": "党委：单位里负责管理事务的党的领导机构，能位于三楼办公。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是能位于楼层的实体，不能在三楼。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“在三楼”要求能处于某处的实体，工资不能说在某层楼。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能位于某座楼的某一层。"}], "explanations": {"党委": "党委：单位里负责管理事务的党的领导机构，能位于三楼办公。", "天空": "语义：天空不是能位于楼层的实体，不能在三楼。", "工资": "搭配：“在三楼”要求能处于某处的实体，工资不能说在某层楼。", "太阳": "语义：太阳不能位于某座楼的某一层。"}, "sentence_index": 6, "correct_answer": "党委"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "党委每天都救治病人。", "explanation": "这里应该用〈医生〉。党委是机构，不能救治病人，指人要用“医生”。"}, {"text": "我们单位有一位党委。", "explanation": "这里应该用〈个〉。“位”用于人，党委是机构，量词应为“个”。"}, {"text": "那位党委总是迟到。", "explanation": "这里应该用〈委员〉。“那位”指人，党委是机构，指人要用“委员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条县党委有九个委员。", "corrected_sentence": "这个县党委有九个委员。", "error_description": "量词错误：“党委”是机构，修饰它的指示量词应为“这个”。“这条”用于细长的东西，不能用于机构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
