INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95012, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "言行卑鄙、低级，令人瞧不起。", "primary_collocate": null, "pronunciation": "xià zuo", "ipa": "ɕia˥˩ tswo", "syllable_count": 2, "sentences": [{"text": "他说话下作，没人愿意理他。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人举止下作，让人讨厌。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑话又低级又下作。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她骂人的话太下作了。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的行为下作，员工都走了。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别学他那种下作的样子。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里的人物言行下作。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿别人的隐私开玩笑，真下作。", "target_word": "下作", "complexity_tier": "T3", "furigana": "tā ná biérén de yǐnsī kāi wánxiào, zhēn xiàzuo.", "sentence_source": "generated"}, {"text": "比赛输了就骂人，这样太下作。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了出名，手段越来越下作。", "target_word": "下作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "言行卑鄙低级令人瞧不起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '109ed30c-9583-414f-9809-33e9e60b7ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下作", "is_correct": true, "explanation": "下作：言行卑鄙低级，与“说话让人不愿理他”的情形相符。"}, {"text": "亲切", "is_correct": false, "explanation": "语义：“亲切”指态度和气、令人愿意接近，与“没人愿意理他”矛盾。"}, {"text": "礼貌", "is_correct": false, "explanation": "语义：“礼貌”指待人有礼，与“没人愿意理他”的结果冲突。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材，不能用来形容说话。"}], "explanations": {"下作": "下作：言行卑鄙低级，与“说话让人不愿理他”的情形相符。", "亲切": "语义：“亲切”指态度和气、令人愿意接近，与“没人愿意理他”矛盾。", "礼貌": "语义：“礼貌”指待人有礼，与“没人愿意理他”的结果冲突。", "高大": "搭配：“高大”形容身材，不能用来形容说话。"}, "sentence_index": 0, "correct_answer": "下作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把作业忘在家里，很下作。", "explanation": "这里应该用〈粗心〉。下作指言行卑鄙低级，忘带作业只是疏忽，不涉及品行。"}, {"text": "听到喜讯，他很下作。", "explanation": "这里应该用〈激动〉。下作形容卑鄙低级的言行，听到好消息的兴奋不能用它来形容。"}, {"text": "他考了第一名，显得很下作。", "explanation": "这里应该用〈骄傲〉。下作指言行卑鄙、令人瞧不起，因成绩好而自豪不属于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下作", "is_correct": true, "explanation": "下作：言行卑鄙低级，正是电影里人物言行的特点。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不能用来形容言行。"}, {"text": "茂盛", "is_correct": false, "explanation": "搭配：“茂盛”形容草木生长旺盛，不能修饰“言行”。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能修饰“言行”。"}], "explanations": {"下作": "下作：言行卑鄙低级，正是电影里人物言行的特点。", "矮小": "体貌：“矮小”形容身材，不能用来形容言行。", "茂盛": "搭配：“茂盛”形容草木生长旺盛，不能修饰“言行”。", "雪白": "搭配：“雪白”形容颜色，不能修饰“言行”。"}, "sentence_index": 6, "correct_answer": "下作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "航班快要起飞了，他很下作。", "explanation": "这里应该用〈着急〉。下作指言行卑鄙低级，为赶时间而焦急不属于这种情况。"}, {"text": "比赛没赢，我很下作。", "explanation": "这里应该用〈失望〉。下作形容卑鄙低级的言行，输掉比赛的心情不能用它来形容。"}, {"text": "昨晚没睡好，他一直很下作。", "explanation": "这里应该用〈困〉。下作指言行卑鄙低级，睡眠不足的状态与品行无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下作样子让人讨厌。", "corrected_sentence": "他下作的样子让人讨厌。", "error_description": "“下作”修饰名词“样子”，中间需要加“的”，漏掉“的”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骂人骂很下作。", "corrected_sentence": "他骂人骂得很下作。", "error_description": "“下作”作补语说明“骂”的情况，二者之间需用“得”连接，漏掉“得”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95013, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有利", "is_correct": true, "explanation": "“有利”与“不利”是反义词，都指对事情或处境有没有好处。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容环境整洁，与“不利”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事情或结构繁多，与“不利”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情愉快，与“不利”没有反义关系。"}], "correct_answer": "有利", "explanations": {"有利": "“有利”与“不利”是反义词，都指对事情或处境有没有好处。", "干净": "“干净”形容环境整洁，与“不利”没有反义关系。", "复杂": "“复杂”形容事情或结构繁多，与“不利”没有反义关系。", "高兴": "“高兴”形容心情愉快，与“不利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95013, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有利", "is_correct": true, "explanation": "“有利”与“不利”是反义词，都指对事情或处境有没有好处。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”形容排列有序，与“不利”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”形容态度郑重，与“不利”没有反义关系。"}, {"text": "大方", "is_correct": false, "explanation": "“大方”形容举止不拘谨或不吝啬，与“不利”没有反义关系。"}], "correct_answer": "有利", "explanations": {"有利": "“有利”与“不利”是反义词，都指对事情或处境有没有好处。", "整齐": "“整齐”形容排列有序，与“不利”没有反义关系。", "严肃": "“严肃”形容态度郑重，与“不利”没有反义关系。", "大方": "“大方”形容举止不拘谨或不吝啬，与“不利”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95013, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不利是对事情没有好处。", "primary_collocate": null, "pronunciation": "bù lì", "ipa": "pu˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "太晚睡觉对健康不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新规定对小公司不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的年纪对找工作不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时下大雨，对我们不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话太直对你的工作不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈话对我很不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路太远，对老人看病不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比分落后，形势对球队不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后独自走路，对女性很不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价上涨，对买房的人不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不利于", "label": "复合"}], "register": "中性", "sense_fingerprint": "对事情没有好处，对某人某事不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95013, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不利", "is_correct": true, "explanation": "正确答案：“不利”，意思是没有好处，对事情或处境不好。"}, {"text": "不理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“不理”指不搭理。"}, {"text": "富丽", "is_correct": false, "explanation": "f 与 b 声母不同，“富丽”指华丽，意思与“不利”不同。"}, {"text": "目力", "is_correct": false, "explanation": "m 与 b 声母不同，“目力”指视力，意思与“不利”不同。"}, {"text": "不乐", "is_correct": false, "explanation": "lè（第四声）与 lì（第四声）韵母不同，“不乐”指不高兴。"}], "explanations": {"不利": "正确答案：“不利”，意思是没有好处，对事情或处境不好。", "不理": "lǐ（第三声）与 lì（第四声）声调不同，“不理”指不搭理。", "富丽": "f 与 b 声母不同，“富丽”指华丽，意思与“不利”不同。", "目力": "m 与 b 声母不同，“目力”指视力，意思与“不利”不同。", "不乐": "lè（第四声）与 lì（第四声）韵母不同，“不乐”指不高兴。"}, "sentence_index": null, "correct_answer": "不利"}, "level_3": {"options": [{"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能用来形容健康。"}, {"text": "好听", "is_correct": false, "explanation": "搭配：“好听”形容声音，与“健康”不搭配。"}, {"text": "不利", "is_correct": true, "explanation": "“不利”说明太晚睡觉对健康没有好处，与“对健康”搭配自然。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面或地方的气氛，不能用来形容健康。"}], "explanations": {"宽敞": "搭配：“宽敞”形容空间，不能用来形容健康。", "好听": "搭配：“好听”形容声音，与“健康”不搭配。", "不利": "“不利”说明太晚睡觉对健康没有好处，与“对健康”搭配自然。", "热闹": "语义：“热闹”形容场面或地方的气氛，不能用来形容健康。"}, "sentence_index": 0, "correct_answer": "不利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间房间很不利。", "explanation": "这里应该用〈干净〉。形容环境整洁要用〈干净〉，不利说的是对某人或某事没有好处。"}, {"text": "他的笑容很不利。", "explanation": "这里应该用〈灿烂〉。形容笑容的样子要用〈灿烂〉或〈甜美〉，不利说的是对事情或处境没有好处，不用来描述表情。"}, {"text": "他的脚步很不利。", "explanation": "这里应该用〈轻快〉。形容走路的样子要用〈轻快〉或〈沉重〉，不利说的是对事情或处境没有好处，不用来描述脚步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95013, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不利", "is_correct": true, "explanation": "正确答案：“不利”，意思是没有好处，对事情或处境不好。"}, {"text": "不必", "is_correct": false, "explanation": "bì（第四声）与 lì（第四声）声母不同，“不必”指没有必要。"}, {"text": "不计", "is_correct": false, "explanation": "jì（第四声）与 lì（第四声）声母不同，“不计”指不计较。"}, {"text": "不易", "is_correct": false, "explanation": "yì（第四声）与 lì（第四声）声母不同，“不易”指不容易。"}, {"text": "互利", "is_correct": false, "explanation": "h 与 b 声母不同，“互利”指双方都有好处，与“不利”意思相反。"}], "explanations": {"不利": "正确答案：“不利”，意思是没有好处，对事情或处境不好。", "不必": "bì（第四声）与 lì（第四声）声母不同，“不必”指没有必要。", "不计": "jì（第四声）与 lì（第四声）声母不同，“不计”指不计较。", "不易": "yì（第四声）与 lì（第四声）声母不同，“不易”指不容易。", "互利": "h 与 b 声母不同，“互利”指双方都有好处，与“不利”意思相反。"}, "sentence_index": null, "correct_answer": "不利"}, "level_3": {"options": [{"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人的谈吐风趣，与看病无关，句子说不通。"}, {"text": "凉快", "is_correct": false, "explanation": "搭配：“凉快”形容温度或感觉，不能用来形容看病。"}, {"text": "新鲜", "is_correct": false, "explanation": "搭配：“新鲜”形容食物、空气等的状态，不能用来形容看病。"}, {"text": "不利", "is_correct": true, "explanation": "“不利”说明路太远对老人看病没有好处，与“对老人看病”搭配自然。"}], "explanations": {"幽默": "语义：“幽默”形容人的谈吐风趣，与看病无关，句子说不通。", "凉快": "搭配：“凉快”形容温度或感觉，不能用来形容看病。", "新鲜": "搭配：“新鲜”形容食物、空气等的状态，不能用来形容看病。", "不利": "“不利”说明路太远对老人看病没有好处，与“对老人看病”搭配自然。"}, "sentence_index": 6, "correct_answer": "不利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家对这次涨价很不利。", "explanation": "这里应该用〈不满〉。对某件事的情绪要用〈不满〉，不利只说事情带来的客观坏处，不表示情绪。"}, {"text": "听到好消息，他很不利。", "explanation": "这里应该用〈高兴〉。表示心情要用〈高兴〉，不利不用来形容人的心情。"}, {"text": "这块蛋糕很不利。", "explanation": "这里应该用〈好吃〉。形容食物的味道要用〈好吃〉，不利说的是对事情或处境没有好处，不用来评价食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天天加班，对身体很不利于，应该注意休息。", "corrected_sentence": "天天加班，对身体很不利，应该注意休息。", "error_description": "“不利于”错误：“不利于”后面必须带宾语，不能直接放在“很”后面。应去掉“于”，说“对身体很不利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个政策对年轻人被很不利。", "corrected_sentence": "这个政策对年轻人很不利。", "error_description": "“被”字句错误：“很不利”是形容词作谓语，前面不能加“被”。应去掉“被”，说“这个政策对年轻人很不利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95014, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有利", "is_correct": true, "explanation": "“有利”与“不利”是反义词，都指对事情或处境有没有好处。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“不利”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外表好看，与“不利”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境的状态，与“不利”没有反义关系。"}], "correct_answer": "有利", "explanations": {"有利": "“有利”与“不利”是反义词，都指对事情或处境有没有好处。", "聪明": "“聪明”形容人的智力，与“不利”没有反义关系。", "漂亮": "“漂亮”形容外表好看，与“不利”没有反义关系。", "安静": "“安静”形容声音或环境的状态，与“不利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
