INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95014, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有好处，对事情发展或人的处境不利。", "primary_collocate": null, "pronunciation": "bù lì", "ipa": "pu˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "天气对比赛很不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息对公司很不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熬夜对身体不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨对我们的旅行不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做对你很不利，你最好再想想。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在比赛中的位置很不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证据对他非常不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风对出海的船很不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里道路湿滑，对开车很不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的情况对他很不利。", "target_word": "不利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不利于", "label": "复合"}], "register": "中性", "sense_fingerprint": "对事情发展或人的处境没有好处，形势、条件、消息等对某人某事不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不利", "is_correct": true, "explanation": "正确答案：“不利”，意思是没有好处，对事情或处境不好。"}, {"text": "不理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“不理”意思是不搭理。"}, {"text": "互利", "is_correct": false, "explanation": "h 与 b 声母不同，“互利”指双方都有好处，与“不利”意思相反。"}, {"text": "富丽", "is_correct": false, "explanation": "f 与 b 声母不同，“富丽”指华丽、豪华，意思与“不利”不同。"}, {"text": "目力", "is_correct": false, "explanation": "m 与 b 声母不同，“目力”指视力，意思与“不利”不同。"}], "explanations": {"不利": "正确答案：“不利”，意思是没有好处，对事情或处境不好。", "不理": "lǐ（第三声）与 lì（第四声）声调不同，“不理”意思是不搭理。", "互利": "h 与 b 声母不同，“互利”指双方都有好处，与“不利”意思相反。", "富丽": "f 与 b 声母不同，“富丽”指华丽、豪华，意思与“不利”不同。", "目力": "m 与 b 声母不同，“目力”指视力，意思与“不利”不同。"}, "sentence_index": null, "correct_answer": "不利"}, "level_3": {"options": [{"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容环境或人的状态，不能用来形容天气对比赛的情况。"}, {"text": "不利", "is_correct": true, "explanation": "“不利”说明天气对比赛没有好处，与“天气对比赛”搭配自然。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，天气没有智力，句子说不通。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示人的情绪，天气和比赛不会有心情，句子说不通。"}], "explanations": {"安静": "搭配：“安静”形容环境或人的状态，不能用来形容天气对比赛的情况。", "不利": "“不利”说明天气对比赛没有好处，与“天气对比赛”搭配自然。", "聪明": "语义：“聪明”形容人的智力，天气没有智力，句子说不通。", "高兴": "语义：“高兴”表示人的情绪，天气和比赛不会有心情，句子说不通。"}, "sentence_index": 0, "correct_answer": "不利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套很不利，穿在我身上太大了。", "explanation": "这里应该用〈不合身〉。形容衣服大小合不合适要用〈不合身〉，不利说的是对事情发展或处境没有好处，不用来形容衣服尺寸。"}, {"text": "这批货的质量很不利，我们最好退掉。", "explanation": "这里应该用〈不好〉。形容事物本身的质量要用〈不好〉，不利强调对某事或某人没有好处。"}, {"text": "他昨晚没睡好，今天身体很不利。", "explanation": "这里应该用〈不舒服〉。描述身体的感受要用〈不舒服〉，不利描述的是处境或情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95014, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不利", "is_correct": true, "explanation": "正确答案：“不利”，意思是没有好处，对事情或处境不好。"}, {"text": "不必", "is_correct": false, "explanation": "bì（第四声）与 lì（第四声）声母不同，“不必”指没有必要。"}, {"text": "不计", "is_correct": false, "explanation": "jì（第四声）与 lì（第四声）声母不同，“不计”指不计较。"}, {"text": "不易", "is_correct": false, "explanation": "yì（第四声）与 lì（第四声）声母不同，“不易”指不容易。"}, {"text": "不乐", "is_correct": false, "explanation": "lè（第四声）与 lì（第四声）韵母不同，“不乐”指不高兴。"}], "explanations": {"不利": "正确答案：“不利”，意思是没有好处，对事情或处境不好。", "不必": "bì（第四声）与 lì（第四声）声母不同，“不必”指没有必要。", "不计": "jì（第四声）与 lì（第四声）声母不同，“不计”指不计较。", "不易": "yì（第四声）与 lì（第四声）声母不同，“不易”指不容易。", "不乐": "lè（第四声）与 lì（第四声）韵母不同，“不乐”指不高兴。"}, "sentence_index": null, "correct_answer": "不利"}, "level_3": {"options": [{"text": "清淡", "is_correct": false, "explanation": "语义：“清淡”形容味道或颜色，证据不能用来形容对人的作用。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来形容证据对人的作用。"}, {"text": "不利", "is_correct": true, "explanation": "“不利”说明证据对他有坏处，与“证据对他”搭配自然。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容人的年龄，证据没有年龄，句子说不通。"}], "explanations": {"清淡": "语义：“清淡”形容味道或颜色，证据不能用来形容对人的作用。", "响亮": "搭配：“响亮”形容声音，不能用来形容证据对人的作用。", "不利": "“不利”说明证据对他有坏处，与“证据对他”搭配自然。", "年轻": "语义：“年轻”形容人的年龄，证据没有年龄，句子说不通。"}, "sentence_index": 6, "correct_answer": "不利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对这家饭店的服务很不利。", "explanation": "这里应该用〈不满〉。对某件事的情绪要用〈不满〉，不利只说客观上的坏处，不表示情绪。"}, {"text": "这个苹果很不利。", "explanation": "这里应该用〈甜〉。形容食物的味道要用〈甜〉，不利说的是对事情或处境没有好处，不用来形容味道。"}, {"text": "这双鞋很不利。", "explanation": "这里应该用〈合脚〉。形容鞋子合不合脚要用〈合脚〉，不利说的是对事情或处境没有好处，不用来评价鞋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "浓雾对夜间航行的船只很不利于。", "corrected_sentence": "浓雾对夜间航行的船只很不利。", "error_description": "“不利于”错误：“不利于”是动词性的固定结构，后面必须带宾语，不能直接放在“很”后面作谓语。应去掉“于”，说“很不利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "报告里全是错误，这对你的申请被很不利。", "corrected_sentence": "报告里全是错误，这对你的申请很不利。", "error_description": "“被”字句错误：“很不利”是形容词作谓语，前面不能加“被”。应去掉“被”，说“这对你的申请很不利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改变", "is_correct": true, "explanation": "「改变」与「不变」意思相反，表示变得和以前不一样。"}, {"text": "生长", "is_correct": false, "explanation": "「生长」与「不变」没有反义关系，指生物长大。"}, {"text": "移动", "is_correct": false, "explanation": "「移动」与「不变」没有反义关系，指位置改变。"}, {"text": "游泳", "is_correct": false, "explanation": "「游泳」与「不变」没有反义关系，指在水中活动。"}], "correct_answer": "改变", "explanations": {"改变": "「改变」与「不变」意思相反，表示变得和以前不一样。", "生长": "「生长」与「不变」没有反义关系，指生物长大。", "移动": "「移动」与「不变」没有反义关系，指位置改变。", "游泳": "「游泳」与「不变」没有反义关系，指在水中活动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改变", "is_correct": true, "explanation": "「改变」与「不变」意思相反，表示变得和以前不一样。"}, {"text": "跳舞", "is_correct": false, "explanation": "「跳舞」与「不变」没有反义关系，指舞动身体。"}, {"text": "哭泣", "is_correct": false, "explanation": "「哭泣」与「不变」没有反义关系，指流泪哭出声。"}, {"text": "睡觉", "is_correct": false, "explanation": "「睡觉」与「不变」没有反义关系，指入睡休息。"}], "correct_answer": "改变", "explanations": {"改变": "「改变」与「不变」意思相反，表示变得和以前不一样。", "跳舞": "「跳舞」与「不变」没有反义关系，指舞动身体。", "哭泣": "「哭泣」与「不变」没有反义关系，指流泪哭出声。", "睡觉": "「睡觉」与「不变」没有反义关系，指入睡休息。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "不变是还和以前一样。", "primary_collocate": null, "pronunciation": "bù biàn", "ipa": "pu˥˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他的习惯多年不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的地址三年不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的味道二十年不变，老顾客都很喜欢。", "target_word": "不变", "complexity_tier": "T3", "furigana": "bú biàn", "sentence_source": "generated"}, {"text": "老师上课的时间一直不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格今年保持不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对我的态度不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的名字一直不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友的笑容十年不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上跑步，这个习惯不变。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电话号码不变，你可以放心。", "target_word": "不变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不变：还和以前一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8a6e1b4-4957-4aa2-bef8-2e14d4c5083b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不变", "is_correct": true, "explanation": "「不变」表示还和以前一样，是这里要选的词。"}, {"text": "普遍", "is_correct": false, "explanation": "「pǔ（第三声）」与 bù（第四声）声母不同（p 与 b），意思是普遍。"}, {"text": "不办", "is_correct": false, "explanation": "「bàn」与 biàn 韵母不同（少了 i），意思是不办理。"}, {"text": "不搬", "is_correct": false, "explanation": "「bān」与 biàn 韵母不同（少了 i）且声调不同，意思是不搬动。"}], "explanations": {"不变": "「不变」表示还和以前一样，是这里要选的词。", "普遍": "「pǔ（第三声）」与 bù（第四声）声母不同（p 与 b），意思是普遍。", "不办": "「bàn」与 biàn 韵母不同（少了 i），意思是不办理。", "不搬": "「bān」与 biàn 韵母不同（少了 i）且声调不同，意思是不搬动。"}, "sentence_index": null, "correct_answer": "不变"}, "level_3": {"options": [{"text": "不变", "is_correct": true, "explanation": "「不变」表示还和以前一样，与“多年”的持续义相符。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：「增加」说数量，不能与“习惯”搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "配价：「忘记」需要带宾语，“习惯多年忘记”不成立。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：「生长」只用于生物，不能与“习惯”搭配。"}], "explanations": {"不变": "「不变」表示还和以前一样，与“多年”的持续义相符。", "增加": "搭配：「增加」说数量，不能与“习惯”搭配。", "忘记": "配价：「忘记」需要带宾语，“习惯多年忘记”不成立。", "生长": "搭配：「生长」只用于生物，不能与“习惯”搭配。"}, "sentence_index": 0, "correct_answer": "不变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的旋律每次都不变，所以听起来很新鲜。", "explanation": "这里应该用〈变换〉。「不变」指没有变化，与“新鲜”矛盾，表示花样不断变化要用〈变换〉。"}, {"text": "他的体重这半年都不变，却瘦了好几斤。", "explanation": "这里应该用〈减轻〉。「不变」表示没有变化，与“瘦了好几斤”矛盾，体重减少要用〈减轻〉。"}, {"text": "他说话的声音一直不变，越来越小了。", "explanation": "这里应该用〈降低〉。「不变」表示没有变化，与“越来越小”矛盾，声音变小要用〈降低〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不变", "is_correct": true, "explanation": "「不变」表示还和以前一样，与“一直”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：路的名字不会游泳，与语境矛盾。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：名字不能增长，「增长」多用于数量或规模。"}, {"text": "参观", "is_correct": false, "explanation": "配价：「参观」需要带宾语，“这条路的名字一直参观”不成立。"}], "explanations": {"不变": "「不变」表示还和以前一样，与“一直”相符。", "游泳": "语义：路的名字不会游泳，与语境矛盾。", "增长": "搭配：名字不能增长，「增长」多用于数量或规模。", "参观": "配价：「参观」需要带宾语，“这条路的名字一直参观”不成立。"}, "sentence_index": 6, "correct_answer": "不变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气一天一个样，每天都不变。", "explanation": "这里应该用〈多变〉。「不变」指和以前一样，说脾气“一天一个样”要用〈多变〉。"}, {"text": "这家店的装修每个月都不变，总给人新鲜感。", "explanation": "这里应该用〈翻新〉。「不变」表示没有变化，与“总给人新鲜感”矛盾，经常换新装修要用〈翻新〉。"}, {"text": "他一年比一年高，身高却每年都不变。", "explanation": "这里应该用〈长高〉。「不变」表示没有变化，与“一年比一年高”矛盾，身高随年龄变化要用〈长高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的友谊多年来始终不变了。", "corrected_sentence": "我们的友谊多年来始终不变。", "error_description": "「不变」表示没有变化，后面加“了”表示已经发生变化，与语境矛盾，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的样子几十年都被不变。", "corrected_sentence": "这个小镇的样子几十年都不变。", "error_description": "「不变」是不及物的状态词，不能用“被”字句，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
