INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中心点是正中间的那一个点。", "primary_collocate": null, "pronunciation": "zhōng xīn diǎn", "ipa": "ʈʂʊŋ˥ ɕin˥ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个圆的中心点在哪里？", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用尺子找到了纸的中心点。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在线段的中心点画一个小圆。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的中心点放着一盆花。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆的中心点到圆周上每一点的距离都相等。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把绳子的中心点系在树上。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说正方形的中心点在两条线中间。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把球放在球场的中心点。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟的中心点上有三根针。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在盒子盖的中心点贴一张画。", "target_word": "中心点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个中心点", "label": "量词"}], "register": "中性", "sense_fingerprint": "正中间的那一个点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755a2819-fc8e-4d21-b491-ab1430d215e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“在哪里”问的是位置，“颜色”不能用来问位置。"}, {"text": "三角形", "is_correct": false, "explanation": "语义：圆与三角形相互矛盾，“这个圆的三角形”说不通。"}, {"text": "中心点", "is_correct": true, "explanation": "中心点是圆正中间的那一个点，句子问它在哪里，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“在哪里”问地点，“时间”不能用来提问位置。"}], "explanations": {"颜色": "搭配：“在哪里”问的是位置，“颜色”不能用来问位置。", "三角形": "语义：圆与三角形相互矛盾，“这个圆的三角形”说不通。", "中心点": "中心点是圆正中间的那一个点，句子问它在哪里，符合句意。", "时间": "搭配：“在哪里”问地点，“时间”不能用来提问位置。"}, "sentence_index": 0, "correct_answer": "中心点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个故事的中心点是友谊。", "explanation": "这里应该用〈中心思想〉。中心点指正中间的那一个点，是位置；说故事主要讲的内容要用“中心思想”。"}, {"text": "比赛的中心点有十分钟休息。", "explanation": "这里应该用〈中间〉。表示一段时间的正中间要说〈中间〉，“中心点”只指一个点。"}, {"text": "这个广场的中心点很大。", "explanation": "这里应该用〈中心区〉。中心点是一个点，没有大小，不能说“很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是正方形上的点，“正方形的天空”说不通。"}, {"text": "中心点", "is_correct": true, "explanation": "正方形的中心点是正中间的点，位于两条线之间，符合句意。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“在……中间”描述空间位置，“上午”是时间词，不能这样搭配。"}, {"text": "圆", "is_correct": false, "explanation": "语义：正方形与圆相互矛盾，“正方形的圆”说不通。"}], "explanations": {"天空": "语义：天空不是正方形上的点，“正方形的天空”说不通。", "中心点": "正方形的中心点是正中间的点，位于两条线之间，符合句意。", "上午": "搭配：“在……中间”描述空间位置，“上午”是时间词，不能这样搭配。", "圆": "语义：正方形与圆相互矛盾，“正方形的圆”说不通。"}, "sentence_index": 6, "correct_answer": "中心点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事的中心点是他不想去。", "explanation": "这里应该用〈关键〉。中心点是空间上正中间的点，不能指事情的关键。"}, {"text": "我们在湖的中心点游了一下午。", "explanation": "这里应该用〈中间〉。中心点只是一个点，不能在一个点上游一下午；大片区域要说“湖中间”。"}, {"text": "他是我们班的中心点，大家都喜欢他。", "explanation": "这里应该用〈中心人物〉。中心点指几何位置上的点，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在纸上画了一只中心点。", "corrected_sentence": "我在纸上画了一个中心点。", "error_description": "错误形式“一只中心点”，正确形式“一个中心点”：“只”常用于动物，不能用来数“中心点”，“中心点”应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈到桌子的中心点摆了一个花瓶。", "corrected_sentence": "妈妈在桌子的中心点摆了一个花瓶。", "error_description": "错误形式“到桌子的中心点摆”，正确形式“在桌子的中心点摆”：表示放置在某处，动词前的地点要用“在”引出；“到”通常放在动词后，如“摆到桌子上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4a3377f-3e32-4c57-9340-b9253ea5873e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95019, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收拾", "is_correct": false, "explanation": "“收拾”指整理、归置，与“中断”没有反义关系。"}, {"text": "继续", "is_correct": true, "explanation": "“继续”与“中断”是反义词，指说到一半停下后接着说下去。"}, {"text": "欣赏", "is_correct": false, "explanation": "“欣赏”指觉得好而赞美，与“中断”没有反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "“等待”指停下来等候，与“中断”没有反义关系。"}], "correct_answer": "继续", "explanations": {"收拾": "“收拾”指整理、归置，与“中断”没有反义关系。", "继续": "“继续”与“中断”是反义词，指说到一半停下后接着说下去。", "欣赏": "“欣赏”指觉得好而赞美，与“中断”没有反义关系。", "等待": "“等待”指停下来等候，与“中断”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95019, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "洗澡", "is_correct": false, "explanation": "“洗澡”指清洗身体，与“中断”没有反义关系。"}, {"text": "继续", "is_correct": true, "explanation": "“继续”与“中断”是反义词，指通话停下后接着进行。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“中断”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指大家一起交流意见，与“中断”没有反义关系。"}], "correct_answer": "继续", "explanations": {"洗澡": "“洗澡”指清洗身体，与“中断”没有反义关系。", "继续": "“继续”与“中断”是反义词，指通话停下后接着进行。", "搬运": "“搬运”指把东西从一处移到另一处，与“中断”没有反义关系。", "讨论": "“讨论”指大家一起交流意见，与“中断”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95019, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "中断是做到一半，停下来了。", "primary_collocate": null, "pronunciation": "zhōng duàn", "ipa": "ʈʂʊŋ˥ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "他做作业时有人敲门，作业只好中断。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的锻炼中断了三天。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的哭声中断了会议。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说到一半，突然中断了。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨使施工中断了。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛因为大雪中断了。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的合作中断了一段时间。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看电影时停电，电影中断了。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为搬家，学习中断过。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话中断后，我又打了一次。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中断了", "label": "体标"}, {"form": "中断过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事情做到一半就停下来，没有做完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中断", "is_correct": true, "explanation": "正确答案：“中断”，指做到一半停下来。"}, {"text": "终端", "is_correct": false, "explanation": "duān（第一声）与 duàn（第四声）声调不同，“终端”指末端、终点。"}, {"text": "工段", "is_correct": false, "explanation": "gōng 与 zhōng 声母不同，“工段”指工厂里的生产单位。"}, {"text": "中短", "is_correct": false, "explanation": "duǎn（第三声）与 duàn（第四声）声调不同，“中短”指中等偏短。"}, {"text": "冲断", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同，“冲断”指猛冲而将其切断。"}], "explanations": {"中断": "正确答案：“中断”，指做到一半停下来。", "终端": "duān（第一声）与 duàn（第四声）声调不同，“终端”指末端、终点。", "工段": "gōng 与 zhōng 声母不同，“工段”指工厂里的生产单位。", "中短": "duǎn（第三声）与 duàn（第四声）声调不同，“中短”指中等偏短。", "冲断": "chōng 与 zhōng 声母不同，“冲断”指猛冲而将其切断。"}, "sentence_index": null, "correct_answer": "中断"}, "level_3": {"options": [{"text": "休息", "is_correct": false, "explanation": "语义：“休息”需要人来做，作业不会休息，句子说不通。"}, {"text": "中断", "is_correct": true, "explanation": "“中断”说作业做到一半停下了，与“有人敲门”的原因搭配自然。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”需要人来走，作业不能散步，句子说不通。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行，作业不能被出版，句子说不通。"}], "explanations": {"休息": "语义：“休息”需要人来做，作业不会休息，句子说不通。", "中断": "“中断”说作业做到一半停下了，与“有人敲门”的原因搭配自然。", "散步": "语义：“散步”需要人来走，作业不能散步，句子说不通。", "出版": "语义：“出版”指印刷发行，作业不能被出版，句子说不通。"}, "sentence_index": 0, "correct_answer": "中断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这个包裹中断了。", "explanation": "这里应该用〈寄〉。把东西送出去要用〈寄〉，中断只用于正在进行的事情。"}, {"text": "他中断了这个房间。", "explanation": "这里应该用〈收拾〉。整理房间要用〈收拾〉，中断不能用来说整理房间。"}, {"text": "他中断了门。", "explanation": "这里应该用〈关〉。把门关上要用〈关〉，中断只指正在进行的事情停下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95019, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "中断", "is_correct": true, "explanation": "正确答案：“中断”，指正在进行的事情中途停下。"}, {"text": "通断", "is_correct": false, "explanation": "tōng 与 zhōng 声母不同，“通断”指接通与断开。"}, {"text": "中院", "is_correct": false, "explanation": "yuàn（第四声）与 duàn（第四声）声母不同，“中院”指中级人民法院。"}, {"text": "中端", "is_correct": false, "explanation": "duān（第一声）与 duàn（第四声）声调不同，“中端”指中等档次。"}], "explanations": {"中断": "正确答案：“中断”，指正在进行的事情中途停下。", "通断": "tōng 与 zhōng 声母不同，“通断”指接通与断开。", "中院": "yuàn（第四声）与 duàn（第四声）声母不同，“中院”指中级人民法院。", "中端": "duān（第一声）与 duàn（第四声）声调不同，“中端”指中等档次。"}, "sentence_index": null, "correct_answer": "中断"}, "level_3": {"options": [{"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是人的身体动作，合作不会咳嗽，句子说不通。"}, {"text": "中断", "is_correct": true, "explanation": "“中断”说合作停下了一段时间，与“合作”搭配自然。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”是人的表情，合作不能微笑，句子说不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”不能和“合作”搭配，句子说不通。"}], "explanations": {"咳嗽": "语义：“咳嗽”是人的身体动作，合作不会咳嗽，句子说不通。", "中断": "“中断”说合作停下了一段时间，与“合作”搭配自然。", "微笑": "语义：“微笑”是人的表情，合作不能微笑，句子说不通。", "跳舞": "搭配：“跳舞”不能和“合作”搭配，句子说不通。"}, "sentence_index": 6, "correct_answer": "中断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我生气，把书中断了。", "explanation": "这里应该用〈扔〉。把东西丢掉要用〈扔〉，中断指正在进行的事情停下来，不能用来说书。"}, {"text": "他中断了一下门铃。", "explanation": "这里应该用〈按〉。按门铃要用〈按〉，中断不能用来说按门铃。"}, {"text": "她中断了那张桌子。", "explanation": "这里应该用〈擦〉。把桌子擦干净要用〈擦〉，中断不能用于桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_w