INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95020, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在进行中停止或断开。", "primary_collocate": null, "pronunciation": "zhōng duàn", "ipa": "ʈʂʊŋ˥ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "大雨中断了比赛。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话突然中断了。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为停电，会议中断了一个小时。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学习中断过一年。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络中断了，我没法上网。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雪，火车运行中断了。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震让交通中断了。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生病了，旅行只好中断。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中断后，球员都回到了休息室。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作不能中断，我们要做完。", "target_word": "中断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中断了", "label": "体标"}, {"form": "中断过", "label": "体标"}], "register": "中性", "sense_fingerprint": "正在进行的事情或连着的联系中途停止、断开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中断", "is_correct": true, "explanation": "正确答案：“中断”，指正在进行的事情中途停下。"}, {"text": "终端", "is_correct": false, "explanation": "duān（第一声）与 duàn（第四声）声调不同，“终端”指末端、终点。"}, {"text": "工段", "is_correct": false, "explanation": "gōng 与 zhōng 声母不同，“工段”指工厂里的生产单位。"}, {"text": "中院", "is_correct": false, "explanation": "yuàn（第四声）与 duàn（第四声）声母不同，“中院”指中级人民法院。"}, {"text": "通断", "is_correct": false, "explanation": "tōng 与 zhōng 声母不同，“通断”指接通与断开，意思与“中断”不同。"}], "explanations": {"中断": "正确答案：“中断”，指正在进行的事情中途停下。", "终端": "duān（第一声）与 duàn（第四声）声调不同，“终端”指末端、终点。", "工段": "gōng 与 zhōng 声母不同，“工段”指工厂里的生产单位。", "中院": "yuàn（第四声）与 duàn（第四声）声母不同，“中院”指中级人民法院。", "通断": "tōng 与 zhōng 声母不同，“通断”指接通与断开，意思与“中断”不同。"}, "sentence_index": null, "correct_answer": "中断"}, "level_3": {"options": [{"text": "观看", "is_correct": false, "explanation": "语义：“观看”需要有人作主语，大雨不能观看比赛。"}, {"text": "举办", "is_correct": false, "explanation": "语义：“举办”需要有人来组织，大雨不能举办比赛。"}, {"text": "中断", "is_correct": true, "explanation": "“中断”说比赛被大雨停下，与“大雨”搭配自然。"}, {"text": "赢得", "is_correct": false, "explanation": "配价：“赢得”需要人作主语，大雨不能赢得比赛。"}], "explanations": {"观看": "语义：“观看”需要有人作主语，大雨不能观看比赛。", "举办": "语义：“举办”需要有人来组织，大雨不能举办比赛。", "中断": "“中断”说比赛被大雨停下，与“大雨”搭配自然。", "赢得": "配价：“赢得”需要人作主语，大雨不能赢得比赛。"}, "sentence_index": 0, "correct_answer": "中断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他中断了那棵树。", "explanation": "这里应该用〈砍〉。把树砍断要用〈砍〉，中断指正在进行的事情停下来，不能用于树。"}, {"text": "他把积木中断了。", "explanation": "这里应该用〈拆〉。把已经连在一起的东西分开要用〈拆〉，中断只用于正在进行的事情。"}, {"text": "他中断了那张床。", "explanation": "这里应该用〈搬〉。搬动家具要用〈搬〉，中断只用于正在进行的活动，不能用于家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95020, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "中断", "is_correct": true, "explanation": "正确答案：“中断”，指正在进行的事情中途停下。"}, {"text": "中端", "is_correct": false, "explanation": "duān（第一声）与 duàn（第四声）声调不同，“中端”指中等档次。"}, {"text": "冲断", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同，“冲断”指猛冲而将其切断。"}, {"text": "中短", "is_correct": false, "explanation": "duǎn（第三声）与 duàn（第四声）声调不同，“中短”指中等偏短。"}], "explanations": {"中断": "正确答案：“中断”，指正在进行的事情中途停下。", "中端": "duān（第一声）与 duàn（第四声）声调不同，“中端”指中等档次。", "冲断": "chōng 与 zhōng 声母不同，“冲断”指猛冲而将其切断。", "中短": "duǎn（第三声）与 duàn（第四声）声调不同，“中短”指中等偏短。"}, "sentence_index": null, "correct_answer": "中断"}, "level_3": {"options": [{"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指让东西开始燃烧，交通不能被点燃。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光不再亮，交通不能熄灭。"}, {"text": "叫醒", "is_correct": false, "explanation": "配价：“叫醒”需要一个人作宾语，“交通”不能被叫醒。"}, {"text": "中断", "is_correct": true, "explanation": "“中断”说交通被地震停下来，与“让……了”的结构搭配自然。"}], "explanations": {"点燃": "语义：“点燃”指让东西开始燃烧，交通不能被点燃。", "熄灭": "语义：“熄灭”指火或光不再亮，交通不能熄灭。", "叫醒": "配价：“叫醒”需要一个人作宾语，“交通”不能被叫醒。", "中断": "“中断”说交通被地震停下来，与“让……了”的结构搭配自然。"}, "sentence_index": 6, "correct_answer": "中断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他中断了这次邀请。", "explanation": "这里应该用〈拒绝〉。不接受别人的邀请要用〈拒绝〉，中断只用于正在进行的活动。"}, {"text": "他中断了一瓶水。", "explanation": "这里应该用〈喝〉。喝东西要用〈喝〉，中断不能用来说喝水。"}, {"text": "他把旧手机中断了，又买了一部新的。", "explanation": "这里应该用〈扔〉。把不要的东西丢掉要用〈扔〉，中断不能用于东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暴雨被中断了这场比赛。", "corrected_sentence": "暴雨中断了这场比赛。", "error_description": "被字句错误：“暴雨”是施事，不能放在“被”前充当受事；应去掉“被”，说“暴雨中断了这场比赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次罢工让运输中断了过一段时间。", "corrected_sentence": "这次罢工让运输中断过一段时间。", "error_description": "体标重复：“中断过”已用“过”表示经历，多加的“了”应去掉，应说“中断过一段时间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
