INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95021, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "促使是让某件事发生。", "primary_collocate": null, "pronunciation": "cù shǐ", "ipa": "tsʰu˥˩ ʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这件事促使他下决心学汉语。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话促使我认真复习。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友的帮助促使他走出了困难。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷促使人们多穿衣服。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次失败促使她换了方法。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格下降促使更多人来买。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雨促使比赛改到明天。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母的爱促使他努力工作。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到别人进步，促使我也想试试。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一本书促使他开始了写作。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "促使了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "某个原因或事情使人做出某种行动或让某件事发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "促使", "is_correct": true, "explanation": "正确：“促使”表示使人做某件事，与“他下决心学汉语”的结构相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”要求有意愿的人作主语，“这件事”不能拒绝。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”需要人作主语，事情不能嘲笑人，与“下决心学汉语”的语境也不合。"}, {"text": "劝", "is_correct": false, "explanation": "搭配：“劝”的主语须是人，说“这件事劝他”不通。"}], "explanations": {"促使": "正确：“促使”表示使人做某件事，与“他下决心学汉语”的结构相符。", "拒绝": "语义：“拒绝”要求有意愿的人作主语，“这件事”不能拒绝。", "嘲笑": "语义：“嘲笑”需要人作主语，事情不能嘲笑人，与“下决心学汉语”的语境也不合。", "劝": "搭配：“劝”的主语须是人，说“这件事劝他”不通。"}, "sentence_index": 0, "correct_answer": "促使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "多运动能促使健康。", "explanation": "这里应该用〈促进〉。促使后面要接人去做某件事，不能直接接“健康”这样的状态；促进用于推动事物向好发展。"}, {"text": "这部电影促使我很难过。", "explanation": "这里应该用〈让〉。促使后面接的是人去做某件事，表示感受、情绪要用“让”。"}, {"text": "这次改革促使了很多机会。", "explanation": "这里应该用〈带来〉。促使表示使人做某事，“机会”不能被促使，应用“带来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "促使", "is_correct": true, "explanation": "正确：“促使”表示使某种情况出现或使人行动，与“这场大雨……比赛改到明天”的语境相符。"}, {"text": "反对", "is_correct": false, "explanation": "配价：“反对”需要有意见的人作主语，宾语应是提议或做法，“大雨”不能反对比赛改期。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”需要人表态，“大雨”不能同意比赛改期。"}, {"text": "安排", "is_correct": false, "explanation": "语义：“安排”需要有意志的人来做，大雨不能安排比赛。"}], "explanations": {"促使": "正确：“促使”表示使某种情况出现或使人行动，与“这场大雨……比赛改到明天”的语境相符。", "反对": "配价：“反对”需要有意见的人作主语，宾语应是提议或做法，“大雨”不能反对比赛改期。", "同意": "语义：“同意”需要人表态，“大雨”不能同意比赛改期。", "安排": "语义：“安排”需要有意志的人来做，大雨不能安排比赛。"}, "sentence_index": 6, "correct_answer": "促使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次失败促使了他的自信。", "explanation": "这里应该用〈增强〉。促使表示让某件事发生，“自信”是心理状态，不能被促使出现，要用“增强”。"}, {"text": "这个笑话促使了大家的沉默。", "explanation": "这里应该用〈让〉。促使后要接能发生的动作，“沉默”是状态，要用“让大家沉默”。"}, {"text": "这张照片促使了我的泪水。", "explanation": "这里应该用〈让〉。促使后接的是人要去做的事，不能直接带“泪水”这样的名词；应说“让我流泪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的唠叨促使的他早点儿回家。", "corrected_sentence": "妈妈的唠叨促使他早点儿回家。", "error_description": "多了“的”：应说“促使他早点儿回家”，“促使的”变成修饰语，句子没有谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次的失败促使的他换了方法。", "corrected_sentence": "这次的失败促使他换了方法。", "error_description": "多了“的”：应说“促使他换了方法”，“促使的”变成修饰语，句子没有谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
