INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "推动，使某事发生或实现。", "primary_collocate": null, "pronunciation": "cù shǐ", "ipa": "tsʰu˥˩ ʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "新政策促使经济很快发展起来。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学技术促使社会不断进步。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竞争促使公司提高了产品质量。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议促使两国合作。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场需要促使工厂增加生产。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好政策促使城市变得更干净。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体报道促使问题得到了解决。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的努力促使计划顺利实现。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定促使行业标准逐步统一。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术促使工作方式发生了变化。", "target_word": "促使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "促使了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "政策、技术、竞争等因素推动某种变化发生或实现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "促使", "is_correct": true, "explanation": "正确：“促使”表示推动某事发生，与“新政策……经济很快发展起来”的语境相符。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍”表示妨碍，与“经济很快发展起来”的语境相反。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”表示使事情推迟，与“经济很快发展起来”的语境相反。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指使不能流动或活动，与“经济很快发展起来”的语境不合。"}], "explanations": {"促使": "正确：“促使”表示推动某事发生，与“新政策……经济很快发展起来”的语境相符。", "阻碍": "语义：“阻碍”表示妨碍，与“经济很快发展起来”的语境相反。", "拖延": "语义：“拖延”表示使事情推迟，与“经济很快发展起来”的语境相反。", "冻结": "语义：“冻结”指使不能流动或活动，与“经济很快发展起来”的语境不合。"}, "sentence_index": 0, "correct_answer": "促使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次意外促使了大家的关注。", "explanation": "这里应该用〈引起〉。“促使了”后接名词“关注”搭配不当；“引起大家的关注”才自然。"}, {"text": "这场地震促使了很大的损失。", "explanation": "这里应该用〈造成〉。促使指推动某事发生，不能直接以“损失”作为结果宾语，说损害要用“造成”。"}, {"text": "这项新政策促使了很多机会。", "explanation": "这里应该用〈带来〉。促使表示推动某事发生或实现，“机会”是结果，不是可以被推动的事件，要用“带来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "促使", "is_correct": true, "explanation": "正确：“促使”表示推动某事发生或实现，与“媒体报道……问题得到了解决”的语境相符。"}, {"text": "掩盖", "is_correct": false, "explanation": "语义：“掩盖”指遮住真相，与“问题得到了解决”的语境相反。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”指不让某事发生，与“问题得到了解决”的语境相反。"}, {"text": "遏制", "is_correct": false, "explanation": "语义：“遏制”指控制、制止，与“问题得到了解决”的语境相反。"}], "explanations": {"促使": "正确：“促使”表示推动某事发生或实现，与“媒体报道……问题得到了解决”的语境相符。", "掩盖": "语义：“掩盖”指遮住真相，与“问题得到了解决”的语境相反。", "阻止": "语义：“阻止”指不让某事发生，与“问题得到了解决”的语境相反。", "遏制": "语义：“遏制”指控制、制止，与“问题得到了解决”的语境相反。"}, "sentence_index": 6, "correct_answer": "促使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息促使了他的好奇。", "explanation": "这里应该用〈引起〉。促使表示推动某事发生或实现，后面不能直接带“好奇”这样的心理名词，应说“引起了他的好奇”。"}, {"text": "这次比赛促使了他的名气。", "explanation": "这里应该用〈提高〉。促使后接事情的发生或变化，不能直接带“名气”，应说“提高了他的名气”。"}, {"text": "这张照片促使了观众的兴趣。", "explanation": "这里应该用〈激起〉。促使表示推动某事发生或实现，“兴趣”要用“激起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革促使的市场很快活跃起来。", "corrected_sentence": "这次改革促使市场很快活跃起来。", "error_description": "多了“的”：应说“促使市场很快活跃起来”，“促使的”变成修饰语，句子没有谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练的鼓励促使的队员更加努力。", "corrected_sentence": "教练的鼓励促使队员更加努力。", "error_description": "多了“的”：应说“促使队员更加努力”，“促使的”变成修饰语，句子没有谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
