INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "言行不合情理，令人不满。", "primary_collocate": null, "pronunciation": "xiàng huà", "ipa": "ɕjɑŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "这么晚了还不回家，像话吗？", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你让老人站着，自己坐着，像话吗？", "target_word": "像话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班总是迟到，真不像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生在课堂上大声打电话，太不像话了。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借了钱不还，还说是我的错，这不像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人还没来，你们就先吃了，像话吗？", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个大人跟小孩抢东西，真不像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对自己的父母那么冷淡，实在不像话。", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人说话你一直打断，这像话吗？", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间乱成这样你都不收拾，不像话！", "target_word": "像话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不像话", "label": "否定"}], "register": "口语", "sense_fingerprint": "言行不合情理、令人不满，多用于否定式或反问式批评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7709e2f0-004d-4e3f-a172-8cd680b047b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话（xiàng huà）：言行不合情理、令人不满，正是本词的意思。"}, {"text": "笑话", "is_correct": false, "explanation": "笑话（xiào huà）与“像话”第二个音节相同，第一个音节韵母不同（iao 与 iang），意思是引人发笑的话或故事。"}, {"text": "墙画", "is_correct": false, "explanation": "墙画（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是画在墙上的画。"}, {"text": "香花", "is_correct": false, "explanation": "香花（xiāng huā）两个音节的声调都与“像话”不同（第一声与第四声），意思是芳香的花。"}, {"text": "闲话", "is_correct": false, "explanation": "闲话（xián huà）与“像话”的韵母不同（an 与 ang），声调也不同，意思是闲聊或背后议论。"}], "explanations": {"像话": "像话（xiàng huà）：言行不合情理、令人不满，正是本词的意思。", "笑话": "笑话（xiào huà）与“像话”第二个音节相同，第一个音节韵母不同（iao 与 iang），意思是引人发笑的话或故事。", "墙画": "墙画（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是画在墙上的画。", "香花": "香花（xiāng huā）两个音节的声调都与“像话”不同（第一声与第四声），意思是芳香的花。", "闲话": "闲话（xián huà）与“像话”的韵母不同（an 与 ang），声调也不同，意思是闲聊或背后议论。"}, "sentence_index": null, "correct_answer": "像话"}, "level_3": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话：言行是否合乎情理，这里用反问来批评，正符合语境。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容味道，与晚归、不回家无关。"}, {"text": "好喝", "is_correct": false, "explanation": "语义：“好喝”形容饮料的味道，不能用来评价晚归的行为。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多用于表演、比赛、故事，不能用来评价晚归的行为。"}], "explanations": {"像话": "像话：言行是否合乎情理，这里用反问来批评，正符合语境。", "好吃": "语义：“好吃”形容味道，与晚归、不回家无关。", "好喝": "语义：“好喝”形容饮料的味道，不能用来评价晚归的行为。", "精彩": "搭配：“精彩”多用于表演、比赛、故事，不能用来评价晚归的行为。"}, "sentence_index": 0, "correct_answer": "像话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生在课堂上大声打电话，这样做很像话。", "explanation": "这里用的是“像话”的表扬义（言行合乎情理、没有错），与句中的批评语境相反，本句要的是批评义。"}, {"text": "他的眼睛很不像话，看东西总是模糊。", "explanation": "这里应该用〈近视〉。像话只用于批评人的言行，视力不好要说近视。"}, {"text": "他的牙齿很不像话，笑起来特别难看。", "explanation": "这里应该用〈整齐〉。像话只用于批评人的言行，牙齿的排列要说整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话（xiàng huà）：言行不合情理、令人不满，正是本词的意思。"}, {"text": "强化", "is_correct": false, "explanation": "强化（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是加强、巩固。"}, {"text": "量化", "is_correct": false, "explanation": "量化（liàng huà）的声母与“像话”不同（l 与 x），声调相同（第四声），意思是用数量来表示。"}, {"text": "香滑", "is_correct": false, "explanation": "香滑（xiāng huá）两个音节的声调都与“像话”不同，意思是又香又滑，多形容食物。"}], "explanations": {"像话": "像话（xiàng huà）：言行不合情理、令人不满，正是本词的意思。", "强化": "强化（qiáng huà）与“像话”的声母和声调都不同（q 与 x，第二声与第四声），意思是加强、巩固。", "量化": "量化（liàng huà）的声母与“像话”不同（l 与 x），声调相同（第四声），意思是用数量来表示。", "香滑": "香滑（xiāng huá）两个音节的声调都与“像话”不同，意思是又香又滑，多形容食物。"}, "sentence_index": null, "correct_answer": "像话"}, "level_3": {"options": [{"text": "像话", "is_correct": true, "explanation": "像话：言行不合情理，这里用来批评大人抢小孩东西的行为。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容温度舒适，不能用来评价抢东西的行为。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，与抢东西的行为毫无关系。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”多用于物体或身体，不说人的行为“不结实”。"}], "explanations": {"像话": "像话：言行不合情理，这里用来批评大人抢小孩东西的行为。", "凉快": "语义：“凉快”形容温度舒适，不能用来评价抢东西的行为。", "甜": "语义：“甜”形容味道，与抢东西的行为毫无关系。", "结实": "搭配：“结实”多用于物体或身体，不说人的行为“不结实”。"}, "sentence_index": 6, "correct_answer": "像话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子很不像话，坐在后排也看不清。", "explanation": "这里应该用〈矮〉。像话评价言行，身高等身体特征不能用它，个子矮要说矮。"}, {"text": "他的身体很不像话，每天都去跑步。", "explanation": "这里应该用〈健康〉。像话评价言行是否合情理，身体状况要说健康。"}, {"text": "他的手很不像话，做的木工活很精致。", "explanation": "这里应该用〈巧〉。像话不能评价手的灵巧程度，手艺灵巧要说巧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这样插队，真不像话地。", "corrected_sentence": "他这样插队，真不像话。", "error_description": "词类错误：“不像话”是形容词，后面不加“地”。“地”用于修饰动词的副词，应说“真不像话”，不能说“真不像话地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是乱发脾气，实在像话。", "corrected_sentence": "他总是乱发脾气，实在不像话。", "error_description": "否定词漏掉：“不像话”是批评的说法，漏掉“不”后句子变成表扬，与语境相反，应说“实在不像话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95025, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺点", "is_correct": true, "explanation": "正确。「缺点」与「优点」相对，指不好的地方。"}, {"text": "天气", "is_correct": false, "explanation": "「天气」是自然现象，与「优点」不构成反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "「桌子」是家具，与「优点」没有相对的关系。"}, {"text": "河流", "is_correct": false, "explanation": "「河流」是自然事物，与「优点」不是相对的概念。"}], "correct_answer": "缺点", "explanations": {"缺点": "正确。「缺点」与「优点」相对，指不好的地方。", "天气": "「天气」是自然现象，与「优点」不构成反义关系。", "桌子": "「桌子」是家具，与「优点」没有相对的关系。", "河流": "「河流」是自然事物，与「优点」不是相对的概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95025, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺点", "is_correct": true, "explanation": "正确。「缺点」与「优点」相对，指不好的地方。"}, {"text": "车站", "is_correct": false, "explanation": "「车站」是地点，与「优点」没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "「石头」是物体，不与「优点」相对。"}, {"text": "窗户", "is_correct": false, "explanation": "「窗户」是建筑部件，与「优点」没有相对的关系。"}], "correct_answer": "缺点", "explanations": {"缺点": "正确。「缺点」与「优点」相对，指不好的地方。", "车站": "「车站」是地点，与「优点」没有反义关系。", "石头": "「石头」是物体，不与「优点」相对。", "窗户": "「窗户」是建筑部件，与「优点」没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95025, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "优点是一个人或东西好的地方。", "primary_collocate": null, "pronunciation": "yōu diǎn", "ipa": "jou˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的优点是做事认真。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己的优点。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的优点是电池很耐用。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要多看别人的优点。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的优点是爱帮助同学。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种车的优点是便宜，缺点是小。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹最大的优点是很会照顾人。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在小城市有很多优点。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先说说这个办法的优点。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么优点，说来听听？", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "优缺点", "label": "复合"}], "register": "通用", "sense_fingerprint": "人或东西好的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01a5a511-643b-455f-a743-1f7bb54c8652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95025, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优点", "is_correct": true, "explanation": "正确。优点指人或东西好的地方。"}, {"text": "有点", "is_correct": false, "explanation": "有点与优点第一个音节声调不同（yǒu 第三声，yōu 第一声），有点的意思是稍微。"}, {"text": "油点", "is_correct": false, "explanation": "油点（yóu diǎn）与优点只有第一个音节声调不同（第二声与第一声），意思是油的斑点。"}, {"text": "邮电", "is_correct": false, "explanation": "邮电与优点两个音节的声调都不同（yóu diàn 与 yōu diǎn），意思是邮政和电信。"}], "explanations": {"优点": "正确。优点指人或东西好的地方。", "有点": "有点与优点第一个音节声调不同（yǒu 第三声，yōu 第一声），有点的意思是稍微。", "油点": "油点（yóu diǎn）与优点只有第一个音节声调不同（第二声与第一声），意思是油的斑点。", "邮电": "邮电与优点两个音节的声调都不同（yóu diàn 与 yōu diǎn），意思是邮政和电信。"}, "sentence_index": null, "correct_answer": "优点"}, "level_3": {"options": [{"text": "优点", "is_correct": true, "explanation": "正确。「优点」指好的地方，「做事认真」可以作为他的优点。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」指外形，不能用来说做事的态度。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」与做事是否认真无关，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "配价：「价格」只能与金额搭配，不能作「做事认真」的主题。"}], "explanations": {"优点": "正确。「优点」指好的地方，「做事认真」可以作为他的优点。", "身高": "体貌：「身高」指外形，不能用来说做事的态度。", "颜色": "语义：「颜色」与做事是否认真无关，句子不通。", "价格": "配价：「价格」只能与金额搭配，不能作「做事认真」的主题。"}, "sentence_index": 0, "correct_answer": "优点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的英语优点很高。", "explanation": "这里应该用〈水平〉。「很高」说的是能力或成绩的程度，优点只指好的方面，不能说“很高”。"}, {"text": "这个方案的优点是成本很高。", "explanation": "这里说的是缺点，应该用〈缺点〉。优点只指好的方面，不能用来说成本高这样的不足。"}, {"text": "这家店占了优点。", "explanation": "这里应该用〈优势〉。「占」搭配「优势」，不说「占优点」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "优点", "is_correct": true, "explanation": "正确。「最大的优点」指妹妹突出的好处，「很会照顾人」正好是这种好处。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指岁数，不能说「很会照顾人」。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：「体重」指身体的重量，与照顾人的能力无关。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：「鞋子」是物品，不能作为能力或性格的特点。"}], "explanations": {"优点": "正确。「最大的优点」指妹妹突出的好处，「很会照顾人」正好是这种好处。", "年龄": "语义：「年龄」指岁数，不能说「很会照顾人」。", "体重": "体貌：「体重」指身体的重量，与照顾人的能力无关。", "鞋子": "语义：「鞋子」是物品，不能作为能力或性格的特点。"}, "sentence_index": 6, "correct_answer": "优点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的数学优点排第一。", "explanation": "这里应该用〈成绩〉。「排第一」说的是成绩或名次，优点只指好的方面，不能按名次排。"}, {"text": "这台电脑的优点是经常死机。", "explanation": "这里说的是缺点，应该用〈缺点〉。死机是不足，不能算作优点。"}, {"text": "他们在比赛中取得了优点。", "explanation": "这里应该用〈优势〉。「取得」搭配「优势」，不说「取得优点」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
