INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物好的方面、长处。", "primary_collocate": null, "pronunciation": "yōu diǎn", "ipa": "jou˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家饭店的优点是菜新鲜。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车的优点是不堵车。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学习上的优点是肯问问题。", "target_word": "优点", "complexity_tier": "T3", "furigana": "yōu diǎn", "sentence_source": "generated"}, {"text": "这件衣服的优点是又轻又暖和。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的优点，我要多学习。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写下这本书的优点和缺点。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的优点是离地铁近。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的优点写在纸上。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西的优点是方便。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找工作时，要说出自己的优点。", "target_word": "优点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "优缺点", "label": "复合"}], "register": "通用", "sense_fingerprint": "事物好的方面、长处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01a5a511-643b-455f-a743-1f7bb54c8652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95026, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优点", "is_correct": true, "explanation": "正确。优点指事物好的方面、长处。"}, {"text": "有点", "is_correct": false, "explanation": "有点与优点第一个音节声调不同（yǒu 第三声，yōu 第一声），有点的意思是稍微。"}, {"text": "油点", "is_correct": false, "explanation": "油点（yóu diǎn）与优点只有第一个音节声调不同（第二声与第一声），意思是油的斑点。"}, {"text": "邮电", "is_correct": false, "explanation": "邮电与优点两个音节的声调都不同（yóu diàn 与 yōu diǎn），意思是邮政和电信。"}], "explanations": {"优点": "正确。优点指事物好的方面、长处。", "有点": "有点与优点第一个音节声调不同（yǒu 第三声，yōu 第一声），有点的意思是稍微。", "油点": "油点（yóu diǎn）与优点只有第一个音节声调不同（第二声与第一声），意思是油的斑点。", "邮电": "邮电与优点两个音节的声调都不同（yóu diàn 与 yōu diǎn），意思是邮政和电信。"}, "sentence_index": null, "correct_answer": "优点"}, "level_3": {"options": [{"text": "优点", "is_correct": true, "explanation": "正确。「优点」指好的方面，「菜新鲜」是这家饭店的优点。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指岁数，不能用来说饭店的菜。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：「体重」指人或动物身体的重量，不能用于饭店。"}, {"text": "价格", "is_correct": false, "explanation": "配价：「价格」不能与「菜新鲜」搭配，句子不通。"}], "explanations": {"优点": "正确。「优点」指好的方面，「菜新鲜」是这家饭店的优点。", "年龄": "语义：「年龄」指岁数，不能用来说饭店的菜。", "体重": "体貌：「体重」指人或动物身体的重量，不能用于饭店。", "价格": "配价：「价格」不能与「菜新鲜」搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "优点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个学生的英语优点很高。", "explanation": "这里应该用〈水平〉。「很高」说的是能力或成绩的程度，优点只指好的方面，不能说“很高”。"}, {"text": "这家店的优点是服务很差。", "explanation": "这里说的是缺点，应该用〈缺点〉。优点指好的方面，不能用来说服务差这样的不足。"}, {"text": "他们在市场上占了优点。", "explanation": "这里应该用〈优势〉。「占」搭配「优势」，不说「占优点」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation