INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95027, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "凶手是杀死别人的坏人。", "primary_collocate": null, "pronunciation": "xiōng shǒu", "ipa": "ɕjʊŋ˥˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察终于抓住了凶手。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凶手昨天晚上跑了。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是杀死他的凶手？", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人知道凶手是谁。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凶手留下了一把刀。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在找那个凶手。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居看见凶手从门口走了出去。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个凶手杀了三个人。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判凶手死刑。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是凶手，警察弄错了。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "杀人凶手", "label": "复合"}], "register": "中性", "sense_fingerprint": "杀死别人的坏人，案件中的行凶者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56189473-a491-472b-a780-7b2e60a5ec1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "搭配：“抓住”用于人或物，不能说抓住感冒。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“抓住”不能用于天空，天空抓不住。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是书，不是可以被警察抓住的对象。"}, {"text": "凶手", "is_correct": true, "explanation": "凶手：杀死别人的坏人，警察可以抓住。"}], "explanations": {"感冒": "搭配：“抓住”用于人或物，不能说抓住感冒。", "天空": "搭配：“抓住”不能用于天空，天空抓不住。", "小说": "语义：小说是书，不是可以被警察抓住的对象。", "凶手": "凶手：杀死别人的坏人，警察可以抓住。"}, "sentence_index": 0, "correct_answer": "凶手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个凶手，偷了我的手机。", "explanation": "这里应该用〈小偷〉。凶手指杀死别人的人，偷东西的人要说小偷。"}, {"text": "凶手每天在学校教孩子们唱歌。", "explanation": "这里应该用〈老师〉。凶手指杀死别人的坏人，教孩子的人要说老师。"}, {"text": "凶手骗走了老人的存款。", "explanation": "这里应该用〈骗子〉。凶手指杀人的人，骗钱的人要说骗子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不会自己走出门口。"}, {"text": "闹钟", "is_correct": false, "explanation": "配价：“走出去”的主语必须是人或动物，闹钟不能走。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见，也不会从门口走出去。"}, {"text": "凶手", "is_correct": true, "explanation": "凶手：杀死别人的坏人，是人，可以看见并走出门口。"}], "explanations": {"天气": "语义：天气不会自己走出门口。", "闹钟": "配价：“走出去”的主语必须是人或动物，闹钟不能走。", "声音": "语义：声音看不见，也不会从门口走出去。", "凶手": "凶手：杀死别人的坏人，是人，可以看见并走出门口。"}, "sentence_index": 6, "correct_answer": "凶手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是凶手，救了三个孩子。", "explanation": "这里应该用〈英雄〉。凶手指杀死别人的坏人，救人的人不能叫凶手。"}, {"text": "这位凶手每天给病人治病。", "explanation": "这里应该用〈医生〉。凶手指杀人的人，给病人治病的要说医生。"}, {"text": "我养的那个凶手很可爱。", "explanation": "这里应该用〈猫〉。凶手指杀人的人，不能用来形容可爱的宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察在河边抓到了一只凶手。", "corrected_sentence": "警察在河边抓到了一个凶手。", "error_description": "“凶手”指人，应该用量词“个”。“只”多用于动物，说“一只凶手”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天警察会把一只凶手带回来。", "corrected_sentence": "明天警察会把一个凶手带回来。", "error_description": "错误：一只凶手。正确：一个凶手。“凶手”指人，量词应用“个”，“只”多用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
