INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "杀害他人的人。", "primary_collocate": null, "pronunciation": "xiōng shǒu", "ipa": "ɕjʊŋ˥˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这起案子的凶手还没找到。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个冷酷的凶手。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把凶手带回了警察局。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凶手为什么要杀他？", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的凶手是他的朋友。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个凶手一直不说话。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证人说，她看到了凶手的脸。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凶手后来承认了自己的错。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想知道凶手到底是谁。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕凶手会再来找他。", "target_word": "凶手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "杀人凶手", "label": "复合"}], "register": "中性", "sense_fingerprint": "杀害他人的人，案件与故事中的行凶者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56189473-a491-472b-a780-7b2e60a5ec1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能被找到，不是案子里的人或物。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳不是案子的组成部分，不能“找到”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格属于人，案子没有“性格”，“这起案子的性格”说不通。"}, {"text": "凶手", "is_correct": true, "explanation": "凶手：杀害他人的人，案子还没找到凶手。"}], "explanations": {"天气": "语义：天气不能被找到，不是案子里的人或物。", "心跳": "语义：心跳不是案子的组成部分，不能“找到”。", "性格": "语义：性格属于人，案子没有“性格”，“这起案子的性格”说不通。", "凶手": "凶手：杀害他人的人，案子还没找到凶手。"}, "sentence_index": 0, "correct_answer": "凶手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "凶手为什么要偷他的钱？", "explanation": "这里应该用〈小偷〉。凶手指杀害他人的人，偷钱的人要说小偷。"}, {"text": "凶手每天开车送大家上班。", "explanation": "这里应该用〈司机〉。凶手指杀害他人的人，开车送人上班的要说司机。"}, {"text": "凶手用假身份骗走了他的钱。", "explanation": "这里应该用〈骗子〉。凶手指杀害他人的人，用假身份骗钱的人要说骗子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：此处指证人看到的人脸，“天空的脸”不合语境。"}, {"text": "风", "is_correct": false, "explanation": "语义：此处指证人看到的人脸，“风的脸”不合语境。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字没有脸，证人不可能看到数字的脸。"}, {"text": "凶手", "is_correct": true, "explanation": "凶手：杀害他人的人，有脸，证人可以看到。"}], "explanations": {"天空": "语义：此处指证人看到的人脸，“天空的脸”不合语境。", "风": "语义：此处指证人看到的人脸，“风的脸”不合语境。", "数字": "语义：数字没有脸，证人不可能看到数字的脸。", "凶手": "凶手：杀害他人的人，有脸，证人可以看到。"}, "sentence_index": 6, "correct_answer": "凶手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是凶手，在火灾中救出了孩子。", "explanation": "这里应该用〈英雄〉。凶手指杀害他人的人，救人的人不能叫凶手。"}, {"text": "那位凶手每天照顾病人。", "explanation": "这里应该用〈护士〉。凶手指杀害他人的人，照顾病人的要说护士。"}, {"text": "妈妈养的凶手很可爱。", "explanation": "这里应该用〈小猫〉。凶手指杀害他人的人，不能用来形容可爱的宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个凶手们已经逃走了。", "corrected_sentence": "那个凶手已经逃走了。", "error_description": "“们”不能与“那个”这类带数量词的名词短语连用，去掉“们”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察昨天抓住了三个凶手们。", "corrected_sentence": "警察昨天抓住了三个凶手。", "error_description": "错误：三个凶手们。正确：三个凶手。名词前面有数量词“三个”时，后面不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
