INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全年是从年头到年尾的整一年。", "primary_collocate": null, "pronunciation": "quán nián", "ipa": "tɕʰɥɛn˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这家商店全年都开门。", "target_word": "全年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全年有十二个月。", "target_word": "全年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他全年没有请过一天假。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司全年的收入比去年多。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市全年的雨水很少。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我全年的计划已经写好了。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全年三百六十五天，他每天跑步。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志全年共出十二期。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校全年的活动都在这张表上。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她订了全年的牛奶。", "target_word": "全年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全年：从年头到年尾的整一年，时间名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56189473-a491-472b-a780-7b2e60a5ec1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全年", "is_correct": true, "explanation": "正确：“全年”指从年头到年尾的整一年，与“都开门”的时间范围相合。"}, {"text": "年代", "is_correct": false, "explanation": "语义：“年代”指以十年为单位的时期，与“都开门”的全年范围不合。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”只是一年中的一段时间，不能表示整个一年。"}, {"text": "时期", "is_correct": false, "explanation": "搭配：“时期”前要有修饰语，不能直接说“这家商店时期都开门”。"}], "explanations": {"全年": "正确：“全年”指从年头到年尾的整一年，与“都开门”的时间范围相合。", "年代": "语义：“年代”指以十年为单位的时期，与“都开门”的全年范围不合。", "季节": "语义：“季节”只是一年中的一段时间，不能表示整个一年。", "时期": "搭配：“时期”前要有修饰语，不能直接说“这家商店时期都开门”。"}, "sentence_index": 0, "correct_answer": "全年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的全年很大，住得很舒服。", "explanation": "语义：这里把“全年”当成了面积、规模的意思，但它只指一年的时间，不能用来形容房子的大小。"}, {"text": "他的全年很聪明，老师都夸他。", "explanation": "语义：这里把“全年”当成了人的品质，但它只指一年的时间，不能用来形容人聪明。"}, {"text": "他的全年很高，比同学都高。", "explanation": "语义：这里把“全年”当成了身高、高度的意思，但它只指一年的时间，不能用来形容人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全年", "is_correct": true, "explanation": "正确：“全年”指一整年的时间，与“三百六十五天”相合。"}, {"text": "本月", "is_correct": false, "explanation": "语义：“本月”只有几十天，不能是三百六十五天。"}, {"text": "一季", "is_correct": false, "explanation": "搭配：“一季”通常指三个月，数量不能与“三百六十五天”搭配。"}, {"text": "整周", "is_correct": false, "explanation": "语义：“整周”只有七天，与三百六十五天不合。"}], "explanations": {"全年": "正确：“全年”指一整年的时间，与“三百六十五天”相合。", "本月": "语义：“本月”只有几十天，不能是三百六十五天。", "一季": "搭配：“一季”通常指三个月，数量不能与“三百六十五天”搭配。", "整周": "语义：“整周”只有七天，与三百六十五天不合。"}, "sentence_index": 6, "correct_answer": "全年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的全年很重，我抬不动。", "explanation": "语义：这里把“全年”当成了重量、分量的意思，但它只指一年的时间，不能用来形容物品的重量。"}, {"text": "她的全年很方，像一个盒子。", "explanation": "语义：这里把“全年”当成了形状的意思，但它只指一年的时间，不能用来形容物体的形状。"}, {"text": "她的全年很甜，大家都爱吃。", "explanation": "语义：这里把“全年”当成了味道的意思，但它只指一年的时间，不能用来形容食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司全年了的利润比去年高。", "corrected_sentence": "这家公司全年的利润比去年高。", "error_description": "错误：“全年”后面多了“了”。正确：去掉“了”，说“公司全年的利润”。“全年”是时间名词，不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家企业的产量全年了都很稳定。", "corrected_sentence": "这家企业的产量全年都很稳定。", "error_description": "错误：全年了都很稳定。正确：全年都很稳定。“全年”是时间名词，后面不能加“了”，表示整个时间段直接用“全年都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
