INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年的整个时间。", "primary_collocate": null, "pronunciation": "quán nián", "ipa": "tɕʰɥɛn˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这里全年气温都很高。", "target_word": "全年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民全年都在田里忙着。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全年下来，他只休息了五天。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们全年的工作都做完了。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园全年免费开放。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他全年的工资不到五万元。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年全年的销售数字出来了。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山全年都有雪。", "target_word": "全年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他全年住在海边的小房子里。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂全年没有停过工。", "target_word": "全年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全年：一年的整个时间，指一年里始终", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56189473-a491-472b-a780-7b2e60a5ec1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全年", "is_correct": true, "explanation": "正确：“全年”指一年里的整个时间，与“这里……气温都很高”相合。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指一段较短的时间，不能指整个一年的气温。"}, {"text": "时期", "is_correct": false, "explanation": "搭配：“时期”前要有修饰语，不能说“这里时期气温都很高”。"}, {"text": "年份", "is_correct": false, "explanation": "语义：“年份”指年的编号，不指一年的整个时间段。"}], "explanations": {"全年": "正确：“全年”指一年里的整个时间，与“这里……气温都很高”相合。", "季节": "语义：“季节”指一段较短的时间，不能指整个一年的气温。", "时期": "搭配：“时期”前要有修饰语，不能说“这里时期气温都很高”。", "年份": "语义：“年份”指年的编号，不指一年的整个时间段。"}, "sentence_index": 0, "correct_answer": "全年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的全年有三十天。", "explanation": "语义：这里把“全年”用成了“一个月”的意思，但“全年”指一年的整个时间，不能用来指一个月。"}, {"text": "他的全年很窄，只能坐一个人。", "explanation": "语义：这里把“全年”当成了空间宽窄的意思，但它只指一年的时间，不能用来形容空间的宽窄。"}, {"text": "这家饭店的全年很好吃。", "explanation": "语义：这里把“全年”当成了味道的意思，但它只指一年的时间，不能用来形容食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全年", "is_correct": true, "explanation": "正确：“全年”指一年的整个时间，与“今年……的销售数字”相合。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”只有七天，不能表示今年整年的销售数字。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是一天中的一段时间，与“今年”的范围不合。"}, {"text": "时刻", "is_correct": false, "explanation": "搭配：“时刻”指具体的时间点，不能与“今年”一起修饰销售数字。"}], "explanations": {"全年": "正确：“全年”指一年的整个时间，与“今年……的销售数字”相合。", "星期": "语义：“星期”只有七天，不能表示今年整年的销售数字。", "下午": "语义：“下午”是一天中的一段时间，与“今年”的范围不合。", "时刻": "搭配：“时刻”指具体的时间点，不能与“今年”一起修饰销售数字。"}, "sentence_index": 6, "correct_answer": "全年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的全年很干净，地板都能照出人影。", "explanation": "语义：这里把“全年”当成了干净、整洁的意思，但它只指一年的时间，不能用来形容环境。"}, {"text": "这家工厂的全年很香，机器都能闻到。", "explanation": "语义：这里把“全年”当成了气味的意思，但它只指一年的时间，不能用来形容气味。"}, {"text": "这家工厂把全年搬进了仓库。", "explanation": "语义：“全年”是时间段，不能作为“把”字结构里可以搬动的东西，这里的说法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市全年的很热。", "corrected_sentence": "这个城市全年很热。", "error_description": "错误：“全年”后面不能加“的”再接形容词。正确：“全年很热”，“全年”直接作主语，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司全年地利润增长了一成。", "corrected_sentence": "这家公司全年的利润增长了一成。", "error_description": "错误：全年地利润。正确：全年的利润。“全年”修饰名词时要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
