INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "整个省的范围。", "primary_collocate": null, "pronunciation": "quán shěng", "ipa": "tɕʰɥɛn˧˥ ʂɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次比赛在全省范围内举行。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全省一共有几千所学校。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字在全省很有名。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的店开遍了全省。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全省的人口有八千万。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全省的老师都来参加了会。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩在全省排第一。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全省哪里的菜最好吃？", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全省的水果这两年卖得很好。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻全省的人都知道。", "target_word": "全省", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "整个省的范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01a5a511-643b-455f-a743-1f7bb54c8652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全省", "is_correct": true, "explanation": "正确。全省指整个省的范围。"}, {"text": "全身", "is_correct": false, "explanation": "「全身」与「全省」第二个音节的韵母不同（shēn 与 shěng），声调也不同，意思是身体的整体。"}, {"text": "全盛", "is_correct": false, "explanation": "「全盛」与「全省」只有第二个音节的声调不同（shèng 与 shěng），意思是最兴盛的时期。"}, {"text": "全胜", "is_correct": false, "explanation": "「全胜」与「全省」只有第二个音节的声调不同（shèng 与 shěng），意思是完全获胜。"}], "explanations": {"全省": "正确。全省指整个省的范围。", "全身": "「全身」与「全省」第二个音节的韵母不同（shēn 与 shěng），声调也不同，意思是身体的整体。", "全盛": "「全盛」与「全省」只有第二个音节的声调不同（shèng 与 shěng），意思是最兴盛的时期。", "全胜": "「全胜」与「全省」只有第二个音节的声调不同（shèng 与 shěng），意思是完全获胜。"}, "sentence_index": null, "correct_answer": "全省"}, "level_3": {"options": [{"text": "全省", "is_correct": true, "explanation": "正确。「全省范围」指整个省的范围，与「比赛举行」搭配。"}, {"text": "全文", "is_correct": false, "explanation": "语义：「全文」指整篇文字，不能作比赛的场地范围。"}, {"text": "全天", "is_correct": false, "explanation": "语义：「全天」是时间，不能作空间范围。"}, {"text": "全家", "is_correct": false, "explanation": "搭配：「全家」指一家人，不能说「全家范围」。"}], "explanations": {"全省": "正确。「全省范围」指整个省的范围，与「比赛举行」搭配。", "全文": "语义：「全文」指整篇文字，不能作比赛的场地范围。", "全天": "语义：「全天」是时间，不能作空间范围。", "全家": "搭配：「全家」指一家人，不能说「全家范围」。"}, "sentence_index": 0, "correct_answer": "全省"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的店开遍了三个全省。", "explanation": "这里应该说「三个省」。「全省」指一个省的全部范围，不能用数量词计数。"}, {"text": "全省的总统是谁？", "explanation": "这里应该用〈全国〉。总统管理全国，「全省」只指一个省的范围，不能说「全省的总统」。"}, {"text": "全省的一间教室里坐满了学生。", "explanation": "这里应该说「这间教室」。「全省」指整个省的范围，太大，不能用来指一间教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全省", "is_correct": true, "explanation": "正确。「在全省排第一」指在整个省的范围里排名第一。"}, {"text": "全书", "is_correct": false, "explanation": "语义：「全书」指整本书，不能作排名的范围。"}, {"text": "全景", "is_correct": false, "explanation": "语义：「全景」指全部的景象，不能用来说排名。"}, {"text": "全套", "is_correct": false, "explanation": "搭配：「全套」指整套东西，不说「在全套排第一」。"}], "explanations": {"全省": "正确。「在全省排第一」指在整个省的范围里排名第一。", "全书": "语义：「全书」指整本书，不能作排名的范围。", "全景": "语义：「全景」指全部的景象，不能用来说排名。", "全套": "搭配：「全套」指整套东西，不说「在全套排第一」。"}, "sentence_index": 6, "correct_answer": "全省"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全省的总理在开会。", "explanation": "这里应该用〈全国〉。总理管理全国，「全省」只指一个省，不能说「全省的总理」。"}, {"text": "我们学校有三个全省的学生。", "explanation": "这里应该说「三个省」。「全省」表示一个省的全部范围，不能用数量词计数。"}, {"text": "我的眼镜放在全省的桌子上。", "explanation": "这里应该说「这张桌子上」。「全省」指整个省的范围，不能用来指一张桌子的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划在一个全省推行。", "corrected_sentence": "这个计划在全省推行。", "error_description": "量词错误：「全省」指整个省的范围，不能用量词「个」计数。正确说法是「在全省推行」，去掉「一个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目在每个全省都受欢迎。", "corrected_sentence": "这个节目在全省都受欢迎。", "error_description": "量词错误：「全省」本身指整个省的范围，前面不能再加「每个」。应去掉「每个」，说「在全省都受欢迎」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0f77f7f-a113-45b7-a041-c2f14fdf4dfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
