INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95033, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "列入是把一样东西写进名单里。", "primary_collocate": null, "pronunciation": "liè rù", "ipa": "lje˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "老师把他的名字列入了名单。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把我列入参赛名单。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的名字列入了获奖名单。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经把你列入名单了。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有列入这次比赛的名单。", "target_word": "列入", "complexity_tier": "T3", "furigana": "tā méi yǒu liè rù zhè cì bǐ sài de míng dān", "sentence_source": "generated"}, {"text": "经理把五个人列入了面试名单。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师曾把这个孩子列入班上的名单。", "target_word": "列入", "complexity_tier": "T3", "furigana": "lǎo shī céng bǎ zhè ge hái zi liè rù bān shàng de míng dān", "sentence_source": "generated"}, {"text": "请把新同学列入名册。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字列入了黑名单。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把客人的名字列入来宾名单。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "列入了", "label": "体标"}, {"form": "列入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把人或事物的名字写进名单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee0abe9c-383b-4465-adda-6a9bff074073') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95033, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "列入", "is_correct": true, "explanation": "正确：列入（liè rù）指把名字或事物写进名单里。"}, {"text": "介入", "is_correct": false, "explanation": "jiè（介）与 liè（列）声母不同，意思是插手干预，不是写进名单。"}, {"text": "借入", "is_correct": false, "explanation": "jiè（借）与 liè（列）声母不同，意思是借进钱或物。"}, {"text": "烈日", "is_correct": false, "explanation": "末音节 rì 与 rù（入）韵母不同，意思是炎热的太阳。"}, {"text": "流入", "is_correct": false, "explanation": "首音节 liú 与 liè（列）韵母和声调都不同，意思是流进。"}, {"text": "猎人", "is_correct": false, "explanation": "末音节 rén 与 rù（入）韵母和声调不同，意思是猎手。"}], "explanations": {"列入": "正确：列入（liè rù）指把名字或事物写进名单里。", "介入": "jiè（介）与 liè（列）声母不同，意思是插手干预，不是写进名单。", "借入": "jiè（借）与 liè（列）声母不同，意思是借进钱或物。", "烈日": "末音节 rì 与 rù（入）韵母不同，意思是炎热的太阳。", "流入": "首音节 liú 与 liè（列）韵母和声调都不同，意思是流进。", "猎人": "末音节 rén 与 rù（入）韵母和声调不同，意思是猎手。"}, "sentence_index": null, "correct_answer": "列入"}, "level_3": {"options": [{"text": "列入", "is_correct": true, "explanation": "正确：「列入了名单」指把名字放进名单，与句中「把他的名字」「名单」吻合。"}, {"text": "去掉", "is_correct": false, "explanation": "配价：「去掉」的处所要用「从……上」引出，不能直接接「名单」。"}, {"text": "划掉", "is_correct": false, "explanation": "搭配：「划掉」的对象是名字，应说「从名单上划掉」，不说「划掉名单」。"}, {"text": "查看", "is_correct": false, "explanation": "配价：「查看」只带一个宾语，不能让「他的名字」再被「把」处置。"}], "explanations": {"列入": "正确：「列入了名单」指把名字放进名单，与句中「把他的名字」「名单」吻合。", "去掉": "配价：「去掉」的处所要用「从……上」引出，不能直接接「名单」。", "划掉": "搭配：「划掉」的对象是名字，应说「从名单上划掉」，不说「划掉名单」。", "查看": "配价：「查看」只带一个宾语，不能让「他的名字」再被「把」处置。"}, "sentence_index": 0, "correct_answer": "列入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的工资列入了两万元。", "explanation": "这里应该用〈收入〉。列入指把人或事物写进名单或计划，说收到多少钱要用收入。"}, {"text": "我在网上列入了马拉松比赛。", "explanation": "这里应该用〈报名〉。报名指申请参加比赛，列入指把东西写进名单，说自己参赛要用报名。"}, {"text": "他在银行列入了五百元。", "explanation": "这里应该用〈存入〉。列入指写进名单或计划，把钱存进银行要用存入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "列入", "is_correct": true, "explanation": "正确：「列入班上的名单」指把孩子写进名单，符合句意。"}, {"text": "排除", "is_correct": false, "explanation": "搭配：「排除」不能直接带「名单」，要说「排除在名单之外」；而且意思和「列入」相反。"}, {"text": "送入", "is_correct": false, "explanation": "搭配：「送入」多接场所或机构，如「送入医院」，不说送入名单。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：「拍照」与把孩子写进名单无关，句意不通。"}], "explanations": {"列入": "正确：「列入班上的名单」指把孩子写进名单，符合句意。", "排除": "搭配：「排除」不能直接带「名单」，要说「排除在名单之外」；而且意思和「列入」相反。", "送入": "搭配：「送入」多接场所或机构，如「送入医院」，不说送入名单。", "拍照": "语义：「拍照」与把孩子写进名单无关，句意不通。"}, "sentence_index": 6, "correct_answer": "列入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "管理员把这些数据列入了硬盘。", "explanation": "这里应该用〈保存〉。列入指写进名单或计划，把数据存进硬盘要用保存。"}, {"text": "妈妈把钱列入钱包里。", "explanation": "这里应该用〈放入〉。列入指写进名单，把东西装进钱包要用放入。"}, {"text": "他刚列入大学。", "explanation": "这里应该用〈进入〉。列入指写进名单，进入学校要用进入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
