INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95034, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放进某个范围或名单之中。", "primary_collocate": null, "pronunciation": "liè rù", "ipa": "lje˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "这个问题已经列入明年的计划。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河列入了城市建设的计划。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把这件事列入工作计划。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药没有列入医保范围。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子列入了保护范围。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把环保列入今年的重点工作。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目列入了周末的安排。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把运动列入每天的安排。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书列入了学生必读书目。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市列入了旅游路线。", "target_word": "列入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "列入了", "label": "体标"}, {"form": "列入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把事物放进某个计划或范围之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee0abe9c-383b-4465-adda-6a9bff074073') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "列入", "is_correct": true, "explanation": "正确：列入（liè rù）指放进某个范围或名单之中。"}, {"text": "介入", "is_correct": false, "explanation": "jiè（介）与 liè（列）声母不同，意思是插手干预。"}, {"text": "借入", "is_correct": false, "explanation": "jiè（借）与 liè（列）声母不同，意思是借进钱或物。"}, {"text": "烈日", "is_correct": false, "explanation": "末音节 rì 与 rù（入）韵母不同，意思是炎热的太阳。"}, {"text": "流入", "is_correct": false, "explanation": "首音节 liú 与 liè（列）韵母和声调都不同，意思是流进。"}, {"text": "猎人", "is_correct": false, "explanation": "末音节 rén 与 rù（入）韵母和声调不同，意思是猎手。"}], "explanations": {"列入": "正确：列入（liè rù）指放进某个范围或名单之中。", "介入": "jiè（介）与 liè（列）声母不同，意思是插手干预。", "借入": "jiè（借）与 liè（列）声母不同，意思是借进钱或物。", "烈日": "末音节 rì 与 rù（入）韵母不同，意思是炎热的太阳。", "流入": "首音节 liú 与 liè（列）韵母和声调都不同，意思是流进。", "猎人": "末音节 rén 与 rù（入）韵母和声调不同，意思是猎手。"}, "sentence_index": null, "correct_answer": "列入"}, "level_3": {"options": [{"text": "列入", "is_correct": true, "explanation": "正确：「列入明年的计划」指把问题放进计划，与句意吻合。"}, {"text": "排除", "is_correct": false, "explanation": "语义：「排除」是去掉，与「列入计划」相反。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：「问题」不能做「完成」的主语，「问题完成计划」说不通。"}, {"text": "实现", "is_correct": false, "explanation": "搭配：「问题」不能「实现」计划，主语和动词不搭配。"}], "explanations": {"列入": "正确：「列入明年的计划」指把问题放进计划，与句意吻合。", "排除": "语义：「排除」是去掉，与「列入计划」相反。", "完成": "搭配：「问题」不能做「完成」的主语，「问题完成计划」说不通。", "实现": "搭配：「问题」不能「实现」计划，主语和动词不搭配。"}, "sentence_index": 0, "correct_answer": "列入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书列入包里了。", "explanation": "这里应该用〈放入〉。列入指写进名单或计划，把东西装进包里要用放入。"}, {"text": "这个计划列入三个部分。", "explanation": "这里应该用〈包括〉。列入指放进名单，说计划含有几个部分要用包括。"}, {"text": "医生列入了病人的病情。", "explanation": "这里应该用〈记录〉。列入指放进名单，把病情记下来要用记录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "列入", "is_correct": true, "explanation": "正确：「列入了周末的安排」指把节目放进安排之中，符合句意。"}, {"text": "批准", "is_correct": false, "explanation": "语义：「批准」要由有权的人或机构做出，节目不能批准安排。"}, {"text": "相信", "is_correct": false, "explanation": "搭配：「相信」的主语应是人，节目不能「相信」安排。"}, {"text": "对待", "is_correct": false, "explanation": "搭配：「对待」的主语应是人，「节目对待安排」不通。"}], "explanations": {"列入": "正确：「列入了周末的安排」指把节目放进安排之中，符合句意。", "批准": "语义：「批准」要由有权的人或机构做出，节目不能批准安排。", "相信": "搭配：「相信」的主语应是人，节目不能「相信」安排。", "对待": "搭配：「对待」的主语应是人，「节目对待安排」不通。"}, "sentence_index": 6, "correct_answer": "列入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店这个月列入了十万元。", "explanation": "这里应该用〈收入〉。列入指写进名单，说收到多少钱要用收入。"}, {"text": "我去派出所列入了身份证。", "explanation": "这里应该用〈办理〉。列入指写进名单或计划，去派出所办证件要用办理。"}, {"text": "火车列入了车站。", "explanation": "这里应该用〈进入〉。列入指写进名单，火车驶入车站要用进入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
