INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95035, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "剥削是拿走别人做出来的东西，不给钱。", "primary_collocate": null, "pronunciation": "bō xuē", "ipa": "pwo˥ ɕɥe˥", "syllable_count": 2, "sentences": [{"text": "老板剥削工人，不给他们工资。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个公司剥削了很多年轻人。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们剥削农民的劳动成果，不付报酬。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂剥削过工人。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板剥削着工人的劳动，自己很有钱。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再也不愿意受老板剥削了。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去，地主剥削农民。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这家店剥削小工。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人总是剥削同事的成果。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们不满老板剥削他们。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剥削了", "label": "完成体"}, {"form": "剥削过", "label": "经历体"}, {"form": "剥削着", "label": "持续体"}], "register": "书面", "sense_fingerprint": "拿走别人做出来的东西而不付钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95035, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剥削", "is_correct": true, "explanation": "正确：“剥削”指无偿占有工人的劳动，与后句“不给他们工资”相符。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是给予好处，与后句“不给他们工资”矛盾。"}, {"text": "辅导", "is_correct": false, "explanation": "语义：“辅导”是帮助别人学习，与后句“不给他们工资”的语境不合。"}, {"text": "资助", "is_correct": false, "explanation": "语义：“资助”是提供钱财支持，与后句“不给他们工资”矛盾。"}], "explanations": {"剥削": "正确：“剥削”指无偿占有工人的劳动，与后句“不给他们工资”相符。", "奖励": "语义：“奖励”是给予好处，与后句“不给他们工资”矛盾。", "辅导": "语义：“辅导”是帮助别人学习，与后句“不给他们工资”的语境不合。", "资助": "语义：“资助”是提供钱财支持，与后句“不给他们工资”矛盾。"}, "sentence_index": 0, "correct_answer": "剥削"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法律规定，不能剥削公民的选举权。", "explanation": "这里应该用〈剥夺〉。剥削指无偿占有他人的劳动成果，权利被夺去要用“剥夺”。"}, {"text": "我们要充分剥削这些自然资源。", "explanation": "这里应该用〈利用〉。剥削专指无偿占有他人的劳动成果，自然资源应说“利用”。"}, {"text": "这个人剥削了我的座位。", "explanation": "这里应该用〈占用〉。剥削指无偿占有他人的劳动成果，占座位要说“占用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95035, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剥削", "is_correct": true, "explanation": "正确：“剥削”指无偿占有农民的劳动，与句中“地主”的身份相符。"}, {"text": "赡养", "is_correct": false, "explanation": "搭配：“赡养”的对象多是老人或父母，不说赡养农民。"}, {"text": "解放", "is_correct": false, "explanation": "语义：“解放”是让人摆脱压迫，与句中“地主”的压迫身份矛盾。"}, {"text": "慰问", "is_correct": false, "explanation": "语义：“慰问”是表示关怀，与地主占有农民劳动的语境不符。"}], "explanations": {"剥削": "正确：“剥削”指无偿占有农民的劳动，与句中“地主”的身份相符。", "赡养": "搭配：“赡养”的对象多是老人或父母，不说赡养农民。", "解放": "语义：“解放”是让人摆脱压迫，与句中“地主”的压迫身份矛盾。", "慰问": "语义：“慰问”是表示关怀，与地主占有农民劳动的语境不符。"}, "sentence_index": 6, "correct_answer": "剥削"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该好好剥削生活，多做有意义的事。", "explanation": "这里应该用〈享受〉。剥削指无偿占有他人的劳动成果，享受生活要用“享受”。"}, {"text": "大家都在剥削这幅画的美。", "explanation": "这里应该用〈欣赏〉。剥削只指无偿占有劳动成果，欣赏画的美要用“欣赏”。"}, {"text": "他很快剥削了这项技术。", "explanation": "这里应该用〈掌握〉。剥削指无偿占有他人的劳动成果，学会技术要用“掌握”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老板曾经剥削着很多工人。", "corrected_sentence": "那位老板曾经剥削过很多工人。", "error_description": "“曾经”表示过去的经历，要用表示经历的“过”，不能用表示持续的“着”，应说“剥削过很多工人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人经常老板剥削。", "corrected_sentence": "工人经常被老板剥削。", "error_description": "被字句要加“被”：应说“工人经常被老板剥削”，不能省去“被”说“工人经常老板剥削”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
