INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "无偿占有他人的劳动成果。", "primary_collocate": null, "pronunciation": "bō xuē", "ipa": "pwo˥ ɕɥe˥", "syllable_count": 2, "sentences": [{"text": "地主长期剥削农民的劳动。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让工人加班不给钱，这是剥削工人。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们剥削了孩子的劳动成果。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人靠剥削别人生活。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，有钱人剥削穷人。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂剥削工人很多年了。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能剥削别人的劳动。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直剥削着手下的人。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现老板剥削了所有员工。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剥削别人的人会受到批评。", "target_word": "剥削", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剥削了", "label": "完成体"}, {"form": "剥削过", "label": "经历体"}, {"form": "剥削着", "label": "持续体"}], "register": "书面", "sense_fingerprint": "无偿占有他人的劳动成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剥削", "is_correct": true, "explanation": "正确：“剥削”指无偿占有农民的劳动成果，与“地主长期”的语境相符。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物或幼儿，不说喂养“劳动”。"}, {"text": "播种", "is_correct": false, "explanation": "搭配：“播种”的对象是种子，不说播种“劳动”。"}, {"text": "赡养", "is_correct": false, "explanation": "搭配：“赡养”的对象是人，不说赡养“劳动”。"}], "explanations": {"剥削": "正确：“剥削”指无偿占有农民的劳动成果，与“地主长期”的语境相符。", "喂养": "搭配：“喂养”的对象是动物或幼儿，不说喂养“劳动”。", "播种": "搭配：“播种”的对象是种子，不说播种“劳动”。", "赡养": "搭配：“赡养”的对象是人，不说赡养“劳动”。"}, "sentence_index": 0, "correct_answer": "剥削"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他剥削了一块蛋糕，拿去分给妹妹。", "explanation": "这里应该用〈切〉。剥削指无偿占有他人的劳动成果，从蛋糕上取下一块要用“切”。"}, {"text": "我们要合理剥削时间，别浪费。", "explanation": "这里应该用〈利用〉。剥削专指无偿占有他人的劳动成果，时间应说“利用”。"}, {"text": "他在图书馆剥削了一个空座位。", "explanation": "这里应该用〈占据〉。剥削指无偿占有他人的劳动成果，占座位要说“占据”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剥削", "is_correct": true, "explanation": "正确：“剥削”指无偿占有他人的劳动成果，正是“不能”要避免的行为。"}, {"text": "欺骗", "is_correct": false, "explanation": "搭配：“欺骗”的对象是人，不说欺骗“劳动”。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不说饲养“劳动”。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：句中“不能”后接“尊重”与常理相反，句意不通。"}], "explanations": {"剥削": "正确：“剥削”指无偿占有他人的劳动成果，正是“不能”要避免的行为。", "欺骗": "搭配：“欺骗”的对象是人，不说欺骗“劳动”。", "饲养": "搭配：“饲养”的对象是动物，不说饲养“劳动”。", "尊重": "语义：句中“不能”后接“尊重”与常理相反，句意不通。"}, "sentence_index": 6, "correct_answer": "剥削"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师很会剥削学生的兴趣。", "explanation": "这里应该用〈培养〉。剥削指无偿占有他人的劳动成果，培养兴趣要用“培养”。"}, {"text": "他很快剥削了这道难题。", "explanation": "这里应该用〈解决〉。剥削指无偿占有他人的劳动成果，解决难题要用“解决”。"}, {"text": "他按时剥削了作业。", "explanation": "这里应该用〈完成〉。剥削指无偿占有他人的劳动成果，按时交作业要用“完成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家小店一直剥削过学徒的劳动。", "corrected_sentence": "那家小店一直剥削着学徒的劳动。", "error_description": "“一直”表示动作持续，要用表示持续的“着”，不能用表示经历的“过”，应说“一直剥削着学徒的劳动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人一直剥削得别人的劳动。", "corrected_sentence": "那个人一直剥削别人的劳动。", "error_description": "“得”引出的是补语，此句“得”后没有补语，应删去“得”：应说“一直剥削别人的劳动”，不能说“一直剥削得别人的劳动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
