INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "口味是吃东西时喜欢的味道。", "primary_collocate": null, "pronunciation": "kǒu wèi", "ipa": "kʰoʊ˨˩˦ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我的口味比较清淡，不太爱吃辣。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜很合我的口味。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的口味不一样，有人爱吃甜的。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢什么口味的冰淇淋？", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈知道我的口味，做了我爱吃的菜。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人和南方人的口味不太一样。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人口味淡，菜里不要放太多盐。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饼干有三种口味：草莓、巧克力和牛奶。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了口味，今天想吃点辣的。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他口味很重，每顿饭都要放很多辣椒。", "target_word": "口味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种口味", "label": "量词"}], "register": "中性", "sense_fingerprint": "吃东西时喜欢的味道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口味", "is_correct": true, "explanation": "正确：“口味”指吃东西时喜欢的味道，与“清淡”搭配；后半句“不太爱吃辣”也说明这是口味上的偏好。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“清淡”形容味道、颜色等，不用来说人的体重。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“清淡”不用来形容身材，句中“不太爱吃辣”也与身材无关。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“清淡”不用来形容声音，句中“不太爱吃辣”也与声音无关。"}], "explanations": {"口味": "正确：“口味”指吃东西时喜欢的味道，与“清淡”搭配；后半句“不太爱吃辣”也说明这是口味上的偏好。", "体重": "搭配：“清淡”形容味道、颜色等，不用来说人的体重。", "身材": "搭配：“清淡”不用来形容身材，句中“不太爱吃辣”也与身材无关。", "声音": "搭配：“清淡”不用来形容声音，句中“不太爱吃辣”也与声音无关。"}, "sentence_index": 0, "correct_answer": "口味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个面包的口味很软，吃起来很舒服。", "explanation": "这里应该用〈口感〉。口感指食物入口时的软、脆、滑等感觉；口味指吃东西时喜欢的味道，不能用来说入口的软硬。"}, {"text": "我的口味很灵敏，能尝出很细微的差别。", "explanation": "这里应该用〈味觉〉。味觉是舌头辨别味道的能力；口味指喜欢的味道，不能用“灵敏”来形容。"}, {"text": "他说话的口味很硬，大家都不敢反驳。", "explanation": "这里应该用〈口气〉。“口气很硬”形容说话的语气；口味指吃东西的喜好，不能用来形容说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口味", "is_correct": true, "explanation": "正确：“口味淡”指偏好清淡，后句“菜里不要放太多盐”与之呼应。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“淡”形容味道或颜色，不用来说体温。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”与“菜里不要放太多盐”的句意无关，句中的“淡”也不指年纪。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“淡”不用来形容脚步，句中也没有与行走有关的线索。"}], "explanations": {"口味": "正确：“口味淡”指偏好清淡，后句“菜里不要放太多盐”与之呼应。", "体温": "搭配：“淡”形容味道或颜色，不用来说体温。", "年纪": "语义：“年纪”与“菜里不要放太多盐”的句意无关，句中的“淡”也不指年纪。", "脚步": "搭配：“淡”不用来形容脚步，句中也没有与行走有关的线索。"}, "sentence_index": 6, "correct_answer": "口味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次辩论中，他的口味发挥得很好。", "explanation": "这里应该用〈口才〉。“发挥”可用于口才，如“发挥口才”；口味指吃东西的喜好，不能用“发挥”来说说话的能力。"}, {"text": "他的口味很灵，能闻出很远的香味。", "explanation": "这里应该用〈嗅觉〉。嗅觉是鼻子辨别气味的能力；口味指喜欢的味道，不能用“灵”来说辨别气味的能力。"}, {"text": "他的口味很重，每次说话都能听出是哪里人。", "explanation": "这里应该用〈口音〉。口音指说话的发音特点，能听出是哪里人；口味指吃东西的喜好，不能用来说明发音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店有三只口味的冰淇淋。", "corrected_sentence": "这家店有三种口味的冰淇淋。", "error_description": "量词错误：“口味”的量词应用“种”，不能用“只”。“只”多用于动物或成对、单个的东西，应说“三种口味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他口味重很，喜欢吃麻辣的菜。", "corrected_sentence": "他口味很重，喜欢吃麻辣的菜。", "error_description": "语序错误：程度副词“很”要放在形容词前面，应说“口味很重”，不能说“口味重很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
