INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95039, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把世界各地的计算机和用户连接起来的信息网络。", "primary_collocate": null, "pronunciation": "guó jì wǎng luò", "ipa": "kwo˧˥ tɕi˥˩ waŋ˨˩˦ lwo˥˩", "syllable_count": 4, "sentences": [{"text": "国际网络让世界各地的人能聊天。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用国际网络给国外的朋友发信。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际网络连着世界上很多国家。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有国际网络，我们看不到外国新闻。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际网络把全世界的人连在了一起。", "target_word": "国际网络", "complexity_tier": "T3", "furigana": "guó jì wǎng luò bǎ quán shì jiè de rén lián zài le yì qǐ.", "sentence_source": "generated"}, {"text": "学校的电脑已经连上国际网络。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际网络很大，信息特别多。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的村子也有国际网络了。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际网络出问题，全世界都受影响。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们通过国际网络学英语。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连接全球计算机与用户的信息网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '109ed30c-9583-414f-9809-33e9e60b7ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际网络", "is_correct": true, "explanation": "国际网络：连起全世界的网络，能让世界各地的人聊天。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是存放书籍的场所，不能让世界各地的人聊天。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园是供人参观动物的地方，与“让人聊天”的功能无关。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“让……能聊天”要求施事是信息系统或能说话的人，“厨房”不能充当这样的主语。"}], "explanations": {"国际网络": "国际网络：连起全世界的网络，能让世界各地的人聊天。", "图书馆": "语义：图书馆是存放书籍的场所，不能让世界各地的人聊天。", "动物园": "语义：动物园是供人参观动物的地方，与“让人聊天”的功能无关。", "厨房": "搭配：“让……能聊天”要求施事是信息系统或能说话的人，“厨房”不能充当这样的主语。"}, "sentence_index": 0, "correct_answer": "国际网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天开着国际网络去上班。", "explanation": "这里应该用〈汽车〉。国际网络是信息网络，不能“开着去上班”。"}, {"text": "我们每天坐国际网络去上海。", "explanation": "这里应该用〈火车〉。国际网络是信息网络，不是交通工具，不能用“坐”。"}, {"text": "两国签订了国际网络。", "explanation": "这里应该用〈国际公约〉。签订的是条约或协议，国际网络不是文件，不能被签订。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际网络", "is_correct": true, "explanation": "国际网络：信息系统，可以很大、包含很多信息。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不会“信息特别多”。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠是自然地貌，不是信息的载体，与“信息特别多”不合。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”指吃饭的数量，不能与“信息特别多”搭配。"}], "explanations": {"国际网络": "国际网络：信息系统，可以很大、包含很多信息。", "冰箱": "语义：冰箱是家用电器，不会“信息特别多”。", "沙漠": "语义：沙漠是自然地貌，不是信息的载体，与“信息特别多”不合。", "饭量": "搭配：“饭量”指吃饭的数量，不能与“信息特别多”搭配。"}, "sentence_index": 6, "correct_answer": "国际网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天给国际网络浇水。", "explanation": "这里应该用〈花〉。“浇水”的对象是植物，国际网络是信息系统，不能被浇水。"}, {"text": "国际网络上周生了一个孩子。", "explanation": "这里应该用〈她〉。生孩子的主语必须是人，国际网络是信息系统，不能生育。"}, {"text": "这个国际网络比我高三十厘米。", "explanation": "这里应该用〈同学〉。比较身高的对象是人，国际网络没有身高，不能这样比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天国际网络给外国同学发邮件。", "corrected_sentence": "我每天用国际网络给外国同学发邮件。", "error_description": "“国际网络”是发信的工具，前面需要用“用”引出；缺少“用”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们经常国际网络学英语。", "corrected_sentence": "孩子们经常通过国际网络学英语。", "error_description": "“国际网络”作为“学”的凭借方式，需用介词“通过”引出，缺少“通过”，应为“通过国际网络学英语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
