INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由跨国机构、企业或组织形成的、分布于多个国家的分支或合作网络。", "primary_collocate": null, "pronunciation": "guó jì wǎng luò", "ipa": "kwo˧˥ tɕi˥˩ waŋ˨˩˦ lwo˥˩", "syllable_count": 4, "sentences": [{"text": "这家公司有覆盖二十国的国际网络。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行靠国际网络转账给国外客户。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递公司的国际网络很完整。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们组成国际网络，一起研究这种病。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话公司正在扩大国际网络。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国际网络里有很多大学。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建一个国际网络需要很多钱。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用国际网络把货送到各国。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店属于一个国际网络。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家航空公司的国际网络遍布三十多个国家。", "target_word": "国际网络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "跨国机构的分支或合作网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '109ed30c-9583-414f-9809-33e9e60b7ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际网络", "is_correct": true, "explanation": "国际网络：公司分布在多个国家的分支网络，可以覆盖二十个国家。"}, {"text": "乐队", "is_correct": false, "explanation": "搭配：“覆盖”的对象是网络、范围等，不能搭配“乐队”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，不能覆盖二十个国家。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，与“覆盖二十个国家”的意思不合。"}], "explanations": {"国际网络": "国际网络：公司分布在多个国家的分支网络，可以覆盖二十个国家。", "乐队": "搭配：“覆盖”的对象是网络、范围等，不能搭配“乐队”。", "玩具": "语义：玩具是物品，不能覆盖二十个国家。", "词典": "语义：词典是工具书，与“覆盖二十个国家”的意思不合。"}, "sentence_index": 0, "correct_answer": "国际网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "各国代表在日内瓦召开国际网络。", "explanation": "这里应该用〈国际会议〉。“召开”的对象是会议，网络不能被召开。"}, {"text": "妈妈把国际网络放进冰箱里了。", "explanation": "这里应该用〈水果〉。国际网络是跨国的分支网络，不能放进冰箱。"}, {"text": "他很喜欢吃国际网络。", "explanation": "这里应该用〈国际料理〉。“吃”的对象是食物，国际网络不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际网络", "is_correct": true, "explanation": "国际网络：跨国机构或企业的分支网络，建设需要很多钱。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话是言语，不能被“建”，与“需要很多钱”也不合。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“建”搭配的是系统、工程等，不能搭配“心情”。"}, {"text": "谎言", "is_correct": false, "explanation": "搭配：“建”不能搭配“谎言”，说谎话用“编造”之类的词。"}], "explanations": {"国际网络": "国际网络：跨国机构或企业的分支网络，建设需要很多钱。", "笑话": "语义：笑话是言语，不能被“建”，与“需要很多钱”也不合。", "心情": "搭配：“建”搭配的是系统、工程等，不能搭配“心情”。", "谎言": "搭配：“建”不能搭配“谎言”，说谎话用“编造”之类的词。"}, "sentence_index": 6, "correct_answer": "国际网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把国际网络穿在身上。", "explanation": "这里应该用〈外套〉。国际网络是跨国机构的分支网络，不能穿。"}, {"text": "这个国际网络每天早上六点起床上班。", "explanation": "这里应该用〈职员〉。起床、上班的主语是人，国际网络是系统，不能做这些动作。"}, {"text": "他是国际网络。", "explanation": "这里应该用〈律师〉。网络是系统，不能指人，也不能用“是”来描述人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国际网络没有覆盖了非洲。", "corrected_sentence": "这个国际网络没有覆盖非洲。", "error_description": "“没有”否定已发生的动作时，动词后不能再加“了”；“没有覆盖了非洲”应为“没有覆盖非洲”，错误在于多出了“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家航空公司加入了一只国际网络。", "corrected_sentence": "这家航空公司加入了一个国际网络。", "error_description": "“国际网络”的量词应用“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dedbc29c-746d-487f-b362-bdc472522b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
