INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95042, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地区和市的合称，指省以下的行政区划。", "primary_collocate": null, "pronunciation": "dì shì", "ipa": "ti˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "全省的地市都开了会。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省里请各地市送来报告。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省一共有二十一个地市。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地市一级的医院比县里的大。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个地市的老师今天来省城学习。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些地市的经济发展得很快。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去过省内好几个地市。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个地市的天气都很冷。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省里的地市要一起修这条路。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是从北方一个地市来的。", "target_word": "地市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地市级", "label": "复合"}], "register": "书面", "sense_fingerprint": "地区和市的合称，省以下的行政区划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6217be5-e5ea-4a87-a628-c92f2ff422f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95042, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地市", "is_correct": true, "explanation": "地市是地区和市的合称，指省以下的行政区划，就是这个词本身。"}, {"text": "地质", "is_correct": false, "explanation": "zhì 与 shì 声母不同，意思是地质（研究地球构造和成分的学问）。"}, {"text": "力士", "is_correct": false, "explanation": "lì 与 dì 声母不同，都是第四声，意思是力士（力气很大的人）。"}, {"text": "敌视", "is_correct": false, "explanation": "dí（第二声）与 dì（第四声）声调不同，意思是敌视（把人当作敌人看待）。"}, {"text": "第四", "is_correct": false, "explanation": "sì 与 shì 声母不同，都是第四声，意思是顺序上的第四。"}], "explanations": {"地市": "地市是地区和市的合称，指省以下的行政区划，就是这个词本身。", "地质": "zhì 与 shì 声母不同，意思是地质（研究地球构造和成分的学问）。", "力士": "lì 与 dì 声母不同，都是第四声，意思是力士（力气很大的人）。", "敌视": "dí（第二声）与 dì（第四声）声调不同，意思是敌视（把人当作敌人看待）。", "第四": "sì 与 shì 声母不同，都是第四声，意思是顺序上的第四。"}, "sentence_index": null, "correct_answer": "地市"}, "level_3": {"options": [{"text": "地市", "is_correct": true, "explanation": "地市是省以下的行政区划，是能够开会的组织单位，「全省的地市都开了会」符合语义。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是建筑物，不能开会，「全省的桥都开了会」说不通。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是自然水体，不能开会，「全省的河都开了会」说不通。"}, {"text": "矿", "is_correct": false, "explanation": "搭配：「开会」的主体应是人或组织，矿不能开会，这个搭配不成立。"}], "explanations": {"地市": "地市是省以下的行政区划，是能够开会的组织单位，「全省的地市都开了会」符合语义。", "桥": "语义：桥是建筑物，不能开会，「全省的桥都开了会」说不通。", "河": "语义：河是自然水体，不能开会，「全省的河都开了会」说不通。", "矿": "搭配：「开会」的主体应是人或组织，矿不能开会，这个搭配不成立。"}, "sentence_index": 0, "correct_answer": "地市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天戴着地市去上班。", "explanation": "这里应该用〈手表〉。地市是行政区划，不是可以戴在身上的东西；「手表」才能戴。"}, {"text": "我家门口的地市很宽。", "explanation": "这里应该用〈街道〉。地市是行政区划，不是门口可以看见的路。"}, {"text": "这个地市很大，有两扇窗。", "explanation": "这里应该用〈房间〉。地市是行政区划，没有窗户，不能说有两扇窗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95042, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地市", "is_correct": true, "explanation": "地市是地区和市的合称，指省以下的行政区划，就是这个词本身。"}, {"text": "志士", "is_correct": false, "explanation": "zhì 与 dì 声母不同，都是第四声，意思是志士（有远大志向的人）。"}, {"text": "世事", "is_correct": false, "explanation": "shì 与 dì 声母不同，都是第四声，意思是世间的事情。"}, {"text": "记事", "is_correct": false, "explanation": "jì 与 dì 声母不同，都是第四声，意思是把事情记录下来。"}, {"text": "气势", "is_correct": false, "explanation": "qì 与 dì 声母不同，都是第四声，意思是气派和声势。"}], "explanations": {"地市": "地市是地区和市的合称，指省以下的行政区划，就是这个词本身。", "志士": "zhì 与 dì 声母不同，都是第四声，意思是志士（有远大志向的人）。", "世事": "shì 与 dì 声母不同，都是第四声，意思是世间的事情。", "记事": "jì 与 dì 声母不同，都是第四声，意思是把事情记录下来。", "气势": "qì 与 dì 声母不同，都是第四声，意思是气派和声势。"}, "sentence_index": null, "correct_answer": "地市"}, "level_3": {"options": [{"text": "地市", "is_correct": true, "explanation": "地市是省以下的行政区划，「省内好几个地市」符合语义。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词「个」不配「书」，书应说「本」，「好几个书」不成立。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通信工具，不是可以去过的地方，「去过省内好几个手机」说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是可以去过的地方，「去过省内好几个桌子」说不通。"}], "explanations": {"地市": "地市是省以下的行政区划，「省内好几个地市」符合语义。", "书": "搭配：量词「个」不配「书」，书应说「本」，「好几个书」不成立。", "手机": "语义：手机是通信工具，不是可以去过的地方，「去过省内好几个手机」说不通。", "桌子": "语义：桌子是家具，不是可以去过的地方，「去过省内好几个桌子」说不通。"}, "sentence_index": 6, "correct_answer": "地市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的地市很健康。", "explanation": "这里应该用〈身体〉。地市是行政区划，不能说健康。"}, {"text": "这个地市很好用。", "explanation": "这里应该用〈电话〉。地市是行政区划，不是工具，不能说好用。"}, {"text": "她的地市很白。", "explanation": "这里应该用〈牙齿〉。地市不能说颜色白，描述牙齿白要用「牙齿」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个地市们都通了高铁。", "corrected_sentence": "这几个地市都通了高铁。", "error_description": "错误形式「地市们」，正确形式「地市」。「地市」是行政区划，不能加「们」表示复数，多个地市用「这几个」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "省里请了两只地市来开会。", "corrected_sentence": "省里请了两个地市来开会。", "error_description": "错误在量词。「地市」是行政区划，量词要用「个」，不能用「只」（「只」多用于动物等）。正确形式「两个地市」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07d894-ec92-4c2c-bd46-9898e61d91b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
