INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "境外是国家边界的外面。", "primary_collocate": null, "pronunciation": "jìng wài", "ipa": "tɕiŋ˥˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他在境外工作了三年。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在境外有三个办公室。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "境外的朋友给我寄来了礼物。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从境外来的客人要先检查护照。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些货是从境外买来的。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机在境外不能用。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去境外旅行要带好护照。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的家人都住在境外。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在境外的实验室做研究。", "target_word": "境外", "complexity_tier": "T3", "furigana": "jìng wài", "sentence_source": "generated"}, {"text": "他去境外看病了。", "target_word": "境外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "境外：国家边界的外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8a6e1b4-4957-4aa2-bef8-2e14d4c5083b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95043, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "境外", "is_correct": true, "explanation": "正确：境外指国境以外，即国家边界的外面。"}, {"text": "敬畏", "is_correct": false, "explanation": "wèi 与 wài 韵母不同（ei/ai），敬畏指尊敬而又害怕，不指地点。"}, {"text": "另外", "is_correct": false, "explanation": "lìng 与 jìng 声母不同（l/j），另外表示“此外”，与境外意思不同。"}, {"text": "敬爱", "is_correct": false, "explanation": "第二个音节去掉声母 w 变成 ài，敬爱指尊重和喜爱，与境外意思不同。"}], "explanations": {"境外": "正确：境外指国境以外，即国家边界的外面。", "敬畏": "wèi 与 wài 韵母不同（ei/ai），敬畏指尊敬而又害怕，不指地点。", "另外": "lìng 与 jìng 声母不同（l/j），另外表示“此外”，与境外意思不同。", "敬爱": "第二个音节去掉声母 w 变成 ài，敬爱指尊重和喜爱，与境外意思不同。"}, "sentence_index": null, "correct_answer": "境外"}, "level_3": {"options": [{"text": "境外", "is_correct": true, "explanation": "正确：境外指国境以外，“在境外工作”即在国外工作。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是工作的地点，“在钢琴工作”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的部件，不能作为工作的地点。"}, {"text": "星期", "is_correct": false, "explanation": "配价：“工作”需要表示处所的状语，“星期”是时间词，不能充当工作的地点。"}], "explanations": {"境外": "正确：境外指国境以外，“在境外工作”即在国外工作。", "钢琴": "语义：钢琴是乐器，不是工作的地点，“在钢琴工作”说不通。", "窗户": "语义：窗户是建筑的部件，不能作为工作的地点。", "星期": "配价：“工作”需要表示处所的状语，“星期”是时间词，不能充当工作的地点。"}, "sentence_index": 0, "correct_answer": "境外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下个月去境外出差，地点就在国内的深圳。", "explanation": "这里应该用〈外地〉。境外指国境以外，深圳在国内，国内其他地方应说外地。"}, {"text": "我家在境外，就在北京的一个小村子里，离市中心很远。", "explanation": "这里应该用〈郊区〉。境外指国境以外，北京的村子在国内，不能说境外。"}, {"text": "我们在城市境外建了一座新工厂。", "explanation": "这里应该用〈郊区〉。境外指国境以外，城市周围仍在国内，不能说境外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95043, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "境外", "is_correct": true, "explanation": "正确：境外指国境以外，即国家边界的外面。"}, {"text": "敬拜", "is_correct": false, "explanation": "bài 与 wài 声母不同（b/w），敬拜指恭敬地拜见或祭拜，与境外意思不同。"}, {"text": "静待", "is_correct": false, "explanation": "dài 与 wài 声母不同（d/w），静待指安静地等待，与境外意思不同。"}, {"text": "净菜", "is_correct": false, "explanation": "cài 与 wài 声母不同（c/w），净菜指洗净切好的蔬菜，与境外意思不同。"}], "explanations": {"境外": "正确：境外指国境以外，即国家边界的外面。", "敬拜": "bài 与 wài 声母不同（b/w），敬拜指恭敬地拜见或祭拜，与境外意思不同。", "静待": "dài 与 wài 声母不同（d/w），静待指安静地等待，与境外意思不同。", "净菜": "cài 与 wài 声母不同（c/w），净菜指洗净切好的蔬菜，与境外意思不同。"}, "sentence_index": null, "correct_answer": "境外"}, "level_3": {"options": [{"text": "境外", "is_correct": true, "explanation": "正确：境外指国境以外，“去境外旅行”即去国外旅行，需要护照。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的房间，不是可以去旅行的地方。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能作为旅行的目的地。"}, {"text": "手机", "is_correct": false, "explanation": "配价：“旅行”需要表示地点的成分，“手机”不能充当旅行的目的地。"}], "explanations": {"境外": "正确：境外指国境以外，“去境外旅行”即去国外旅行，需要护照。", "厨房": "语义：厨房是做饭的房间，不是可以去旅行的地方。", "桌子": "语义：桌子是家具，不能作为旅行的目的地。", "手机": "配价：“旅行”需要表示地点的成分，“手机”不能充当旅行的目的地。"}, "sentence_index": 6, "correct_answer": "境外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去境外看病了，就在邻省的省会，离这里很近。", "explanation": "这里应该用〈外省〉。境外指国境以外，邻省在国内，不能说境外。"}, {"text": "他从县里去境外看病了，就在我们省城的医院。", "explanation": "这里应该用〈外地〉。境外指国境以外，省城在国内，从县里去省城应说外地。"}, {"text": "他下午去境外看病了，医院就在北京的西城区。", "explanation": "这里应该用〈市区〉。境外指国境以外，北京的西城区在国内，不能说境外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐从境外读书，已经两年了。", "corrected_sentence": "我姐姐在境外读书，已经两年了。", "error_description": "错误：表示处所要用“在”，不能用“从”。“从”表示起点，“从境外读书”说不通，正确说法是“在境外读书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我朋友境外寄来了一份礼物。", "corrected_sentence": "我朋友从境外寄来了一份礼物。", "error_description": "错误：表示来源的“从”漏掉了。正确说法是“从境外寄来”，“从+处所”要引出动作的起点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
