INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某一范围周围的部分；最外面一层。", "primary_collocate": null, "pronunciation": "wài wéi", "ipa": "waɪ˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这个问题先从外围了解。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司外围的工作由我来做。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先看外围的情况。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是队员，只是球队外围的朋友。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外围的人不知道里面的事。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查先从外围开始。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在公司的外围工作，很少知道大事。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些人只是这个组织的外围成员。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外围的消息常常不太准确。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只在比赛外围帮忙。", "target_word": "外围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外围赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "外围：某一范围周围的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8a6e1b4-4957-4aa2-bef8-2e14d4c5083b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外围", "is_correct": true, "explanation": "正确：外围指某一范围周围的部分，“从外围了解”指从周边的情况入手了解。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是了解问题的途径，“从钢琴了解”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能作为了解问题的途径，“从窗户了解”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“了解”需要表示途径或方面的成分，“厨房”是空间，不能充当。"}], "explanations": {"外围": "正确：外围指某一范围周围的部分，“从外围了解”指从周边的情况入手了解。", "钢琴": "语义：钢琴不是了解问题的途径，“从钢琴了解”说不通。", "窗户": "语义：窗户不能作为了解问题的途径，“从窗户了解”说不通。", "厨房": "配价：“了解”需要表示途径或方面的成分，“厨房”是空间，不能充当。"}, "sentence_index": 0, "correct_answer": "外围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是球队的队长，是球队外围最重要的人。", "explanation": "这里应该用〈核心〉。队长是球队最重要的人，不能说在外围。"}, {"text": "这件事是公司外围的秘密，只有老板知道。", "explanation": "这里应该用〈内部〉。只有老板知道的事属于公司内部，不能说外围。"}, {"text": "他天天和队员一起比赛，是球队外围的主力。", "explanation": "这里应该用〈核心〉。主力队员在球队中心位置，不能说外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外围", "is_correct": true, "explanation": "正确：外围指某一范围周围的部分，“在公司的外围工作”指做公司边缘、不核心的工作。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，“在公司的鸡蛋工作”说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室的设备，不能表示公司里的某个部分。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”是时间词，不能作“公司的……”表示工作的范围。"}], "explanations": {"外围": "正确：外围指某一范围周围的部分，“在公司的外围工作”指做公司边缘、不核心的工作。", "鸡蛋": "语义：鸡蛋是食物，“在公司的鸡蛋工作”说不通。", "黑板": "语义：黑板是教室的设备，不能表示公司里的某个部分。", "星期": "搭配：“星期”是时间词，不能作“公司的……”表示工作的范围。"}, "sentence_index": 6, "correct_answer": "外围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这场比赛的主角，一直在比赛外围表演。", "explanation": "这里应该用〈中心〉。主角是比赛的中心人物，不能说在外围。"}, {"text": "这次比赛最重要的决定都由外围的人来做。", "explanation": "这里应该用〈核心〉。做最重要决定的人是核心的人，不能说外围。"}, {"text": "他上场踢满了全场，是比赛外围的球员。", "explanation": "这里应该用〈场上〉。踢满全场的球员在场上比赛，不能说在外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只外围帮忙，不参加正式比赛。", "corrected_sentence": "我只在外围帮忙，不参加正式比赛。", "error_description": "错误：表示处所的“在”漏掉了。正确说法是“在外围帮忙”，“在+处所”要放在动词前面，引出动作发生的处所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们外围开始调查这件事。", "corrected_sentence": "我们从外围开始调查这件事。", "error_description": "错误：表示起点的“从”漏掉了。正确说法是“从外围开始调查”，“从+处所”要引出起点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e402e0-dd95-4f05-86c6-0c1f5bc6d908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
