INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95047, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大副是船上仅次于船长的人。", "primary_collocate": null, "pronunciation": "dà fù", "ipa": "ta˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "大副是船上仅次于船长的人。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我舅舅在海上的大船上当大副。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大副站在船头，看着前面的海。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长睡觉的时候，大副看着船。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大副会说三种语言。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大副让我们把行李放在船里。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大副和船长一起看地图。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想先做大副，再做船长。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大副每天都很早起床检查船。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们船上的大副为人很好。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位大副", "label": "量词搭配"}, {"form": "一名大副", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "船上地位排在船长后面的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95047, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "答复", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）第一音节声调不同，意思是回答、回复。"}, {"text": "大幅", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）第二音节声调不同，意思是幅度大。"}, {"text": "大副", "is_correct": true, "explanation": "大副：船上地位排在船长后面的人。"}, {"text": "大斧", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）第二音节声调不同，意思是大号的斧子。"}, {"text": "大步", "is_correct": false, "explanation": "bù 与 fù 声母不同（b 与 f），意思是迈开的大步子。"}, {"text": "大户", "is_correct": false, "explanation": "hù 与 fù 声母不同（h 与 f），意思是大户人家或大客户。"}], "explanations": {"答复": "dá（第二声）与 dà（第四声）第一音节声调不同，意思是回答、回复。", "大幅": "fú（第二声）与 fù（第四声）第二音节声调不同，意思是幅度大。", "大副": "大副：船上地位排在船长后面的人。", "大斧": "fǔ（第三声）与 fù（第四声）第二音节声调不同，意思是大号的斧子。", "大步": "bù 与 fù 声母不同（b 与 f），意思是迈开的大步子。", "大户": "hù 与 fù 声母不同（h 与 f），意思是大户人家或大客户。"}, "sentence_index": null, "correct_answer": "大副"}, "level_3": {"options": [{"text": "大副", "is_correct": true, "explanation": "正确：“是……的人”后接船上的职位，大副符合句意。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客并不排在船长之后，不能说“仅次于船长的人”。"}, {"text": "船舱", "is_correct": false, "explanation": "搭配：“是……的人”要求指人的名词，“船舱”是地方，不能这样用。"}, {"text": "水手", "is_correct": false, "explanation": "语义：水手的职位远低于船长，不符合“仅次于船长”。"}], "explanations": {"大副": "正确：“是……的人”后接船上的职位，大副符合句意。", "乘客": "语义：乘客并不排在船长之后，不能说“仅次于船长的人”。", "船舱": "搭配：“是……的人”要求指人的名词，“船舱”是地方，不能这样用。", "水手": "语义：水手的职位远低于船长，不符合“仅次于船长”。"}, "sentence_index": 0, "correct_answer": "大副"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大副每天早上都要检查各个班级。", "explanation": "这里应该用〈校长〉。大副是船上的职务，不能用于学校的管理工作。"}, {"text": "大副在医院里给病人看病。", "explanation": "这里应该用〈医生〉。大副是船上的职务，不能指医院里看病的人。"}, {"text": "大副负责整理公司的文件。", "explanation": "这里应该用〈秘书〉。大副是船上的高级船员，不能用于公司的文书工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大副", "is_correct": true, "explanation": "正确：“大副和船长一起看地图”，大副是能看地图的人。"}, {"text": "船长", "is_correct": false, "explanation": "语义：句中已有“船长”，“船长和船长一起看地图”重复且不合逻辑。"}, {"text": "地图", "is_correct": false, "explanation": "配价：“看”的施事要求是人，地图不能看地图。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“看地图”的主语要是人，桌子不能看地图。"}], "explanations": {"大副": "正确：“大副和船长一起看地图”，大副是能看地图的人。", "船长": "语义：句中已有“船长”，“船长和船长一起看地图”重复且不合逻辑。", "地图": "配价：“看”的施事要求是人，地图不能看地图。", "桌子": "配价：“看地图”的主语要是人，桌子不能看地图。"}, "sentence_index": 6, "correct_answer": "大副"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大副每天都要检查生产线。", "explanation": "这里应该用〈厂长〉。大副是船上的职务，不能用于工厂的管理。"}, {"text": "大副负责训练球队的队员。", "explanation": "这里应该用〈教练〉。大副是船上的职务，不能用于体育训练。"}, {"text": "大副在前线指挥部队。", "explanation": "这里应该用〈司令〉。大副是船上的职务，不能用于陆地部队的指挥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船上新来了一块大副。", "corrected_sentence": "船上新来了一名大副。", "error_description": "量词错误：“大副”指人，应用“名”或“位”；“块”用于块状的东西。正确说法是“一名大副”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前当了过大副。", "corrected_sentence": "他以前当过大副。", "error_description": "体标错误：“过”表示经历，不能与“了”连用。正确说法是“当过大副”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
