INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "船舶上职位仅次于船长的高级船员。", "primary_collocate": null, "pronunciation": "dà fù", "ipa": "ta˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "大副的职位仅次于船长。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长不在时，大副来管船。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在船上工作十年，现在是大副。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大副每天检查货物，保证船安全。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条船的大副是一位四十岁的男人。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，大副请大家都回到房间里。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从水手做起，后来当上了大副。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大副把今天的航线告诉了船长。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长生病了，大副接着开船。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大副对新来的水手很严格。", "target_word": "大副", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位大副", "label": "量词搭配"}, {"form": "一名大副", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "船上职位仅次于船长的高级船员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a063f3ad-a04f-4ab6-a8e5-9b13477be05e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "答复", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）第一音节声调不同，意思是回答、回复。"}, {"text": "大幅", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）第二音节声调不同，意思是幅度大。"}, {"text": "大副", "is_correct": true, "explanation": "大副：船上仅次于船长的高级船员。"}, {"text": "大斧", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）第二音节声调不同，意思是大号的斧子。"}, {"text": "大步", "is_correct": false, "explanation": "bù 与 fù 声母不同（b 与 f），意思是迈开的大步子。"}, {"text": "大户", "is_correct": false, "explanation": "hù 与 fù 声母不同（h 与 f），意思是大户人家或大客户。"}], "explanations": {"答复": "dá（第二声）与 dà（第四声）第一音节声调不同，意思是回答、回复。", "大幅": "fú（第二声）与 fù（第四声）第二音节声调不同，意思是幅度大。", "大副": "大副：船上仅次于船长的高级船员。", "大斧": "fǔ（第三声）与 fù（第四声）第二音节声调不同，意思是大号的斧子。", "大步": "bù 与 fù 声母不同（b 与 f），意思是迈开的大步子。", "大户": "hù 与 fù 声母不同（h 与 f），意思是大户人家或大客户。"}, "sentence_index": null, "correct_answer": "大副"}, "level_3": {"options": [{"text": "大副", "is_correct": true, "explanation": "正确：大副是船上仅次于船长的职位，可以作主语。"}, {"text": "船长", "is_correct": false, "explanation": "语义：船长本身就是最高职位，不能说“仅次于船长”。"}, {"text": "水手", "is_correct": false, "explanation": "语义：水手的职位远低于船长，与“仅次于船长”的语境不符。"}, {"text": "船舱", "is_correct": false, "explanation": "搭配：“职位”指人的职务，“船舱”是地方，不能说“船舱的职位”。"}], "explanations": {"大副": "正确：大副是船上仅次于船长的职位，可以作主语。", "船长": "语义：船长本身就是最高职位，不能说“仅次于船长”。", "水手": "语义：水手的职位远低于船长，与“仅次于船长”的语境不符。", "船舱": "搭配：“职位”指人的职务，“船舱”是地方，不能说“船舱的职位”。"}, "sentence_index": 0, "correct_answer": "大副"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在饭店后厨炒菜、洗碗，是这家饭店的大副。", "explanation": "这里应该用〈厨师〉。大副是船上的职务，饭店后厨的工作不能用大副来称呼。"}, {"text": "他是经理的大副，负责处理日常事务。", "explanation": "这里应该用〈副手〉。大副专指船上仅次于船长的高级船员，不能用于公司等场合。"}, {"text": "大副在火车上检查乘客的车票。", "explanation": "这里应该用〈列车员〉。大副是船上的职务，不能用于火车上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大副", "is_correct": true, "explanation": "正确：“当上了大副”表示晋升到船上的高级船员职位。"}, {"text": "水手", "is_correct": false, "explanation": "语义：前文已说“从水手做起”，再说“后来当上了水手”，与晋升的语境相矛盾。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“当上了”要接职务，乘客不是职务。"}, {"text": "码头", "is_correct": false, "explanation": "搭配：“当上了”要接人的职务，码头是地方，不能用于此处。"}], "explanations": {"大副": "正确：“当上了大副”表示晋升到船上的高级船员职位。", "水手": "语义：前文已说“从水手做起”，再说“后来当上了水手”，与晋升的语境相矛盾。", "乘客": "搭配：“当上了”要接职务，乘客不是职务。", "码头": "搭配：“当上了”要接人的职务，码头是地方，不能用于此处。"}, "sentence_index": 6, "correct_answer": "大副"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工厂车间里当上了大副。", "explanation": "这里应该用〈车间主任〉。大副是船上的职务，工厂里不用这个称呼。"}, {"text": "大副在教室里管纪律。", "explanation": "这里应该用〈班长〉。大副只用于船上，不能用于学校班级管理。"}, {"text": "大副带领队员们训练。", "explanation": "这里应该用〈队长〉。大副是船上的职务，不能用来指球队或训练队伍的领队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船上新来了一条大副，大家都很尊敬他。", "corrected_sentence": "船上新来了一名大副，大家都很尊敬他。", "error_description": "量词错误：“大副”指人，应用“名”或“位”；“条”用于细长的东西。正确说法是“一名大副”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于当上着大副。", "corrected_sentence": "他终于当上了大副。", "error_description": "体标错误：“当上”表示已经完成，应用“了”，“着”表示持续，“当上着大副”不成立。正确说法是“当上了大副”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06060590-5687-4e57-b638-b1accfcf700d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
