INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95049, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "娶是男人和女人结婚，把她接到家里。", "primary_collocate": null, "pronunciation": "qǔ", "ipa": "tɕʰy˨˩˦", "syllable_count": 1, "sentences": [{"text": "他用马车把新娘娶回了家。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着马，去娶新娘回家。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷是在二十岁那年娶奶奶的。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都来看他娶新娘。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他攒了钱，要把她风风光光地娶进门。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把她娶回家以后，两个人过得很幸福。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李娶了邻村的姑娘，全家都很高兴。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前娶媳妇要请很多客人吃饭。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在春天娶了媳妇，秋天就有了孩子。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟还没娶妻，妈妈很着急。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "娶了", "label": "体标"}, {"form": "娶过", "label": "体标"}, {"form": "娶亲", "label": "复合"}], "register": "中性", "sense_fingerprint": "男人结婚，把女人接到家里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95049, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "娶", "is_correct": true, "explanation": "正确：娶 qǔ（第三声），指男方迎娶新娘，把她接到家里。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，意思是“离开、前往”。"}, {"text": "区", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是“区域”。"}, {"text": "渠", "is_correct": false, "explanation": "qú（第二声）与 qǔ（第三声）声调不同，意思是“水渠”。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，意思是“趣味”。"}], "explanations": {"娶": "正确：娶 qǔ（第三声），指男方迎娶新娘，把她接到家里。", "去": "qù（第四声）与 qǔ（第三声）声调不同，意思是“离开、前往”。", "区": "qū（第一声）与 qǔ（第三声）声调不同，意思是“区域”。", "渠": "qú（第二声）与 qǔ（第三声）声调不同，意思是“水渠”。", "趣": "qù（第四声）与 qǔ（第三声）声调不同，意思是“趣味”。"}, "sentence_index": null, "correct_answer": "娶"}, "level_3": {"options": [{"text": "娶", "is_correct": true, "explanation": "正确：“娶回了家”指男方把新娘接回家，与“用马车把新娘”搭配。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”用于搬运东西，不能用来搬运人。"}, {"text": "嫁", "is_correct": false, "explanation": "语义：“嫁”只用于女子出嫁，句中是男方把新娘接回家，不能用“嫁”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与“用马车把新娘接回家”的意思相反。"}], "explanations": {"娶": "正确：“娶回了家”指男方把新娘接回家，与“用马车把新娘”搭配。", "搬": "搭配：“搬”用于搬运东西，不能用来搬运人。", "嫁": "语义：“嫁”只用于女子出嫁，句中是男方把新娘接回家，不能用“嫁”。", "扔": "语义：“扔”指丢弃，与“用马车把新娘接回家”的意思相反。"}, "sentence_index": 0, "correct_answer": "娶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新娘娶了邻村的小伙子，大家都去祝贺。", "explanation": "这里应该用〈嫁〉。嫁指女子结婚，新娘是女方，应说“嫁给”；“娶”只用于男方结婚。"}, {"text": "他娶朋友来家里吃饭，大家都很开心。", "explanation": "这里应该用〈请〉。“请”指邀请客人来做客；“娶”指男子与女子结婚，不能用于邀请朋友。"}, {"text": "他娶了一套房子，搬进去住了。", "explanation": "这里应该用〈买〉。花钱得到房子要用〈买〉；“娶”的对象只能是人（妻子），不能用于房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95049, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "娶", "is_correct": true, "explanation": "正确：娶 qǔ（第三声），指男方迎娶新娘，把她接到家里。"}, {"text": "屈", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是“弯曲、屈服”。"}, {"text": "驱", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是“赶走、驱赶”。"}, {"text": "躯", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是“身体”，如“身躯”。"}], "explanations": {"娶": "正确：娶 qǔ（第三声），指男方迎娶新娘，把她接到家里。", "屈": "qū（第一声）与 qǔ（第三声）声调不同，意思是“弯曲、屈服”。", "驱": "qū（第一声）与 qǔ（第三声）声调不同，意思是“赶走、驱赶”。", "躯": "qū（第一声）与 qǔ（第三声）声调不同，意思是“身体”，如“身躯”。"}, "sentence_index": null, "correct_answer": "娶"}, "level_3": {"options": [{"text": "娶", "is_correct": true, "explanation": "正确：“娶了邻村的姑娘”指男方结婚，与后句“全家都很高兴”的喜悦相符。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责备，与后句“全家都很高兴”的情绪矛盾。"}, {"text": "惹", "is_correct": false, "explanation": "语义：“惹”指招惹、得罪，与“全家都很高兴”的意思不合。"}, {"text": "啃", "is_correct": false, "explanation": "搭配：“啃”指用牙咬食物，不能用来说“啃姑娘”。"}], "explanations": {"娶": "正确：“娶了邻村的姑娘”指男方结婚，与后句“全家都很高兴”的喜悦相符。", "骂": "语义：“骂”是责备，与后句“全家都很高兴”的情绪矛盾。", "惹": "语义：“惹”指招惹、得罪，与“全家都很高兴”的意思不合。", "啃": "搭配：“啃”指用牙咬食物，不能用来说“啃姑娘”。"}, "sentence_index": 6, "correct_answer": "娶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去机场娶客人，大家都在等。", "explanation": "这里应该用〈迎接〉。“迎接”指去接待客人；“娶”指结婚，不能用于去机场迎接客人。"}, {"text": "他娶孩子去公园。", "explanation": "这里应该用〈带〉。“带”指带领、陪同；“娶”只用于结婚，不能说“娶孩子去公园”。"}, {"text": "他去医院娶病人。", "explanation": "这里应该用〈看望〉。“看望”指探望病人；“娶”指结婚，不能用于去医院探望病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他娶了过妻子，现在一个人住。", "corrected_sentence": "他娶过妻子，现在一个人住。", "error_description": "体标错误：“了”和“过”不能同时表示经历，应说“娶过妻子”，不能在“过”前面加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于娶了到一个好媳妇。", "corrected_sentence": "他终于娶到了一个好媳妇。", "error_description": "补语错误：“到”是结果补语，“了”应放在“到”之后，应说“娶到了”，不能说“娶了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
