INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "男子与女子结婚。", "primary_collocate": null, "pronunciation": "qǔ", "ipa": "tɕʰy˨˩˦", "syllable_count": 1, "sentences": [{"text": "他想娶一个好女孩。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥去年娶了一个老师。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经娶了妻子，有一个孩子了。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了娶她，他努力工作了三年。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他娶过一次，后来离婚了。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张的儿子下个月要娶媳妇。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，男人要先有房子才能娶妻。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他一定要娶她。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打算什么时候娶她回家？", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想娶的人不是她，是她的姐姐。", "target_word": "娶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "娶了", "label": "体标"}, {"form": "娶过", "label": "体标"}, {"form": "娶妻", "label": "复合"}], "register": "中性", "sense_fingerprint": "男子与女子结婚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95050, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "娶", "is_correct": true, "explanation": "正确：娶 qǔ（第三声），指男子与女子结婚。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，意思是“离开、前往”。"}, {"text": "区", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是“区域”。"}, {"text": "驱", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是“驱赶”。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，意思是“趣味”。"}], "explanations": {"娶": "正确：娶 qǔ（第三声），指男子与女子结婚。", "去": "qù（第四声）与 qǔ（第三声）声调不同，意思是“离开、前往”。", "区": "qū（第一声）与 qǔ（第三声）声调不同，意思是“区域”。", "驱": "qū（第一声）与 qǔ（第三声）声调不同，意思是“驱赶”。", "趣": "qù（第四声）与 qǔ（第三声）声调不同，意思是“趣味”。"}, "sentence_index": null, "correct_answer": "娶"}, "level_3": {"options": [{"text": "娶", "is_correct": true, "explanation": "正确：“娶”指男子结婚，与“一个好女孩”搭配，句意是男子想结婚。"}, {"text": "嫁", "is_correct": false, "explanation": "语义：“嫁”只用于女子出嫁，句中主语是男子，不能用。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是字、文章等，不能说“写一个好女孩”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是水、茶等液体，不能说“喝一个好女孩”。"}], "explanations": {"娶": "正确：“娶”指男子结婚，与“一个好女孩”搭配，句意是男子想结婚。", "嫁": "语义：“嫁”只用于女子出嫁，句中主语是男子，不能用。", "写": "搭配：“写”的对象是字、文章等，不能说“写一个好女孩”。", "喝": "语义：“喝”的对象是水、茶等液体，不能说“喝一个好女孩”。"}, "sentence_index": 0, "correct_answer": "娶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她娶了一个医生，两个人很幸福。", "explanation": "这里应该用〈嫁〉。嫁指女子结婚；“娶”指男子结婚，句中的“她”是女子，不能用“娶”。"}, {"text": "他娶得了好成绩，老师很满意。", "explanation": "这里应该用〈取〉（qǔ）。“取得”表示获得，如取得好成绩；“娶”只用于结婚，不能用于成绩。"}, {"text": "他娶了一台电脑，每天用它上网。", "explanation": "宾语搭配：这里应该用〈买〉。“娶”的对象是人（妻子），不能用于电脑；买电脑要用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95050, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "娶", "is_correct": true, "explanation": "正确：娶 qǔ（第三声），指男子与女子结婚。"}, {"text": "屈", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是“弯曲、屈服”。"}, {"text": "躯", "is_correct": false, "explanation": "qū（第一声）与 qǔ（第三声）声调不同，意思是“身体”。"}, {"text": "渠", "is_correct": false, "explanation": "qú（第二声）与 qǔ（第三声）声调不同，意思是“水渠”。"}], "explanations": {"娶": "正确：娶 qǔ（第三声），指男子与女子结婚。", "屈": "qū（第一声）与 qǔ（第三声）声调不同，意思是“弯曲、屈服”。", "躯": "qū（第一声）与 qǔ（第三声）声调不同，意思是“身体”。", "渠": "qú（第二声）与 qǔ（第三声）声调不同，意思是“水渠”。"}, "sentence_index": null, "correct_answer": "娶"}, "level_3": {"options": [{"text": "娶", "is_correct": true, "explanation": "正确：“娶妻”指男子结婚，“男人要先有房子才能娶妻”说明结婚前的条件。"}, {"text": "盖", "is_correct": false, "explanation": "搭配：“盖”多用于房屋，不能说“盖妻”。"}, {"text": "赚", "is_correct": false, "explanation": "语义：“赚”指挣钱，句中说的是结婚，与“妻”不符。"}, {"text": "请", "is_correct": false, "explanation": "搭配：“请”用于邀请、请求，不能说“请妻”。"}], "explanations": {"娶": "正确：“娶妻”指男子结婚，“男人要先有房子才能娶妻”说明结婚前的条件。", "盖": "搭配：“盖”多用于房屋，不能说“盖妻”。", "赚": "语义：“赚”指挣钱，句中说的是结婚，与“妻”不符。", "请": "搭配：“请”用于邀请、请求，不能说“请妻”。"}, "sentence_index": 6, "correct_answer": "娶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去车站娶客人。", "explanation": "这里应该用〈接〉。“接”指去迎接人；“娶”指结婚，不能用于去车站接客人。"}, {"text": "他娶妈妈去医院。", "explanation": "这里应该用〈陪〉。“陪”指陪伴；“娶”只用于结婚，不能说“娶妈妈去医院”。"}, {"text": "他娶同事吃饭。", "explanation": "这里应该用〈请〉。“请”指邀请、招待；“娶”指结婚，不能用于请同事吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥去年娶着一个好女孩。", "corrected_sentence": "我哥哥去年娶了一个好女孩。", "error_description": "体标错误：“去年”指已完成的过去时间，“娶”是一次完成的动作，应用“了”，不能用表示持续状态的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于娶了到她。", "corrected_sentence": "他终于娶到了她。", "error_description": "补语错误：“到”是结果补语，“了”应放在“到”之后，应说“娶到了她”，不能说“娶了到她”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95051, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "正确：“热闹”与“孤独”构成反义，一个指人多有生气，一个指无人作伴。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”与“孤独”没有反义关系，它描述光线。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”与“孤独”没有反义关系，它描述内容或经验。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”与“孤独”没有反义关系，它描述速度。"}], "correct_answer": "热闹", "explanations": {"热闹": "正确：“热闹”与“孤独”构成反义，一个指人多有生气，一个指无人作伴。", "明亮": "“明亮”与“孤独”没有反义关系，它描述光线。", "丰富": "“丰富”与“孤独”没有反义关系，它描述内容或经验。", "迅速": "“迅速”与“孤独”没有反义关系，它描述速度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
