INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "岭是山上连起来的高高的一道。", "primary_collocate": null, "pronunciation": "lǐng", "ipa": "liŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我们翻过这道岭，就到村子了。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那道岭很高，岭上有很多树。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口气爬上了岭。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岭上的风很大，我们都很冷。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道岭的那边是一条小河。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，岭上开满了红花。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了三个小时，我们才走过那道岭。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天都背着柴上岭。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从岭上往下看，村子特别小。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路绕着岭，一直通到山后面。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道岭", "label": "量词"}], "register": "中性", "sense_fingerprint": "山上连起来的高高的一道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95057, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "岭", "is_correct": true, "explanation": "正确：岭是山上连起来的高高的一道，读 lǐng。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 lǐng（第三声）声调不同，意思是零。"}, {"text": "另", "is_correct": false, "explanation": "lìng（第四声）与 lǐng（第三声）声调不同，意思是另外。"}, {"text": "拧", "is_correct": false, "explanation": "nǐng 与 lǐng 声母不同（n 与 l），意思是拧。"}], "explanations": {"岭": "正确：岭是山上连起来的高高的一道，读 lǐng。", "零": "líng（第二声）与 lǐng（第三声）声调不同，意思是零。", "另": "lìng（第四声）与 lǐng（第三声）声调不同，意思是另外。", "拧": "nǐng 与 lǐng 声母不同（n 与 l），意思是拧。"}, "sentence_index": null, "correct_answer": "岭"}, "level_3": {"options": [{"text": "岭", "is_correct": true, "explanation": "岭：山上连起来的高高的一道，可以翻过去。"}, {"text": "河", "is_correct": false, "explanation": "搭配：“翻过”用于能翻越的山、墙等，河不能说“翻过”。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不是可以翻越的地形，不能翻过。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟没有形体可供翻越，不能翻过。"}], "explanations": {"岭": "岭：山上连起来的高高的一道，可以翻过去。", "河": "搭配：“翻过”用于能翻越的山、墙等，河不能说“翻过”。", "水": "语义：水不是可以翻越的地形，不能翻过。", "烟": "语义：烟没有形体可供翻越，不能翻过。"}, "sentence_index": 0, "correct_answer": "岭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道岭的水很急，船不能过去。", "explanation": "这里应该用〈河〉。岭是山脊地形，没有水流，不能说“岭的水很急”。"}, {"text": "他每天坐岭去上班。", "explanation": "这里应该用〈车〉。岭是山上的地形，不能坐着去上班；上班可以坐车。"}, {"text": "他把岭背回了家。", "explanation": "这里应该用〈柴火〉。岭是山脊地形，不能背走；能背回家的是柴火等可以搬运的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95057, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "岭", "is_correct": true, "explanation": "正确：岭是山上连起来的高高的一道，读 lǐng。"}, {"text": "龄", "is_correct": false, "explanation": "líng（第二声）与 lǐng（第三声）声调不同，意思是年龄。"}, {"text": "令", "is_correct": false, "explanation": "lìng（第四声）与 lǐng（第三声）声调不同，意思是命令。"}, {"text": "冷", "is_correct": false, "explanation": "lěng 与 lǐng 韵母不同（e 与 i），意思是冷。"}], "explanations": {"岭": "正确：岭是山上连起来的高高的一道，读 lǐng。", "龄": "líng（第二声）与 lǐng（第三声）声调不同，意思是年龄。", "令": "lìng（第四声）与 lǐng（第三声）声调不同，意思是命令。", "冷": "lěng 与 lǐng 韵母不同（e 与 i），意思是冷。"}, "sentence_index": null, "correct_answer": "岭"}, "level_3": {"options": [{"text": "岭", "is_correct": true, "explanation": "岭：山上连起来的高高的一道，可以走过去。"}, {"text": "题", "is_correct": false, "explanation": "语义：“题”是问题，不能用脚走过。"}, {"text": "汤", "is_correct": false, "explanation": "语义：“汤”是液体，不能被走过。"}, {"text": "菜", "is_correct": false, "explanation": "语义：“菜”是食物，不能被走过。"}], "explanations": {"岭": "岭：山上连起来的高高的一道，可以走过去。", "题": "语义：“题”是问题，不能用脚走过。", "汤": "语义：“汤”是液体，不能被走过。", "菜": "语义：“菜”是食物，不能被走过。"}, "sentence_index": 6, "correct_answer": "岭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们走过了一只岭，就到村子了。", "explanation": "这里应该用〈道〉。岭的量词是“道”，“只”用于动物和成对的东西，不用于岭。"}, {"text": "我们在岭上钓鱼，一个下午钓了很多鱼。", "explanation": "这里应该用〈湖〉。岭是山脊地形，没有水，不能钓鱼；钓鱼要在湖、河里。"}, {"text": "他用手把岭推开了。", "explanation": "这里应该用〈门〉。岭是大片地形，不能像门一样推开；能推开的是门、窗等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在那个岭上休息了一只小时。", "corrected_sentence": "我们在那个岭上休息了一个小时。", "error_description": "量词错误：“小时”用量词“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们爬上了那只岭。", "corrected_sentence": "他们爬上了那道岭。", "error_description": "量词错误：岭应使用量词“道”。“只”不能用于岭，应说“那道岭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
