INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山脉；也指山路的顶部。", "primary_collocate": null, "pronunciation": "lǐng", "ipa": "liŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "车开到岭上，我们下来休息了。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了这个岭，路就好走了。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的岭连成一片，像一条龙。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬到岭上，我们看到了大海。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪以后，岭上的路很难走。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条岭很长，走了一天还没走完。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在岭上等了我们很久。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家走到岭上，都累得不想说话了。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岭那边的天气和这边不一样。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳慢慢落到岭后面去了。", "target_word": "岭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道岭", "label": "量词"}], "register": "中性", "sense_fingerprint": "山脉；山路的顶部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41024f7d-36b6-483a-ad15-703ba6911c57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "岭", "is_correct": true, "explanation": "正确：岭指山脉或山路的顶部，读 lǐng。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 lǐng（第三声）声调不同，意思是零。"}, {"text": "另", "is_correct": false, "explanation": "lìng（第四声）与 lǐng（第三声）声调不同，意思是另外。"}, {"text": "拧", "is_correct": false, "explanation": "nǐng 与 lǐng 声母不同（n 与 l），意思是拧。"}], "explanations": {"岭": "正确：岭指山脉或山路的顶部，读 lǐng。", "零": "líng（第二声）与 lǐng（第三声）声调不同，意思是零。", "另": "lìng（第四声）与 lǐng（第三声）声调不同，意思是另外。", "拧": "nǐng 与 lǐng 声母不同（n 与 l），意思是拧。"}, "sentence_index": null, "correct_answer": "岭"}, "level_3": {"options": [{"text": "岭", "is_correct": true, "explanation": "岭：山脉或山路的顶部，车可以开到岭上。"}, {"text": "云", "is_correct": false, "explanation": "语义：云不是可以让车开上去的地面，车不能开到云上。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“开到……上”要求车能行驶的地面，墙是竖直的，车不能开到墙上。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：车不能开到桌子上，桌子不是可以行驶的地面。"}], "explanations": {"岭": "岭：山脉或山路的顶部，车可以开到岭上。", "云": "语义：云不是可以让车开上去的地面，车不能开到云上。", "墙": "搭配：“开到……上”要求车能行驶的地面，墙是竖直的，车不能开到墙上。", "桌子": "语义：车不能开到桌子上，桌子不是可以行驶的地面。"}, "sentence_index": 0, "correct_answer": "岭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们爬到一位岭上，看见了大海。", "explanation": "这里应该用〈道〉。“位”用于人，岭应使用量词“道”。"}, {"text": "他们在岭里游泳，游了一天。", "explanation": "这里应该用〈湖〉。岭是山脊地形，不能游泳；游泳要在湖、河、海里。"}, {"text": "他把岭装进了口袋。", "explanation": "这里应该用〈糖〉。岭是大片地形，不能装进口袋；能装进口袋的是糖、石子等小东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95058, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "岭", "is_correct": true, "explanation": "正确：岭指山脉或山路的顶部，读 lǐng。"}, {"text": "龄", "is_correct": false, "explanation": "líng（第二声）与 lǐng（第三声）声调不同，意思是年龄。"}, {"text": "令", "is_correct": false, "explanation": "lìng（第四声）与 lǐng（第三声）声调不同，意思是命令。"}, {"text": "冷", "is_correct": false, "explanation": "lěng 与 lǐng 韵母不同（e 与 i），意思是冷。"}], "explanations": {"岭": "正确：岭指山脉或山路的顶部，读 lǐng。", "龄": "líng（第二声）与 lǐng（第三声）声调不同，意思是年龄。", "令": "lìng（第四声）与 lǐng（第三声）声调不同，意思是命令。", "冷": "lěng 与 lǐng 韵母不同（e 与 i），意思是冷。"}, "sentence_index": null, "correct_answer": "岭"}, "level_3": {"options": [{"text": "岭", "is_correct": true, "explanation": "岭：山脉或山路的顶部，人可以站在岭上等待。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以站或坐着等人的地方。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以站或坐着等人的平面。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“在……上等人”要求有可站或可坐的平面，天空不是。"}], "explanations": {"岭": "岭：山脉或山路的顶部，人可以站在岭上等待。", "冰箱": "语义：冰箱不是可以站或坐着等人的地方。", "窗户": "语义：窗户不是可以站或坐着等人的平面。", "天空": "搭配：“在……上等人”要求有可站或可坐的平面，天空不是。"}, "sentence_index": 6, "correct_answer": "岭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "远处有一只岭，很高。", "explanation": "这里应该用〈道〉。岭用量词“道”，“只”用于动物和成对的东西。"}, {"text": "我们走进岭，屋里很暖和。", "explanation": "这里应该用〈房子〉。岭是山脉地形，不是房屋，没有屋里可言；“屋里”指房屋内部。"}, {"text": "他喝了一口岭。", "explanation": "这里应该用〈水〉。岭是地形，不能喝；能喝的应是水、茶等液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4684b3b6-e430-4c45-bc90-7ec08d4eeea5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
