INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95060, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "经常使用的。", "primary_collocate": null, "pronunciation": "cháng yòng", "ipa": "ʈʂʰɑŋ˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这是一个很常用的词。", "target_word": "常用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先学习这一百个常用汉字。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里常用的软件放在第一页。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们一张常用词表。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是家里常用的药。", "target_word": "常用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把常用的工具放在桌子上。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我常用的杯子。", "target_word": "常用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里常用的菜刀要定期磨。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多常用的句子。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把常用的文件放在一个文件夹里。", "target_word": "常用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "常用词", "label": "复合"}, {"form": "常用字", "label": "复合"}], "register": "中性", "sense_fingerprint": "常用：经常使用的，作定语修饰名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56189473-a491-472b-a780-7b2e60a5ec1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95060, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "常用", "is_correct": true, "explanation": "正确答案。常用：经常使用的。"}, {"text": "重用", "is_correct": false, "explanation": "chóng 与 cháng 韵母不同（ong 与 ang），意思是任用、提拔。"}, {"text": "长泳", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是长距离游泳。"}, {"text": "厂用", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂使用的，如厂用电。"}, {"text": "乘用", "is_correct": false, "explanation": "chéng 与 cháng 韵母不同（eng 与 ang），意思是供乘坐用的，如乘用车。"}], "explanations": {"常用": "正确答案。常用：经常使用的。", "重用": "chóng 与 cháng 韵母不同（ong 与 ang），意思是任用、提拔。", "长泳": "yǒng（第三声）与 yòng（第四声）声调不同，意思是长距离游泳。", "厂用": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂使用的，如厂用电。", "乘用": "chéng 与 cháng 韵母不同（eng 与 ang），意思是供乘坐用的，如乘用车。"}, "sentence_index": null, "correct_answer": "常用"}, "level_3": {"options": [{"text": "常用", "is_correct": true, "explanation": "正确。“常用”修饰“词”，表示经常使用的。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说形状，词不能是圆的。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”说味道，词不能是咸的。"}, {"text": "陡", "is_correct": false, "explanation": "搭配：“陡”用于坡道等，不能说“陡的词”。"}], "explanations": {"常用": "正确。“常用”修饰“词”，表示经常使用的。", "圆": "语义：“圆”说形状，词不能是圆的。", "咸": "语义：“咸”说味道，词不能是咸的。", "陡": "搭配：“陡”用于坡道等，不能说“陡的词”。"}, "sentence_index": 0, "correct_answer": "常用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种鸟在南方很常用。", "explanation": "这里应该用〈常见〉。常用指东西被经常使用，不能用来说动物在某地多见；说多见要用常见。"}, {"text": "这个问题在全国很常用。", "explanation": "这里应该用〈普遍〉。常用说物品或词语被经常使用，问题在各地多次出现要用普遍。"}, {"text": "这是一个很常用的日子。", "explanation": "这里应该用〈平常〉。常用强调经常被使用，不能用来形容日子普通，形容普通要用平常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常用", "is_correct": true, "explanation": "正确。“常用”修饰“杯子”，表示经常使用的。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”说味道，杯子不能是辣的。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”说味道，杯子不能是苦的。"}, {"text": "哑", "is_correct": false, "explanation": "搭配：“哑”说声音，不能说哑杯子。"}], "explanations": {"常用": "正确。“常用”修饰“杯子”，表示经常使用的。", "辣": "语义：“辣”说味道，杯子不能是辣的。", "苦": "语义：“苦”说味道，杯子不能是苦的。", "哑": "搭配：“哑”说声音，不能说哑杯子。"}, "sentence_index": 6, "correct_answer": "常用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人很常用。", "explanation": "这里不能用〈常用〉，误把它当成“被人经常利用”的意思。常用只说物品或词语被经常使用，不用来形容人。"}, {"text": "这片云很常用。", "explanation": "这里不能用〈常用〉，误把它当成“时常出现”的意思。常用只说物品或词语被经常使用，云不能这样说。"}, {"text": "这阵风很常用。", "explanation": "这里不能用〈常用〉，误把它当成“时常刮起”的意思。常用只说物品或词语被经常使用，风不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很常用软件。", "corrected_sentence": "这是一个很常用的软件。", "error_description": "错误形式：“很常用软件”，应为“很常用的软件”。“很”修饰“常用”后，“常用”与后面的名词之间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
