INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95061, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "强", "is_correct": true, "explanation": "反义：“强”与“弱”相对，指身体力气大。"}, {"text": "快", "is_correct": false, "explanation": "无反义关系：“快”说速度，与“弱”不构成反义。"}, {"text": "圆", "is_correct": false, "explanation": "无反义关系：“圆”说形状，与“弱”不构成反义。"}, {"text": "轻", "is_correct": false, "explanation": "无反义关系：“轻”说重量，与“弱”不构成反义。"}], "correct_answer": "强", "explanations": {"强": "反义：“强”与“弱”相对，指身体力气大。", "快": "无反义关系：“快”说速度，与“弱”不构成反义。", "圆": "无反义关系：“圆”说形状，与“弱”不构成反义。", "轻": "无反义关系：“轻”说重量，与“弱”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
