INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95061, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "弱是力气小，不强壮。", "primary_collocate": null, "pronunciation": "ruò", "ipa": "ʐwo˥˩", "syllable_count": 1, "sentences": [{"text": "他身体很弱，爱生病。", "target_word": "弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这孩子小时候很弱。", "target_word": "弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈年纪大了，身体越来越弱。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的身体比哥哥弱。", "target_word": "弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他太弱了，搬不动这张桌子。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病以后，奶奶变得很弱。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫生下来很弱，要多照顾。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来弱，其实很有力气。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的腿弱，不能走远路。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人弱，别让他提重东西。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弱小", "label": "复合词"}, {"form": "弱点", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人的身体力气小，不强壮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95061, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弱", "is_correct": true, "explanation": "正确：弱 ruò，意思是力气小、不强壮。"}, {"text": "落", "is_correct": false, "explanation": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。"}, {"text": "做", "is_correct": false, "explanation": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是做事。"}, {"text": "诺", "is_correct": false, "explanation": "nuò（第四声）与 ruò 声母不同（n 与 r），意思是答应。"}, {"text": "错", "is_correct": false, "explanation": "cuò（第四声）与 ruò 声母不同（c 与 r），意思是错误。"}], "explanations": {"弱": "正确：弱 ruò，意思是力气小、不强壮。", "落": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。", "做": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是做事。", "诺": "nuò（第四声）与 ruò 声母不同（n 与 r），意思是答应。", "错": "cuò（第四声）与 ruò 声母不同（c 与 r），意思是错误。"}, "sentence_index": null, "correct_answer": "弱"}, "level_3": {"options": [{"text": "弱", "is_correct": true, "explanation": "正确：“弱”指身体力气小，与后句“爱生病”相符。"}, {"text": "强", "is_correct": false, "explanation": "语义：“强”表示身体结实，与后句“爱生病”矛盾。"}, {"text": "健壮", "is_correct": false, "explanation": "语义：“健壮”表示身体强壮，与后句“爱生病”矛盾。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：形容身体结实说“健壮”或“强壮”，不说身体“很硬”。"}], "explanations": {"弱": "正确：“弱”指身体力气小，与后句“爱生病”相符。", "强": "语义：“强”表示身体结实，与后句“爱生病”矛盾。", "健壮": "语义：“健壮”表示身体强壮，与后句“爱生病”矛盾。", "硬": "搭配：形容身体结实说“健壮”或“强壮”，不说身体“很硬”。"}, "sentence_index": 0, "correct_answer": "弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个仓库很弱，能放下一百辆车。", "explanation": "这里应该用〈大〉。描述空间大小用“大”，“弱”指力气小，不能用来形容仓库。"}, {"text": "他的个子很弱，比同班同学矮一头。", "explanation": "这里应该用〈小〉。描述个子用“小”或“矮”，“弱”指力气不够。"}, {"text": "这段路很弱，走了十分钟就到了。", "explanation": "这里应该用〈近〉。描述距离远近用“近”或“远”，“弱”指力气小，不能用来形容路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95061, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弱", "is_correct": true, "explanation": "正确：弱 ruò，意思是力气小、不强壮。"}, {"text": "作", "is_correct": false, "explanation": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是制作。"}, {"text": "座", "is_correct": false, "explanation": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是座位。"}, {"text": "硕", "is_correct": false, "explanation": "shuò（第四声）与 ruò 声母不同（sh 与 r），意思是大。"}], "explanations": {"弱": "正确：弱 ruò，意思是力气小、不强壮。", "作": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是制作。", "座": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是座位。", "硕": "shuò（第四声）与 ruò 声母不同（sh 与 r），意思是大。"}, "sentence_index": null, "correct_answer": "弱"}, "level_3": {"options": [{"text": "弱", "is_correct": true, "explanation": "正确：“弱”指刚出生的小猫力气小、需要照顾，与后句相符。"}, {"text": "大", "is_correct": false, "explanation": "语义：刚出生的小猫不会“很大”，与“生下来”矛盾。"}, {"text": "硬朗", "is_correct": false, "explanation": "搭配：“硬朗”多用于形容老人的身体，不说小猫。"}, {"text": "高", "is_correct": false, "explanation": "体貌：刚出生的小猫不说“很高”，身长不用“高”来形容。"}], "explanations": {"弱": "正确：“弱”指刚出生的小猫力气小、需要照顾，与后句相符。", "大": "语义：刚出生的小猫不会“很大”，与“生下来”矛盾。", "硬朗": "搭配：“硬朗”多用于形容老人的身体，不说小猫。", "高": "体貌：刚出生的小猫不说“很高”，身长不用“高”来形容。"}, "sentence_index": 6, "correct_answer": "弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体重很弱，走起路来很利索。", "explanation": "这里应该用〈轻〉。描述重量用“轻”，“弱”指力气小。"}, {"text": "这本书很弱，一共有五百页。", "explanation": "这里应该用〈厚〉。描述书的厚薄用“厚”，“弱”指力气小，不能用来形容书。"}, {"text": "这家店的房租很弱，每月只要三百块。", "explanation": "这里应该用〈便宜〉。描述价格高低用“便宜”或“贵”，“弱”指力气小，不能用来形容房租。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我奶奶年纪大了，身体弱很。", "corrected_sentence": "我奶奶年纪大了，身体弱得很。", "error_description": "“弱”后面的程度补语要用“得”：应说“弱得很”，不能说“弱很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生病以后，他的身体了弱很多。", "corrected_sentence": "生病以后，他的身体弱了很多。", "error_description": "“了”表示变化，要放在形容词“弱”之后，应说“弱了很多”，不能放在“弱”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
