INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95062, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "力量小、不强壮；与“强”相对。", "primary_collocate": null, "pronunciation": "ruò", "ipa": "ʐwo˥˩", "syllable_count": 1, "sentences": [{"text": "这支球队很弱，经常输球。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的力量太弱，打不开门。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的军队很弱。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很结实，我很弱。", "target_word": "弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手臂比你的弱。", "target_word": "弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小河的水流很弱，推不动船。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队前强后弱。", "target_word": "弱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的力量不强，也不太弱。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的风很弱，吹不动树叶。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起别人，我们这边的力量弱多了。", "target_word": "弱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弱小", "label": "复合词"}, {"form": "弱点", "label": "复合词"}], "register": "中性", "sense_fingerprint": "力量小、不强壮，与强相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411a526-522a-48ad-8c7c-56a20b15b9e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95062, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弱", "is_correct": true, "explanation": "正确：弱 ruò，意思是力量小、不强壮。"}, {"text": "落", "is_correct": false, "explanation": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。"}, {"text": "诺", "is_correct": false, "explanation": "nuò（第四声）与 ruò 声母不同（n 与 r），意思是答应。"}, {"text": "错", "is_correct": false, "explanation": "cuò（第四声）与 ruò 声母不同（c 与 r），意思是错误。"}], "explanations": {"弱": "正确：弱 ruò，意思是力量小、不强壮。", "落": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。", "诺": "nuò（第四声）与 ruò 声母不同（n 与 r），意思是答应。", "错": "cuò（第四声）与 ruò 声母不同（c 与 r），意思是错误。"}, "sentence_index": null, "correct_answer": "弱"}, "level_3": {"options": [{"text": "弱", "is_correct": true, "explanation": "正确：“弱”指力量小，与“经常输球”相符。"}, {"text": "强", "is_correct": false, "explanation": "语义：“强”指力量大，与“经常输球”矛盾。"}, {"text": "厉害", "is_correct": false, "explanation": "语义：“厉害”指能力强，与“经常输球”矛盾。"}, {"text": "赢", "is_correct": false, "explanation": "语法：“赢”是动词，不能受程度副词“很”修饰。"}], "explanations": {"弱": "正确：“弱”指力量小，与“经常输球”相符。", "强": "语义：“强”指力量大，与“经常输球”矛盾。", "厉害": "语义：“厉害”指能力强，与“经常输球”矛盾。", "赢": "语法：“赢”是动词，不能受程度副词“很”修饰。"}, "sentence_index": 0, "correct_answer": "弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的服务态度很弱。", "explanation": "这里应该用〈差〉。服务态度说好坏，用“差”；“弱”指力量小，不能用来形容服务态度。"}, {"text": "他的个子很弱，篮球打得很好。", "explanation": "这里应该用〈高〉。描述身高用“高”，“弱”指力气小。"}, {"text": "这件毛衣很弱，买一件要两千块。", "explanation": "这里应该用〈贵〉。描述价格高低用“贵”，“弱”指力量小，不能用来形容毛衣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95062, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弱", "is_correct": true, "explanation": "正确：弱 ruò，意思是力量小、不强壮。"}, {"text": "做", "is_correct": false, "explanation": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是做事。"}, {"text": "座", "is_correct": false, "explanation": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是座位。"}, {"text": "硕", "is_correct": false, "explanation": "shuò（第四声）与 ruò 声母不同（sh 与 r），意思是大。"}], "explanations": {"弱": "正确：弱 ruò，意思是力量小、不强壮。", "做": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是做事。", "座": "zuò（第四声）与 ruò 声母不同（z 与 r），意思是座位。", "硕": "shuò（第四声）与 ruò 声母不同（sh 与 r），意思是大。"}, "sentence_index": null, "correct_answer": "弱"}, "level_3": {"options": [{"text": "弱", "is_correct": true, "explanation": "正确：“前强后弱”指先强后弱，“弱”与“强”相对。"}, {"text": "小", "is_correct": false, "explanation": "搭配：“前……后……”说状态的对比，不用“小”。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”不表示力量状态，前后对比不成立。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线，不用来形容球队的实力。"}], "explanations": {"弱": "正确：“前强后弱”指先强后弱，“弱”与“强”相对。", "小": "搭配：“前……后……”说状态的对比，不用“小”。", "高": "语义：“高”不表示力量状态，前后对比不成立。", "亮": "搭配：“亮”形容光线，不用来形容球队的实力。"}, "sentence_index": 6, "correct_answer": "弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的人数很弱，只有十个人。", "explanation": "这里应该用〈少〉。描述人数多少用“少”，“弱”指力量小。"}, {"text": "他写字的速度很弱，半天写不完。", "explanation": "这里应该用〈慢〉。描述速度快慢用“慢”，“弱”指力量小。"}, {"text": "这个房间很弱，放了十张床。", "explanation": "这里应该用〈大〉。描述房间面积用“大”，“弱”指力量小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的力量弱很，搬不动东西。", "corrected_sentence": "他的力量弱得很，搬不动东西。", "error_description": "“弱得很”是带补语的结构，“得”不能省，应说“弱得很”，不能说“弱很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一支很弱球队。", "corrected_sentence": "这是一支很弱的球队。", "error_description": "“很弱”修饰名词时要用“的”：应说“很弱的球队”，不能说“很弱球队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79ecf5c-5410-4911-8680-f65e8db16a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
