INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95063, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "后悔是做完以后，觉得不应该这样做。", "primary_collocate": null, "pronunciation": "hòu huǐ", "ipa": "xoʊ˥˩ xweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "买了这件衣服，我有点后悔。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他后悔来这么早。", "target_word": "后悔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃完了才后悔吃太多。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要做让自己后悔的事。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我后悔没带伞，雨太大了。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说她不后悔离开那家公司。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人后悔借钱给朋友。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在后悔，已经太晚了。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花光了钱，后来很后悔。", "target_word": "后悔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你现在后悔吗？", "target_word": "后悔", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "后悔了", "label": "体标"}, {"form": "后悔过", "label": "体标"}, {"form": "后悔药", "label": "复合"}, {"form": "後悔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做完以后觉得不该这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21944ec0-25a1-4e3d-9f77-8f4f59681f20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后悔", "is_correct": true, "explanation": "正确。“后悔”表示做完以后觉得不该这样做，与“买了这件衣服”相合。"}, {"text": "预订", "is_correct": false, "explanation": "语义：“预订”是买之前的事，与句中“买了”已经完成的动作冲突。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需要带宾语（感谢某人或某事），“我有点”之后没有合适的宾语，句子不成立。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身去某地，表达不了买衣服之后的心理感受，句意不通。"}], "explanations": {"后悔": "正确。“后悔”表示做完以后觉得不该这样做，与“买了这件衣服”相合。", "预订": "语义：“预订”是买之前的事，与句中“买了”已经完成的动作冲突。", "感谢": "配价：“感谢”需要带宾语（感谢某人或某事），“我有点”之后没有合适的宾语，句子不成立。", "出发": "语义：“出发”指动身去某地，表达不了买衣服之后的心理感受，句意不通。"}, "sentence_index": 0, "correct_answer": "后悔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我常常后悔小时候的夏天。", "explanation": "这里应该用〈怀念〉。后悔指对自己做过的事感到懊恼；对小时候的夏天应该说怀念。"}, {"text": "学生都后悔这些老师。", "explanation": "这里应该用〈感激〉。后悔的对象是自己做过的事，对别人的教导要用感激。"}, {"text": "我真心后悔你的成功。", "explanation": "这里应该用〈祝贺〉。后悔针对自己做过的事，对别人的成功要用祝贺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后悔", "is_correct": true, "explanation": "正确。“后悔”表示对已经做过的事感到懊恼，与“借钱给朋友”相合。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”接的是喜事，不能和“借钱给朋友”这种行为搭配。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”是去看地方或展览，不能表示借钱这件事。"}, {"text": "咨询", "is_correct": false, "explanation": "搭配：“咨询”接的是问题或意见，不能接“借钱给朋友”这种行为。"}], "explanations": {"后悔": "正确。“后悔”表示对已经做过的事感到懊恼，与“借钱给朋友”相合。", "祝贺": "搭配：“祝贺”接的是喜事，不能和“借钱给朋友”这种行为搭配。", "参观": "语义：“参观”是去看地方或展览，不能表示借钱这件事。", "咨询": "搭配：“咨询”接的是问题或意见，不能接“借钱给朋友”这种行为。"}, "sentence_index": 6, "correct_answer": "后悔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很后悔明天会下雨。", "explanation": "这里应该用〈担心〉。后悔指对已经做过的事感到懊恼，明天的天气还没有发生，只能说担心。"}, {"text": "我们都后悔这些新同学。", "explanation": "这里应该用〈欢迎〉。后悔针对自己做过的事，对新来的同学要用欢迎，不能说后悔这些新同学。"}, {"text": "他们在山上后悔风景。", "explanation": "这里应该用〈欣赏〉。后悔的对象是自己做过的事，对风景要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那是我最后悔一件事。", "corrected_sentence": "那是我最后悔的一件事。", "error_description": "“后悔”修饰后面的名词“一件事”时，中间要加“的”，应说“最后悔的一件事”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他借钱给朋友以后，后悔很。", "corrected_sentence": "他借钱给朋友以后，后悔得很。", "error_description": "错误：「后悔」后面作程度补语时，要加助词「得」，应说「后悔得很」，不说「后悔很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06d94915-20bc-43b4-a99f-f7a049f83d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
