INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95066, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某事物所处的地点。", "primary_collocate": null, "pronunciation": "suǒ zài dì", "ipa": "swo˨˩˦ tsaɪ˥˩ ti˥˩", "syllable_count": 3, "sentences": [{"text": "大学的所在地是一座小城市。", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道总部的所在地吗？", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上有没有标出银行的所在地？", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的所在地在北京。", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的所在地靠近江边。", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在表格里写上工作单位的所在地。", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬到了博物馆的所在地附近。", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政府所在地不是最大的城市。", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的所在地离车站不远。", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店的所在地很容易找。", "target_word": "所在地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "机构或建筑所处的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee0abe9c-383b-4465-adda-6a9bff074073') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所在地", "is_correct": true, "explanation": "所在地：大学所处的地点，与“是一座小城市”相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不是一座城市，句意不通。"}, {"text": "校长", "is_correct": false, "explanation": "语义：校长是人，不能说是一座城市。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的身材，不是地点，不能说大学的身高是一座城市。"}], "explanations": {"所在地": "所在地：大学所处的地点，与“是一座小城市”相符。", "学生": "语义：学生是人，不是一座城市，句意不通。", "校长": "语义：校长是人，不能说是一座城市。", "身高": "语义：“身高”指人的身材，不是地点，不能说大学的身高是一座城市。"}, "sentence_index": 0, "correct_answer": "所在地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司新来了一名所在地。", "explanation": "这里应该用〈员工〉。“所在地”指地点，不指人，不能用来指新来的人，“公司新来了一名员工”才对。"}, {"text": "这家公司的所在地是王先生。", "explanation": "这里应该用〈老板〉。“所在地”指机构所处的地点，不能用来指人，“这家公司的老板是王先生”才对。"}, {"text": "这家公司的所在地是1998年。", "explanation": "这里应该用〈成立时间〉。“所在地”指地点，不能用来表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所在地", "is_correct": true, "explanation": "所在地：博物馆所处的地点，可以说“搬到…附近”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是地点，不能说搬到“价格”附近。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是地点，不能说搬到“年龄”附近。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是地点，不能说搬到「时间」附近。"}], "explanations": {"所在地": "所在地：博物馆所处的地点，可以说“搬到…附近”。", "价格": "语义：价格不是地点，不能说搬到“价格”附近。", "年龄": "语义：年龄不是地点，不能说搬到“年龄”附近。", "时间": "语义：时间不是地点，不能说搬到「时间」附近。"}, "sentence_index": 6, "correct_answer": "所在地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在班里的所在地是班长。", "explanation": "这里应该用〈职位〉。“所在地”指地点，不能用来表示人在班里的职位，“他在班里的职位是班长”才对。"}, {"text": "这次展览的所在地是周末。", "explanation": "这里应该用〈时间〉。“所在地”指地点，不能用来表示时间，“这次展览的时间是周末”才对。"}, {"text": "这部电影的所在地是张艺谋。", "explanation": "这里应该用〈导演〉。“所在地”指地点，不能用来指人，“这部电影的导演是张艺谋”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院的所在地上海。", "corrected_sentence": "这家医院的所在地是上海。", "error_description": "缺少动词“是”：说明所在地是哪里时，要说“所在地是某地”，不能直接接地名。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座图书馆的所在地河边。", "corrected_sentence": "这座图书馆的所在地在河边。", "error_description": "缺少动词“在”：说明地点时要说“所在地在某处”，不能省略“在”直接接地名。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c021f814-7f9b-4430-8829-5cdce2863511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
