INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95069, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持有是手里拿着或有。", "primary_collocate": null, "pronunciation": "chí yǒu", "ipa": "ʈʂʰɻ̩˧˥ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "持有门票的客人可以从左边进去。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请持有会员卡的客人到前台。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他持有一张去北京的火车票。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门时请出示您持有的证件。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她手里持有一张去上海的机票。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有持有邀请卡的人才能进会场。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里持有一把钥匙，却不知道能开哪扇门。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "持有优惠券的顾客今天可以便宜十块钱。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有持有过这种证件。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王持有两张音乐会的票，想请朋友一起去。", "target_word": "持有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "持有着", "label": "着（持续体）"}, {"form": "持有过", "label": "过（经历体）"}, {"form": "持有了", "label": "了（完成体）"}, {"form": "持有者", "label": "复合词"}, {"form": "持有人", "label": "复合词"}], "register": "书面", "sense_fingerprint": "持有：手里拿着、带着票证等凭证", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e60e0e-e792-48a1-bca2-90faf2e2bfb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持有", "is_correct": true, "explanation": "正确：“持有”指手里拿着或带着门票，与“持有门票的客人”一致。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是遗失，丢了门票的人不能凭票进场，与“可以进去”矛盾。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是售出，卖门票的是售票人员，不是凭票进场的客人。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：门票一般由检票员撕，“撕门票的客人”与凭票进场的语境不合。"}], "explanations": {"持有": "正确：“持有”指手里拿着或带着门票，与“持有门票的客人”一致。", "丢": "语义：“丢”是遗失，丢了门票的人不能凭票进场，与“可以进去”矛盾。", "卖": "语义：“卖”是售出，卖门票的是售票人员，不是凭票进场的客人。", "撕": "搭配：门票一般由检票员撕，“撕门票的客人”与凭票进场的语境不合。"}, "sentence_index": 0, "correct_answer": "持有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她持有了一次考试。", "explanation": "这里应该用〈参加〉。“持有”指拿着或拥有物品、证件、财产，不能用于考试这类活动。"}, {"text": "我们持有了一次讨论。", "explanation": "这里应该用〈进行〉。“进行”用于讨论、比赛等活动；“持有”只用于物品、证件、财产。"}, {"text": "老师持有了一个故事。", "explanation": "这里应该用〈讲〉。“讲故事”的动作不是持有；“持有”用于物品、证件、财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持有", "is_correct": true, "explanation": "正确：“持有”表示手里拿着钥匙，与“却不知道能开哪扇门”的语境相合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，扔掉了钥匙，就不会还琢磨它能开哪扇门。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是赠予或递送，“手里送一把钥匙”不通，句子说的是他仍拿着钥匙。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能搭配钥匙，句子说的是手里拿着一把钥匙。"}], "explanations": {"持有": "正确：“持有”表示手里拿着钥匙，与“却不知道能开哪扇门”的语境相合。", "扔": "语义：“扔”是丢弃，扔掉了钥匙，就不会还琢磨它能开哪扇门。", "送": "语义：“送”是赠予或递送，“手里送一把钥匙”不通，句子说的是他仍拿着钥匙。", "吃": "搭配：“吃”不能搭配钥匙，句子说的是手里拿着一把钥匙。"}, "sentence_index": 6, "correct_answer": "持有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案持有三个优点。", "explanation": "这里应该用〈具有〉。“持有”指手里拿着或拥有票证、财产；说优点、特点等抽象内容要用“具有”。"}, {"text": "这位同学持有良好的沟通能力。", "explanation": "这里应该用〈具备〉。“具备”指拥有某种能力或条件，“持有”不用于能力。"}, {"text": "这个城市持有很高的声誉。", "explanation": "这里应该用〈享有〉。“享有”指得到声誉、权利等，“持有”用于证件、票证、财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前从没持有了这种票。", "corrected_sentence": "我以前从没持有过这种票。", "error_description": "体标错误：“从没”之后表示经历要用“过”，不能用完成体“了”，应说“从没持有过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷在持有一张老照片，每天都要拿出来看。", "corrected_sentence": "爷爷持有一张老照片，每天都要拿出来看。", "error_description": "状态动词误用：“持有”是状态动词，不能加“在”表示进行，应说“爷爷持有一张老照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16dcdeb9-61f9-472a-9708-f012839813a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
