INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占有，占据。", "primary_collocate": null, "pronunciation": "jù yǒu", "ipa": "tɕy˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家据有大片肥沃的土地。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们据有这座城市已经三年。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店据有街角最好的位置。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队据有了山上的高地。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人据有着河边所有的码头。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想据有这块地，可是别人不卖。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家大公司据有了一半的市场。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们据有了村口的那片空地。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家据有村里最好的水田。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的王常据有大片山林。", "target_word": "据有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "据有了", "label": "体标"}, {"form": "据有着", "label": "体标"}], "register": "书面", "sense_fingerprint": "据有：占有，占据某地或某种位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56189473-a491-472b-a780-7b2e60a5ec1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "据有", "is_correct": true, "explanation": "正确。“据有”表示占有大片土地。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的宾语是饮料，土地不能喝。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能说穿土地。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”的宾语是帽子、眼镜等，不能说戴土地。"}], "explanations": {"据有": "正确。“据有”表示占有大片土地。", "喝": "语义：“喝”的宾语是饮料，土地不能喝。", "穿": "搭配：“穿”的宾语是衣物，不能说穿土地。", "戴": "搭配：“戴”的宾语是帽子、眼镜等，不能说戴土地。"}, "sentence_index": 0, "correct_answer": "据有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他据有了一封信。", "explanation": "这里应该用〈收到〉。据有指占有或占据，收到信件不能说据有。"}, {"text": "他据有了英语。", "explanation": "这里应该用〈掌握〉。据有指占住地方，不能用于语言或技能。"}, {"text": "他据有很多经验。", "explanation": "这里应该用〈积累〉。据有指占住地方，经验要慢慢积累，不能说据有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "据有", "is_correct": true, "explanation": "正确。“据有”表示占有一半的市场。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的宾语是饮料，市场不能喝。"}, {"text": "举", "is_correct": false, "explanation": "搭配：“举”的宾语多是具体物体，不能说举市场。"}, {"text": "晒", "is_correct": false, "explanation": "语义：市场不能被晒，与句意不合。"}], "explanations": {"据有": "正确。“据有”表示占有一半的市场。", "喝": "语义：“喝”的宾语是饮料，市场不能喝。", "举": "搭配：“举”的宾语多是具体物体，不能说举市场。", "晒": "语义：市场不能被晒，与句意不合。"}, "sentence_index": 6, "correct_answer": "据有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学校据有一场比赛。", "explanation": "这里不能用〈据有〉，误把它当成“举办”的意思。据有指占有或占据，比赛要说举办。"}, {"text": "我据有一个好消息。", "explanation": "这里不能用〈据有〉，误把它当成“得到、收到”的意思。据有指占有或占据，消息要说得到或听到。"}, {"text": "这首歌据有很多朋友。", "explanation": "这里不能用〈据有〉，误把它当成“赢得、吸引”的意思。据有指占有或占据，歌曲应说有很多听众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeea166e-9333-4922-aced-f20f32878a67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
