INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95077, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "会谈是两边的人坐下来谈事情。", "primary_collocate": null, "pronunciation": "huì tán", "ipa": "xweɪ˥˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "这次会谈开了三个小时。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人的会谈很顺利。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天上午有一场重要的会谈。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会谈结束后，双方都很满意。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统欢迎来访的客人参加会谈。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会谈的地点在北京。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国举行了第三次会谈。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会谈中，双方都说了自己的想法。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的会谈气氛很好，大家都笑着。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有参加昨天的会谈。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "會談", "label": "繁体"}], "register": "正式", "sense_fingerprint": "名词：双方坐下来谈事情的一次活动，如举行会谈、参加会谈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95077, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会谈", "is_correct": true, "explanation": "正确：“会谈”是一次有时长的商谈活动，可以说“开”三个小时。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是物体，不是活动，不能“开”三个小时。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”与“开”不搭配，下雨要说“下”，不说“开”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不是能持续几个小时的活动。"}], "explanations": {"会谈": "正确：“会谈”是一次有时长的商谈活动，可以说“开”三个小时。", "石头": "语义：“石头”是物体，不是活动，不能“开”三个小时。", "雨": "搭配：“雨”与“开”不搭配，下雨要说“下”，不说“开”。", "书包": "语义：“书包”是物品，不是能持续几个小时的活动。"}, "sentence_index": 0, "correct_answer": "会谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校请来专家做了一场会谈，同学们都认真地听。", "explanation": "这里应该用〈讲座〉。会谈是双方坐下来商谈，一人讲、众人听的活动要用“讲座”。"}, {"text": "周六晚上，我们几个朋友开了一场会谈，玩得很开心。", "explanation": "这里应该用〈聚会〉。会谈是正式的双方商谈，朋友聚在一起玩不用“会谈”。"}, {"text": "我和弟弟为了一块蛋糕在厨房里发生了一场会谈，声音很大。", "explanation": "这里应该用〈争吵〉。会谈是有秩序的正式商谈，吵架不用“会谈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会谈", "is_correct": true, "explanation": "正确：“会谈”是一次正式商谈活动，两国可以举行第三次会谈。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是活动，不能被“举行”为第三次。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“午饭”是吃的，不能说“举行第三次午饭”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然状态，不能被“举行”为一次活动。"}], "explanations": {"会谈": "正确：“会谈”是一次正式商谈活动，两国可以举行第三次会谈。", "天空": "语义：“天空”不是活动，不能被“举行”为第三次。", "午饭": "搭配：“午饭”是吃的，不能说“举行第三次午饭”。", "天气": "语义：“天气”是自然状态，不能被“举行”为一次活动。"}, "sentence_index": 6, "correct_answer": "会谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两队昨晚进行了一场会谈，比分是三比一。", "explanation": "这里应该用〈比赛〉。会谈是双方坐下来商谈，体育竞赛要用“比赛”。"}, {"text": "我们班昨天进行了一场会谈，老师一共出了十道题，大家都很紧张。", "explanation": "这里应该用〈考试〉。会谈是商谈活动，课堂测验要用“考试”。"}, {"text": "剧团昨晚在剧院进行了一场会谈，观众很喜欢。", "explanation": "这里应该用〈演出〉。会谈是双方商谈，舞台表演要用“演出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国代表在北京吃了会谈。", "corrected_sentence": "两国代表在北京进行了会谈。", "error_description": "“吃”不能与“会谈”搭配；“会谈”前应用“进行”或“举行”，应说“进行了会谈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国举行了一台会谈。", "corrected_sentence": "两国举行了一场会谈。", "error_description": "“会谈”的量词应用“场”或“次”，“台”多用于机器、晚会等，不能修饰“会谈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
