INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95078, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方或多方就某问题进行正式商谈。", "primary_collocate": null, "pronunciation": "huì tán", "ipa": "xweɪ˥˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "两国领导人明天在北京会谈。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方代表今天上午会谈了三个小时。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国总理和美国总统会谈过两次。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司的老板正在就合作的事会谈。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在会议室里会谈，请别进去。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外交部长要和对方代表会谈，讨论边界问题。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会代表和公司老板会谈，希望提高工资。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三国首脑下个月将在日内瓦会谈。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们会谈了很久，最后还是没有结果。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的外长昨天会谈，主要谈贸易问题。", "target_word": "会谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "会谈了", "label": "体标"}, {"form": "会谈过", "label": "体标"}, {"form": "會談", "label": "繁体"}], "register": "正式", "sense_fingerprint": "动词：双方或多方就某问题正式商谈，如两国领导人会谈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d21fd02-94af-431a-bf66-245fcefabcc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会谈", "is_correct": true, "explanation": "正确：“会谈”指双方或多方就某问题正式商谈，两国领导人明天在北京的正式活动正是这个意思。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”是躲开、离开，不是正式商谈，与两国领导人的正式活动不合。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”需要带宾语（拥有什么），句中缺少宾语，不成立。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指两人成为夫妻，与两国领导人的正式活动毫不相干。"}], "explanations": {"会谈": "正确：“会谈”指双方或多方就某问题正式商谈，两国领导人明天在北京的正式活动正是这个意思。", "逃跑": "语义：“逃跑”是躲开、离开，不是正式商谈，与两国领导人的正式活动不合。", "拥有": "配价：“拥有”需要带宾语（拥有什么），句中缺少宾语，不成立。", "结婚": "语义：“结婚”指两人成为夫妻，与两国领导人的正式活动毫不相干。"}, "sentence_index": 0, "correct_answer": "会谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和室友晚上在宿舍里会谈了很久。", "explanation": "这里应该用〈聊天〉。会谈指双方或多方的正式商谈，宿舍里的闲聊不用“会谈”。"}, {"text": "我和同学在教室里会谈了一个笑话，大家笑个不停。", "explanation": "这里应该用〈讲〉。会谈是双方就问题正式商谈，讲笑话要用“讲”。"}, {"text": "我和老同学昨天在咖啡馆会谈了一下午。", "explanation": "这里应该用〈叙旧〉。会谈是正式的双方商谈，老朋友之间回忆往事、闲聊要用“叙旧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会谈", "is_correct": true, "explanation": "正确：工会代表与公司老板双方正式商谈加薪的事，用“会谈”。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“希望提高工资”的商谈意图矛盾，不能用来描述双方的交涉。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与提高工资的诉求没有关系，不能表示为此进行的商谈。"}, {"text": "分享", "is_correct": false, "explanation": "语义：“分享”指与人共享，不是就加薪问题进行商谈，不能替换“会谈”。"}], "explanations": {"会谈": "正确：工会代表与公司老板双方正式商谈加薪的事，用“会谈”。", "睡觉": "语义：“睡觉”与“希望提高工资”的商谈意图矛盾，不能用来描述双方的交涉。", "唱歌": "语义：“唱歌”与提高工资的诉求没有关系，不能表示为此进行的商谈。", "分享": "语义：“分享”指与人共享，不是就加薪问题进行商谈，不能替换“会谈”。"}, "sentence_index": 6, "correct_answer": "会谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个孩子为了玩具在院子里会谈起来。", "explanation": "这里应该用〈争吵〉。会谈是正式商谈，孩子之间的争吵不用“会谈”。"}, {"text": "我向老师会谈这道题。", "explanation": "这里应该用〈请教〉。会谈是双方正式商谈，向老师求教要说“请教”。"}, {"text": "他一直在会谈自己的委屈，大家都劝他别再说了。", "explanation": "这里应该用〈诉说〉。会谈是正式的双方商谈，向别人说出委屈要用“诉说”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国代表明天给对方会谈。", "corrected_sentence": "两国代表明天和对方会谈。", "error_description": "“会谈”引出对象时要用介词“和”（或“跟”），“给”表示给予，不能说“给对方会谈”，应说“和对方会谈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国外长下周三会谈过。", "corrected_sentence": "两国外长下周三会谈。", "error_description": "“过”表示已经经历过的动作，用在“下周三”这样的将来时间里不对，应去掉“过”，说“下周三会谈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d537595-a683-4614-aa77-e213f58cb469') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
