INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "欠是拿了别人的东西，还没还。", "primary_collocate": null, "pronunciation": "qiàn", "ipa": "tɕʰjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "我欠他一百块钱。", "target_word": "欠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他欠了朋友很多钱，还没还。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你欠我的书，什么时候还？", "target_word": "欠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我欠同学一本书，明天还他。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他欠过房租，后来都还了。", "target_word": "欠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我欠哥哥两百块，下个月还。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别欠别人的东西，要快点还。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她欠我一杯咖啡。", "target_word": "欠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "欠了钱就要还，这是应该的。", "target_word": "欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他欠着银行的钱，每个月还一点。", "target_word": "欠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欠了", "label": "体标"}, {"form": "欠过", "label": "体标"}, {"form": "欠着", "label": "体标"}, {"form": "欠钱", "label": "复合"}, {"form": "欠债", "label": "复合"}], "register": "中性", "sense_fingerprint": "欠：拿了别人的钱或东西，还没有归还", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee0abe9c-383b-4465-adda-6a9bff074073') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
